     !> Given a 3-by-3 matrix pencil (A,B), SLAQZ1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (A - (beta2*sr2 - i*si)*B)*B^(-1)*(beta1*A - (sr2 + i*si2)*B)*B^(-1).
     !> It is assumed that either
     !> 1) sr1 = sr2
     !> or
     !> 2) si = 0.
     !> This is useful for starting double implicit shift bulges
     !> in the QZ algorithm.

     pure subroutine la_slaqz1(a,lda,b,ldb,sr1,sr2,si,beta1,beta2,v)
        use la_constants_sp,only:zero,one
           ! arguments
           integer(ilp),intent(in) :: lda,ldb
           real(sp),intent(in) :: a(lda,*),b(ldb,*),sr1,sr2,si,beta1,beta2
           real(sp),intent(out) :: v(*)

           ! local scalars
           real(sp) :: w(2),safmin,safmax,scale1,scale2
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           ! calculate first shifted vector
           w(1) = beta1*a(1,1) - sr1*b(1,1)
           w(2) = beta1*a(2,1) - sr1*b(2,1)
           scale1 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale1 >= safmin .and. scale1 <= safmax) then
              w(1) = w(1)/scale1
              w(2) = w(2)/scale1
           end if
           ! solve linear system
           w(2) = w(2)/b(2,2)
           w(1) = (w(1) - b(1,2)*w(2))/b(1,1)
           scale2 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale2 >= safmin .and. scale2 <= safmax) then
              w(1) = w(1)/scale2
              w(2) = w(2)/scale2
           end if
           ! apply second shift
           v(1) = beta2*(a(1,1)*w(1) + a(1,2)*w(2)) - sr2*(b(1,1)*w(1) + b(1,2)*w( &
                      2))
           v(2) = beta2*(a(2,1)*w(1) + a(2,2)*w(2)) - sr2*(b(2,1)*w(1) + b(2,2)*w( &
                      2))
           v(3) = beta2*(a(3,1)*w(1) + a(3,2)*w(2)) - sr2*(b(3,1)*w(1) + b(3,2)*w( &
                      2))
           ! account for imaginary part
           v(1) = v(1) + si*si*b(1,1)/scale1/scale2
           ! check for overflow
           if (abs(v(1)) > safmax .or. abs(v(2)) > safmax .or. abs(v(3)) > safmax .or. &
           la_sisnan(v(1)) .or. la_sisnan(v(2)) .or. la_sisnan(v(3))) &
                     then
              v(1) = zero
              v(2) = zero
              v(3) = zero
           end if
     end subroutine la_slaqz1
     !> Given a 3-by-3 matrix pencil (A,B), DLAQZ1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (A - (beta2*sr2 - i*si)*B)*B^(-1)*(beta1*A - (sr2 + i*si2)*B)*B^(-1).
     !> It is assumed that either
     !> 1) sr1 = sr2
     !> or
     !> 2) si = 0.
     !> This is useful for starting double implicit shift bulges
     !> in the QZ algorithm.

     pure subroutine la_dlaqz1(a,lda,b,ldb,sr1,sr2,si,beta1,beta2,v)
        use la_constants_dp,only:zero,one
           ! arguments
           integer(ilp),intent(in) :: lda,ldb
           real(dp),intent(in) :: a(lda,*),b(ldb,*),sr1,sr2,si,beta1,beta2
           real(dp),intent(out) :: v(*)

           ! local scalars
           real(dp) :: w(2),safmin,safmax,scale1,scale2
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           ! calculate first shifted vector
           w(1) = beta1*a(1,1) - sr1*b(1,1)
           w(2) = beta1*a(2,1) - sr1*b(2,1)
           scale1 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale1 >= safmin .and. scale1 <= safmax) then
              w(1) = w(1)/scale1
              w(2) = w(2)/scale1
           end if
           ! solve linear system
           w(2) = w(2)/b(2,2)
           w(1) = (w(1) - b(1,2)*w(2))/b(1,1)
           scale2 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale2 >= safmin .and. scale2 <= safmax) then
              w(1) = w(1)/scale2
              w(2) = w(2)/scale2
           end if
           ! apply second shift
           v(1) = beta2*(a(1,1)*w(1) + a(1,2)*w(2)) - sr2*(b(1,1)*w(1) + b(1,2)*w( &
                      2))
           v(2) = beta2*(a(2,1)*w(1) + a(2,2)*w(2)) - sr2*(b(2,1)*w(1) + b(2,2)*w( &
                      2))
           v(3) = beta2*(a(3,1)*w(1) + a(3,2)*w(2)) - sr2*(b(3,1)*w(1) + b(3,2)*w( &
                      2))
           ! account for imaginary part
           v(1) = v(1) + si*si*b(1,1)/scale1/scale2
           ! check for overflow
           if (abs(v(1)) > safmax .or. abs(v(2)) > safmax .or. abs(v(3)) > safmax .or. &
           la_disnan(v(1)) .or. la_disnan(v(2)) .or. la_disnan(v(3))) &
                     then
              v(1) = zero
              v(2) = zero
              v(3) = zero
           end if
     end subroutine la_dlaqz1
