     !> Given a 3-by-3 matrix pencil (A,B), QLAQZ1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (A - (beta2*sr2 - i*si)*B)*B^(-1)*(beta1*A - (sr2 + i*si2)*B)*B^(-1).
     !> It is assumed that either
     !> 1) sr1 = sr2
     !> or
     !> 2) si = 0.
     !> This is useful for starting double implicit shift bulges
     !> in the QZ algorithm.

     pure subroutine la_qlaqz1(a,lda,b,ldb,sr1,sr2,si,beta1,beta2,v)
        use la_constants_qp,only:zero,one
           ! arguments
           integer(ilp),intent(in) :: lda,ldb
           real(qp),intent(in) :: a(lda,*),b(ldb,*),sr1,sr2,si,beta1,beta2
           real(qp),intent(out) :: v(*)

           ! local scalars
           real(qp) :: w(2),safmin,safmax,scale1,scale2
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           ! calculate first shifted vector
           w(1) = beta1*a(1,1) - sr1*b(1,1)
           w(2) = beta1*a(2,1) - sr1*b(2,1)
           scale1 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale1 >= safmin .and. scale1 <= safmax) then
              w(1) = w(1)/scale1
              w(2) = w(2)/scale1
           end if
           ! solve linear system
           w(2) = w(2)/b(2,2)
           w(1) = (w(1) - b(1,2)*w(2))/b(1,1)
           scale2 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale2 >= safmin .and. scale2 <= safmax) then
              w(1) = w(1)/scale2
              w(2) = w(2)/scale2
           end if
           ! apply second shift
           v(1) = beta2*(a(1,1)*w(1) + a(1,2)*w(2)) - sr2*(b(1,1)*w(1) + b(1,2)*w( &
                      2))
           v(2) = beta2*(a(2,1)*w(1) + a(2,2)*w(2)) - sr2*(b(2,1)*w(1) + b(2,2)*w( &
                      2))
           v(3) = beta2*(a(3,1)*w(1) + a(3,2)*w(2)) - sr2*(b(3,1)*w(1) + b(3,2)*w( &
                      2))
           ! account for imaginary part
           v(1) = v(1) + si*si*b(1,1)/scale1/scale2
           ! check for overflow
           if (abs(v(1)) > safmax .or. abs(v(2)) > safmax .or. abs(v(3)) > safmax .or. &
           la_qisnan(v(1)) .or. la_qisnan(v(2)) .or. la_qisnan(v(3))) &
                     then
              v(1) = zero
              v(2) = zero
              v(3) = zero
           end if
     end subroutine la_qlaqz1
#endif

     !> SLAQZ2: chases a 2x2 shift bulge in a matrix pencil down a single position

     pure subroutine la_slaqz2(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_sp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           real(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(sp) :: h(2,3),c1,s1,c2,s2,temp
           if (k + 2 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              h = b(ihi - 1:ihi,ihi - 2:ihi)
              ! make h upper triangular
              call la_slartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_srot(2,h(1,2),2,h(2,2),2,c1,s1)
              call la_slartg(h(2,3),h(2,2),c1,s1,temp)
              call la_srot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_slartg(h(1,2),h(1,1),c2,s2,temp)
              call la_srot(ihi - istartm + 1,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1, &
                        s1)
              call la_srot(ihi - istartm + 1,b(istartm,ihi - 1),1,b(istartm,ihi - 2),1,c2, &
                        s2)
              b(ihi - 1,ihi - 2) = zero
              b(ihi,ihi - 2) = zero
              call la_srot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              call la_srot(ihi - istartm + 1,a(istartm,ihi - 1),1,a(istartm,ihi - 2),1,c2, &
                        s2)
              if (ilz) then
                 call la_srot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
                 call la_srot(nz,z(1,ihi - 1 - zstart + 1),1,z(1,ihi - 2 - zstart + 1),1,c2, &
                           s2)
              end if
              call la_slartg(a(ihi - 1,ihi - 2),a(ihi,ihi - 2),c1,s1,temp)
              a(ihi - 1,ihi - 2) = temp
              a(ihi,ihi - 2) = zero
              call la_srot(istopm - ihi + 2,a(ihi - 1,ihi - 1),lda,a(ihi,ihi - 1),lda,c1,s1 &
                        )
              call la_srot(istopm - ihi + 2,b(ihi - 1,ihi - 1),ldb,b(ihi,ihi - 1),ldb,c1,s1 &
                        )
              if (ilq) then
                 call la_srot(nq,q(1,ihi - 1 - qstart + 1),1,q(1,ihi - qstart + 1),1,c1,s1 &
                           )
              end if
              call la_slartg(b(ihi,ihi),b(ihi,ihi - 1),c1,s1,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = zero
              call la_srot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1,s1)

              call la_srot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              if (ilz) then
                 call la_srot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
              end if
           else
              ! normal operation, move bulge down
              h = b(k + 1:k + 2,k:k + 2)
              ! make h upper triangular
              call la_slartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_srot(2,h(1,2),2,h(2,2),2,c1,s1)
              ! calculate z1 and z2
              call la_slartg(h(2,3),h(2,2),c1,s1,temp)
              call la_srot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_slartg(h(1,2),h(1,1),c2,s2,temp)
              ! apply transformations from the right
              call la_srot(k + 3 - istartm + 1,a(istartm,k + 2),1,a(istartm,k + 1),1,c1,s1)

              call la_srot(k + 3 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c2,s2)

              call la_srot(k + 2 - istartm + 1,b(istartm,k + 2),1,b(istartm,k + 1),1,c1,s1)

              call la_srot(k + 2 - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c2,s2)

              if (ilz) then
                 call la_srot(nz,z(1,k + 2 - zstart + 1),1,z(1,k + 1 - zstart + 1),1,c1,s1)

                 call la_srot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c2,s2)

              end if
              b(k + 1,k) = zero
              b(k + 2,k) = zero
              ! calculate q1 and q2
              call la_slartg(a(k + 2,k),a(k + 3,k),c1,s1,temp)
              a(k + 2,k) = temp
              a(k + 3,k) = zero
              call la_slartg(a(k + 1,k),a(k + 2,k),c2,s2,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = zero
              ! apply transformations from the left
              call la_srot(istopm - k,a(k + 2,k + 1),lda,a(k + 3,k + 1),lda,c1,s1)
              call la_srot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c2,s2)
              call la_srot(istopm - k,b(k + 2,k + 1),ldb,b(k + 3,k + 1),ldb,c1,s1)
              call la_srot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c2,s2)
              if (ilq) then
                 call la_srot(nq,q(1,k + 2 - qstart + 1),1,q(1,k + 3 - qstart + 1),1,c1,s1)

                 call la_srot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c2,s2)

              end if
           end if
     end subroutine la_slaqz2
     !> DLAQZ2: chases a 2x2 shift bulge in a matrix pencil down a single position

     pure subroutine la_dlaqz2(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_dp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           real(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(dp) :: h(2,3),c1,s1,c2,s2,temp
           if (k + 2 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              h = b(ihi - 1:ihi,ihi - 2:ihi)
              ! make h upper triangular
              call la_dlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_drot(2,h(1,2),2,h(2,2),2,c1,s1)
              call la_dlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_drot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_dlartg(h(1,2),h(1,1),c2,s2,temp)
              call la_drot(ihi - istartm + 1,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1, &
                        s1)
              call la_drot(ihi - istartm + 1,b(istartm,ihi - 1),1,b(istartm,ihi - 2),1,c2, &
                        s2)
              b(ihi - 1,ihi - 2) = zero
              b(ihi,ihi - 2) = zero
              call la_drot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              call la_drot(ihi - istartm + 1,a(istartm,ihi - 1),1,a(istartm,ihi - 2),1,c2, &
                        s2)
              if (ilz) then
                 call la_drot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
                 call la_drot(nz,z(1,ihi - 1 - zstart + 1),1,z(1,ihi - 2 - zstart + 1),1,c2, &
                           s2)
              end if
              call la_dlartg(a(ihi - 1,ihi - 2),a(ihi,ihi - 2),c1,s1,temp)
              a(ihi - 1,ihi - 2) = temp
              a(ihi,ihi - 2) = zero
              call la_drot(istopm - ihi + 2,a(ihi - 1,ihi - 1),lda,a(ihi,ihi - 1),lda,c1,s1 &
                        )
              call la_drot(istopm - ihi + 2,b(ihi - 1,ihi - 1),ldb,b(ihi,ihi - 1),ldb,c1,s1 &
                        )
              if (ilq) then
                 call la_drot(nq,q(1,ihi - 1 - qstart + 1),1,q(1,ihi - qstart + 1),1,c1,s1 &
                           )
              end if
              call la_dlartg(b(ihi,ihi),b(ihi,ihi - 1),c1,s1,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = zero
              call la_drot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1,s1)

              call la_drot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              if (ilz) then
                 call la_drot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
              end if
           else
              ! normal operation, move bulge down
              h = b(k + 1:k + 2,k:k + 2)
              ! make h upper triangular
              call la_dlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_drot(2,h(1,2),2,h(2,2),2,c1,s1)
              ! calculate z1 and z2
              call la_dlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_drot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_dlartg(h(1,2),h(1,1),c2,s2,temp)
              ! apply transformations from the right
              call la_drot(k + 3 - istartm + 1,a(istartm,k + 2),1,a(istartm,k + 1),1,c1,s1)

              call la_drot(k + 3 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c2,s2)

              call la_drot(k + 2 - istartm + 1,b(istartm,k + 2),1,b(istartm,k + 1),1,c1,s1)

              call la_drot(k + 2 - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c2,s2)

              if (ilz) then
                 call la_drot(nz,z(1,k + 2 - zstart + 1),1,z(1,k + 1 - zstart + 1),1,c1,s1)

                 call la_drot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c2,s2)

              end if
              b(k + 1,k) = zero
              b(k + 2,k) = zero
              ! calculate q1 and q2
              call la_dlartg(a(k + 2,k),a(k + 3,k),c1,s1,temp)
              a(k + 2,k) = temp
              a(k + 3,k) = zero
              call la_dlartg(a(k + 1,k),a(k + 2,k),c2,s2,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = zero
              ! apply transformations from the left
              call la_drot(istopm - k,a(k + 2,k + 1),lda,a(k + 3,k + 1),lda,c1,s1)
              call la_drot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c2,s2)
              call la_drot(istopm - k,b(k + 2,k + 1),ldb,b(k + 3,k + 1),ldb,c1,s1)
              call la_drot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c2,s2)
              if (ilq) then
                 call la_drot(nq,q(1,k + 2 - qstart + 1),1,q(1,k + 3 - qstart + 1),1,c1,s1)

                 call la_drot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c2,s2)

              end if
           end if
     end subroutine la_dlaqz2
#ifdef LA_WITH_XDP
     !> XLAQZ2: chases a 2x2 shift bulge in a matrix pencil down a single position

     pure subroutine la_xlaqz2(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_xdp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           real(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(xdp) :: h(2,3),c1,s1,c2,s2,temp
           if (k + 2 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              h = b(ihi - 1:ihi,ihi - 2:ihi)
              ! make h upper triangular
              call la_xlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_xrot(2,h(1,2),2,h(2,2),2,c1,s1)
              call la_xlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_xrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_xlartg(h(1,2),h(1,1),c2,s2,temp)
              call la_xrot(ihi - istartm + 1,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1, &
                        s1)
              call la_xrot(ihi - istartm + 1,b(istartm,ihi - 1),1,b(istartm,ihi - 2),1,c2, &
                        s2)
              b(ihi - 1,ihi - 2) = zero
              b(ihi,ihi - 2) = zero
              call la_xrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              call la_xrot(ihi - istartm + 1,a(istartm,ihi - 1),1,a(istartm,ihi - 2),1,c2, &
                        s2)
              if (ilz) then
                 call la_xrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
                 call la_xrot(nz,z(1,ihi - 1 - zstart + 1),1,z(1,ihi - 2 - zstart + 1),1,c2, &
                           s2)
              end if
              call la_xlartg(a(ihi - 1,ihi - 2),a(ihi,ihi - 2),c1,s1,temp)
              a(ihi - 1,ihi - 2) = temp
              a(ihi,ihi - 2) = zero
              call la_xrot(istopm - ihi + 2,a(ihi - 1,ihi - 1),lda,a(ihi,ihi - 1),lda,c1,s1 &
                        )
              call la_xrot(istopm - ihi + 2,b(ihi - 1,ihi - 1),ldb,b(ihi,ihi - 1),ldb,c1,s1 &
                        )
              if (ilq) then
                 call la_xrot(nq,q(1,ihi - 1 - qstart + 1),1,q(1,ihi - qstart + 1),1,c1,s1 &
                           )
              end if
              call la_xlartg(b(ihi,ihi),b(ihi,ihi - 1),c1,s1,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = zero
              call la_xrot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1,s1)

              call la_xrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              if (ilz) then
                 call la_xrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
              end if
           else
              ! normal operation, move bulge down
              h = b(k + 1:k + 2,k:k + 2)
              ! make h upper triangular
              call la_xlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_xrot(2,h(1,2),2,h(2,2),2,c1,s1)
              ! calculate z1 and z2
              call la_xlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_xrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_xlartg(h(1,2),h(1,1),c2,s2,temp)
              ! apply transformations from the right
              call la_xrot(k + 3 - istartm + 1,a(istartm,k + 2),1,a(istartm,k + 1),1,c1,s1)

              call la_xrot(k + 3 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c2,s2)

              call la_xrot(k + 2 - istartm + 1,b(istartm,k + 2),1,b(istartm,k + 1),1,c1,s1)

              call la_xrot(k + 2 - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c2,s2)

              if (ilz) then
                 call la_xrot(nz,z(1,k + 2 - zstart + 1),1,z(1,k + 1 - zstart + 1),1,c1,s1)

                 call la_xrot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c2,s2)

              end if
              b(k + 1,k) = zero
              b(k + 2,k) = zero
              ! calculate q1 and q2
              call la_xlartg(a(k + 2,k),a(k + 3,k),c1,s1,temp)
              a(k + 2,k) = temp
              a(k + 3,k) = zero
              call la_xlartg(a(k + 1,k),a(k + 2,k),c2,s2,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = zero
              ! apply transformations from the left
              call la_xrot(istopm - k,a(k + 2,k + 1),lda,a(k + 3,k + 1),lda,c1,s1)
              call la_xrot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c2,s2)
              call la_xrot(istopm - k,b(k + 2,k + 1),ldb,b(k + 3,k + 1),ldb,c1,s1)
              call la_xrot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c2,s2)
              if (ilq) then
                 call la_xrot(nq,q(1,k + 2 - qstart + 1),1,q(1,k + 3 - qstart + 1),1,c1,s1)

                 call la_xrot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c2,s2)

              end if
           end if
     end subroutine la_xlaqz2
#endif
#ifdef LA_WITH_QP
     !> QLAQZ2: chases a 2x2 shift bulge in a matrix pencil down a single position

     pure subroutine la_qlaqz2(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_qp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(qp) :: h(2,3),c1,s1,c2,s2,temp
           if (k + 2 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              h = b(ihi - 1:ihi,ihi - 2:ihi)
              ! make h upper triangular
              call la_qlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_qrot(2,h(1,2),2,h(2,2),2,c1,s1)
              call la_qlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_qrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_qlartg(h(1,2),h(1,1),c2,s2,temp)
              call la_qrot(ihi - istartm + 1,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1, &
                        s1)
              call la_qrot(ihi - istartm + 1,b(istartm,ihi - 1),1,b(istartm,ihi - 2),1,c2, &
                        s2)
              b(ihi - 1,ihi - 2) = zero
              b(ihi,ihi - 2) = zero
              call la_qrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              call la_qrot(ihi - istartm + 1,a(istartm,ihi - 1),1,a(istartm,ihi - 2),1,c2, &
                        s2)
              if (ilz) then
                 call la_qrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
                 call la_qrot(nz,z(1,ihi - 1 - zstart + 1),1,z(1,ihi - 2 - zstart + 1),1,c2, &
                           s2)
              end if
              call la_qlartg(a(ihi - 1,ihi - 2),a(ihi,ihi - 2),c1,s1,temp)
              a(ihi - 1,ihi - 2) = temp
              a(ihi,ihi - 2) = zero
              call la_qrot(istopm - ihi + 2,a(ihi - 1,ihi - 1),lda,a(ihi,ihi - 1),lda,c1,s1 &
                        )
              call la_qrot(istopm - ihi + 2,b(ihi - 1,ihi - 1),ldb,b(ihi,ihi - 1),ldb,c1,s1 &
                        )
              if (ilq) then
                 call la_qrot(nq,q(1,ihi - 1 - qstart + 1),1,q(1,ihi - qstart + 1),1,c1,s1 &
                           )
              end if
              call la_qlartg(b(ihi,ihi),b(ihi,ihi - 1),c1,s1,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = zero
              call la_qrot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1,s1)

              call la_qrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              if (ilz) then
                 call la_qrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
              end if
           else
              ! normal operation, move bulge down
              h = b(k + 1:k + 2,k:k + 2)
              ! make h upper triangular
              call la_qlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_qrot(2,h(1,2),2,h(2,2),2,c1,s1)
              ! calculate z1 and z2
              call la_qlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_qrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_qlartg(h(1,2),h(1,1),c2,s2,temp)
              ! apply transformations from the right
              call la_qrot(k + 3 - istartm + 1,a(istartm,k + 2),1,a(istartm,k + 1),1,c1,s1)

              call la_qrot(k + 3 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c2,s2)

              call la_qrot(k + 2 - istartm + 1,b(istartm,k + 2),1,b(istartm,k + 1),1,c1,s1)

              call la_qrot(k + 2 - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c2,s2)

              if (ilz) then
                 call la_qrot(nz,z(1,k + 2 - zstart + 1),1,z(1,k + 1 - zstart + 1),1,c1,s1)

                 call la_qrot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c2,s2)

              end if
              b(k + 1,k) = zero
              b(k + 2,k) = zero
              ! calculate q1 and q2
              call la_qlartg(a(k + 2,k),a(k + 3,k),c1,s1,temp)
              a(k + 2,k) = temp
              a(k + 3,k) = zero
              call la_qlartg(a(k + 1,k),a(k + 2,k),c2,s2,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = zero
              ! apply transformations from the left
              call la_qrot(istopm - k,a(k + 2,k + 1),lda,a(k + 3,k + 1),lda,c1,s1)
              call la_qrot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c2,s2)
              call la_qrot(istopm - k,b(k + 2,k + 1),ldb,b(k + 3,k + 1),ldb,c1,s1)
              call la_qrot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c2,s2)
              if (ilq) then
                 call la_qrot(nq,q(1,k + 2 - qstart + 1),1,q(1,k + 3 - qstart + 1),1,c1,s1)

                 call la_qrot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c2,s2)

              end if
           end if
     end subroutine la_qlaqz2
#endif

     !> SLAQZ4: Executes a single multishift QZ sweep

     pure subroutine la_slaqz4(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,sr, &
               si,ss,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_sp
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           real(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),sr(*),si(*),ss(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(sp) :: temp,v(3),c1,s1,c2,s2,swap
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('SLAQZ4',-info)
              return
           end if
           ! executable statements
           if (nshifts < 2) then
              return
           end if
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ! shuffle shifts into pairs of real shifts and pairs
           ! of complex conjugate shifts assuming complex
           ! conjugate shifts are already adjacent to one
           ! another
           do i = 1,nshifts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
                 swap = ss(i)
                 ss(i) = ss(i + 1)
                 ss(i + 1) = ss(i + 2)
                 ss(i + 2) = swap
              end if
           end do
           ! nshfts is supposed to be even, but if it is odd,
           ! then simply reduce it by one.  the shuffle above
           ! ensures that the dropped shift is real and that
           ! the remaining shifts are paired.
           ns = nshifts - mod(nshifts,2)
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_slaset('FULL',ns + 1,ns + 1,zero,one,qc,ldqc)
           call la_slaset('FULL',ns,ns,zero,one,zc,ldzc)
           do i = 1,ns,2
              ! introduce the shift
              call la_slaqz1(a(ilo,ilo),lda,b(ilo,ilo),ldb,sr(i),sr(i + 1),si( &
                        i),ss(i),ss(i + 1),v)
              temp = v(2)
              call la_slartg(temp,v(3),c1,s1,v(2))
              call la_slartg(v(1),v(2),c2,s2,temp)
              call la_srot(ns,a(ilo + 1,ilo),lda,a(ilo + 2,ilo),lda,c1,s1)
              call la_srot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c2,s2)
              call la_srot(ns,b(ilo + 1,ilo),ldb,b(ilo + 2,ilo),ldb,c1,s1)
              call la_srot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c2,s2)
              call la_srot(ns + 1,qc(1,2),1,qc(1,3),1,c1,s1)
              call la_srot(ns + 1,qc(1,1),1,qc(1,2),1,c2,s2)
              ! chase the shift down
              do j = 1,ns - 1 - i
                 call la_slaqz2(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ilo,ilo + ns &
                        ),lda,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ilo,ilo + ns &
                        ),ldb,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_sgemm('N','N',n,sheight,sheight,one,q(1,ilo),ldq,qc,ldqc, &
                        zero,work,n)
              call la_slacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_sgemm('N','N',sheight,swidth,swidth,one,a(istartm,ilo),lda, &
                        zc,ldzc,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_sgemm('N','N',sheight,swidth,swidth,one,b(istartm,ilo),ldb, &
                        zc,ldzc,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_sgemm('N','N',n,swidth,swidth,one,z(1,ilo),ldz,zc,ldzc, &
                        zero,work,n)
              call la_slacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_slaset('FULL',ns + np,ns + np,zero,one,qc,ldqc)
              call la_slaset('FULL',ns + np,ns + np,zero,one,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-2
                 do j = 0,np - 1
                    ! move down the block with index k+i+j-1, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_slaqz2(.true.,.true.,k + i + j - 1,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,zero,work,sheight)
                 call la_slacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,zero,work,sheight)
                 call la_slacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_sgemm('N','N',n,nblock,nblock,one,q(1,k + 1),ldq,qc,ldqc, &
                           zero,work,n)
                 call la_slacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_sgemm('N','N',sheight,swidth,swidth,one,a(istartm,k),lda, &
                           zc,ldzc,zero,work,sheight)
                 call la_slacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_sgemm('N','N',sheight,swidth,swidth,one,b(istartm,k),ldb, &
                           zc,ldzc,zero,work,sheight)
                 call la_slacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_sgemm('N','N',n,nblock,nblock,one,z(1,k),ldz,zc,ldzc, &
                           zero,work,n)
                 call la_slacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_slaset('FULL',ns,ns,zero,one,qc,ldqc)
           call la_slaset('FULL',ns + 1,ns + 1,zero,one,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns,2
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i - 1,ihi - 2
                 call la_slaqz2(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_sgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_sgemm('N','N',n,ns,ns,one,q(1,ihi - ns + 1),ldq,qc,ldqc,zero, &
                        work,n)
              call la_slacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_sgemm('N','N',sheight,swidth,swidth,one,a(istartm,ihi - ns),lda, &
                         zc,ldzc,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_sgemm('N','N',sheight,swidth,swidth,one,b(istartm,ihi - ns),ldb, &
                         zc,ldzc,zero,work,sheight)
              call la_slacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_sgemm('N','N',n,ns + 1,ns + 1,one,z(1,ihi - ns),ldz,zc,ldzc,zero, &
                         work,n)
              call la_slacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_slaqz4
     !> DLAQZ4: Executes a single multishift QZ sweep

     pure subroutine la_dlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,sr, &
               si,ss,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_dp
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           real(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),sr(*),si(*),ss(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(dp) :: temp,v(3),c1,s1,c2,s2,swap
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ4',-info)
              return
           end if
           ! executable statements
           if (nshifts < 2) then
              return
           end if
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ! shuffle shifts into pairs of real shifts and pairs
           ! of complex conjugate shifts assuming complex
           ! conjugate shifts are already adjacent to one
           ! another
           do i = 1,nshifts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
                 swap = ss(i)
                 ss(i) = ss(i + 1)
                 ss(i + 1) = ss(i + 2)
                 ss(i + 2) = swap
              end if
           end do
           ! nshfts is supposed to be even, but if it is odd,
           ! then simply reduce it by one.  the shuffle above
           ! ensures that the dropped shift is real and that
           ! the remaining shifts are paired.
           ns = nshifts - mod(nshifts,2)
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_dlaset('FULL',ns + 1,ns + 1,zero,one,qc,ldqc)
           call la_dlaset('FULL',ns,ns,zero,one,zc,ldzc)
           do i = 1,ns,2
              ! introduce the shift
              call la_dlaqz1(a(ilo,ilo),lda,b(ilo,ilo),ldb,sr(i),sr(i + 1),si( &
                        i),ss(i),ss(i + 1),v)
              temp = v(2)
              call la_dlartg(temp,v(3),c1,s1,v(2))
              call la_dlartg(v(1),v(2),c2,s2,temp)
              call la_drot(ns,a(ilo + 1,ilo),lda,a(ilo + 2,ilo),lda,c1,s1)
              call la_drot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c2,s2)
              call la_drot(ns,b(ilo + 1,ilo),ldb,b(ilo + 2,ilo),ldb,c1,s1)
              call la_drot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c2,s2)
              call la_drot(ns + 1,qc(1,2),1,qc(1,3),1,c1,s1)
              call la_drot(ns + 1,qc(1,1),1,qc(1,2),1,c2,s2)
              ! chase the shift down
              do j = 1,ns - 1 - i
                 call la_dlaqz2(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ilo,ilo + ns &
                        ),lda,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ilo,ilo + ns &
                        ),ldb,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_dgemm('N','N',n,sheight,sheight,one,q(1,ilo),ldq,qc,ldqc, &
                        zero,work,n)
              call la_dlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_dgemm('N','N',sheight,swidth,swidth,one,a(istartm,ilo),lda, &
                        zc,ldzc,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_dgemm('N','N',sheight,swidth,swidth,one,b(istartm,ilo),ldb, &
                        zc,ldzc,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_dgemm('N','N',n,swidth,swidth,one,z(1,ilo),ldz,zc,ldzc, &
                        zero,work,n)
              call la_dlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_dlaset('FULL',ns + np,ns + np,zero,one,qc,ldqc)
              call la_dlaset('FULL',ns + np,ns + np,zero,one,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-2
                 do j = 0,np - 1
                    ! move down the block with index k+i+j-1, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_dlaqz2(.true.,.true.,k + i + j - 1,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,zero,work,sheight)
                 call la_dlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,zero,work,sheight)
                 call la_dlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_dgemm('N','N',n,nblock,nblock,one,q(1,k + 1),ldq,qc,ldqc, &
                           zero,work,n)
                 call la_dlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_dgemm('N','N',sheight,swidth,swidth,one,a(istartm,k),lda, &
                           zc,ldzc,zero,work,sheight)
                 call la_dlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_dgemm('N','N',sheight,swidth,swidth,one,b(istartm,k),ldb, &
                           zc,ldzc,zero,work,sheight)
                 call la_dlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_dgemm('N','N',n,nblock,nblock,one,z(1,k),ldz,zc,ldzc, &
                           zero,work,n)
                 call la_dlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_dlaset('FULL',ns,ns,zero,one,qc,ldqc)
           call la_dlaset('FULL',ns + 1,ns + 1,zero,one,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns,2
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i - 1,ihi - 2
                 call la_dlaqz2(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_dgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_dgemm('N','N',n,ns,ns,one,q(1,ihi - ns + 1),ldq,qc,ldqc,zero, &
                        work,n)
              call la_dlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_dgemm('N','N',sheight,swidth,swidth,one,a(istartm,ihi - ns),lda, &
                         zc,ldzc,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_dgemm('N','N',sheight,swidth,swidth,one,b(istartm,ihi - ns),ldb, &
                         zc,ldzc,zero,work,sheight)
              call la_dlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_dgemm('N','N',n,ns + 1,ns + 1,one,z(1,ihi - ns),ldz,zc,ldzc,zero, &
                         work,n)
              call la_dlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_dlaqz4
#ifdef LA_WITH_XDP
     !> XLAQZ4: Executes a single multishift QZ sweep

     pure subroutine la_xlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,sr, &
               si,ss,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_xdp
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           real(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),sr(*),si(*),ss(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(xdp) :: temp,v(3),c1,s1,c2,s2,swap
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('XLAQZ4',-info)
              return
           end if
           ! executable statements
           if (nshifts < 2) then
              return
           end if
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ! shuffle shifts into pairs of real shifts and pairs
           ! of complex conjugate shifts assuming complex
           ! conjugate shifts are already adjacent to one
           ! another
           do i = 1,nshifts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
                 swap = ss(i)
                 ss(i) = ss(i + 1)
                 ss(i + 1) = ss(i + 2)
                 ss(i + 2) = swap
              end if
           end do
           ! nshfts is supposed to be even, but if it is odd,
           ! then simply reduce it by one.  the shuffle above
           ! ensures that the dropped shift is real and that
           ! the remaining shifts are paired.
           ns = nshifts - mod(nshifts,2)
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_xlaset('FULL',ns + 1,ns + 1,zero,one,qc,ldqc)
           call la_xlaset('FULL',ns,ns,zero,one,zc,ldzc)
           do i = 1,ns,2
              ! introduce the shift
              call la_xlaqz1(a(ilo,ilo),lda,b(ilo,ilo),ldb,sr(i),sr(i + 1),si( &
                        i),ss(i),ss(i + 1),v)
              temp = v(2)
              call la_xlartg(temp,v(3),c1,s1,v(2))
              call la_xlartg(v(1),v(2),c2,s2,temp)
              call la_xrot(ns,a(ilo + 1,ilo),lda,a(ilo + 2,ilo),lda,c1,s1)
              call la_xrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c2,s2)
              call la_xrot(ns,b(ilo + 1,ilo),ldb,b(ilo + 2,ilo),ldb,c1,s1)
              call la_xrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c2,s2)
              call la_xrot(ns + 1,qc(1,2),1,qc(1,3),1,c1,s1)
              call la_xrot(ns + 1,qc(1,1),1,qc(1,2),1,c2,s2)
              ! chase the shift down
              do j = 1,ns - 1 - i
                 call la_xlaqz2(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ilo,ilo + ns &
                        ),lda,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ilo,ilo + ns &
                        ),ldb,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_xgemm('N','N',n,sheight,sheight,one,q(1,ilo),ldq,qc,ldqc, &
                        zero,work,n)
              call la_xlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_xgemm('N','N',sheight,swidth,swidth,one,a(istartm,ilo),lda, &
                        zc,ldzc,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_xgemm('N','N',sheight,swidth,swidth,one,b(istartm,ilo),ldb, &
                        zc,ldzc,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_xgemm('N','N',n,swidth,swidth,one,z(1,ilo),ldz,zc,ldzc, &
                        zero,work,n)
              call la_xlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_xlaset('FULL',ns + np,ns + np,zero,one,qc,ldqc)
              call la_xlaset('FULL',ns + np,ns + np,zero,one,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-2
                 do j = 0,np - 1
                    ! move down the block with index k+i+j-1, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_xlaqz2(.true.,.true.,k + i + j - 1,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,zero,work,sheight)
                 call la_xlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,zero,work,sheight)
                 call la_xlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_xgemm('N','N',n,nblock,nblock,one,q(1,k + 1),ldq,qc,ldqc, &
                           zero,work,n)
                 call la_xlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_xgemm('N','N',sheight,swidth,swidth,one,a(istartm,k),lda, &
                           zc,ldzc,zero,work,sheight)
                 call la_xlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_xgemm('N','N',sheight,swidth,swidth,one,b(istartm,k),ldb, &
                           zc,ldzc,zero,work,sheight)
                 call la_xlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_xgemm('N','N',n,nblock,nblock,one,z(1,k),ldz,zc,ldzc, &
                           zero,work,n)
                 call la_xlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_xlaset('FULL',ns,ns,zero,one,qc,ldqc)
           call la_xlaset('FULL',ns + 1,ns + 1,zero,one,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns,2
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i - 1,ihi - 2
                 call la_xlaqz2(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_xgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_xgemm('N','N',n,ns,ns,one,q(1,ihi - ns + 1),ldq,qc,ldqc,zero, &
                        work,n)
              call la_xlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_xgemm('N','N',sheight,swidth,swidth,one,a(istartm,ihi - ns),lda, &
                         zc,ldzc,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_xgemm('N','N',sheight,swidth,swidth,one,b(istartm,ihi - ns),ldb, &
                         zc,ldzc,zero,work,sheight)
              call la_xlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_xgemm('N','N',n,ns + 1,ns + 1,one,z(1,ihi - ns),ldz,zc,ldzc,zero, &
                         work,n)
              call la_xlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_xlaqz4
#endif
#ifdef LA_WITH_QP
     !> QLAQZ4: Executes a single multishift QZ sweep

     pure subroutine la_qlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,sr, &
               si,ss,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_qp
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),sr(*),si(*),ss(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(qp) :: temp,v(3),c1,s1,c2,s2,swap
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('QLAQZ4',-info)
              return
           end if
           ! executable statements
           if (nshifts < 2) then
              return
           end if
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ! shuffle shifts into pairs of real shifts and pairs
           ! of complex conjugate shifts assuming complex
           ! conjugate shifts are already adjacent to one
           ! another
           do i = 1,nshifts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
                 swap = ss(i)
                 ss(i) = ss(i + 1)
                 ss(i + 1) = ss(i + 2)
                 ss(i + 2) = swap
              end if
           end do
           ! nshfts is supposed to be even, but if it is odd,
           ! then simply reduce it by one.  the shuffle above
           ! ensures that the dropped shift is real and that
           ! the remaining shifts are paired.
           ns = nshifts - mod(nshifts,2)
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_qlaset('FULL',ns + 1,ns + 1,zero,one,qc,ldqc)
           call la_qlaset('FULL',ns,ns,zero,one,zc,ldzc)
           do i = 1,ns,2
              ! introduce the shift
              call la_qlaqz1(a(ilo,ilo),lda,b(ilo,ilo),ldb,sr(i),sr(i + 1),si( &
                        i),ss(i),ss(i + 1),v)
              temp = v(2)
              call la_qlartg(temp,v(3),c1,s1,v(2))
              call la_qlartg(v(1),v(2),c2,s2,temp)
              call la_qrot(ns,a(ilo + 1,ilo),lda,a(ilo + 2,ilo),lda,c1,s1)
              call la_qrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c2,s2)
              call la_qrot(ns,b(ilo + 1,ilo),ldb,b(ilo + 2,ilo),ldb,c1,s1)
              call la_qrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c2,s2)
              call la_qrot(ns + 1,qc(1,2),1,qc(1,3),1,c1,s1)
              call la_qrot(ns + 1,qc(1,1),1,qc(1,2),1,c2,s2)
              ! chase the shift down
              do j = 1,ns - 1 - i
                 call la_qlaqz2(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ilo,ilo + ns &
                        ),lda,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ilo,ilo + ns &
                        ),ldb,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_qgemm('N','N',n,sheight,sheight,one,q(1,ilo),ldq,qc,ldqc, &
                        zero,work,n)
              call la_qlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,ilo),lda, &
                        zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,ilo),ldb, &
                        zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_qgemm('N','N',n,swidth,swidth,one,z(1,ilo),ldz,zc,ldzc, &
                        zero,work,n)
              call la_qlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_qlaset('FULL',ns + np,ns + np,zero,one,qc,ldqc)
              call la_qlaset('FULL',ns + np,ns + np,zero,one,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-2
                 do j = 0,np - 1
                    ! move down the block with index k+i+j-1, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_qlaqz2(.true.,.true.,k + i + j - 1,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_qgemm('N','N',n,nblock,nblock,one,q(1,k + 1),ldq,qc,ldqc, &
                           zero,work,n)
                 call la_qlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,k),lda, &
                           zc,ldzc,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,k),ldb, &
                           zc,ldzc,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_qgemm('N','N',n,nblock,nblock,one,z(1,k),ldz,zc,ldzc, &
                           zero,work,n)
                 call la_qlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_qlaset('FULL',ns,ns,zero,one,qc,ldqc)
           call la_qlaset('FULL',ns + 1,ns + 1,zero,one,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns,2
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i - 1,ihi - 2
                 call la_qlaqz2(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_qgemm('N','N',n,ns,ns,one,q(1,ihi - ns + 1),ldq,qc,ldqc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,ihi - ns),lda, &
                         zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,ihi - ns),ldb, &
                         zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_qgemm('N','N',n,ns + 1,ns + 1,one,z(1,ihi - ns),ldz,zc,ldzc,zero, &
                         work,n)
              call la_qlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_qlaqz4
#endif

     !> SLAQR5:, called by SLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_slaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,sr,si,h,ldh, &
               iloz,ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_sp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(sp),intent(inout) :: h(ldh,*),si(*),sr(*),z(ldz,*)
           real(sp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(sp) :: alpha,beta,h11,h12,h21,h22,refsum,safmax,safmin,scl,smlnum,swap, &
                      tst1,tst2,ulp
           integer(ilp) :: i,i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms, &
                     krcol,m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,max,min,mod,real
           ! Local Arrays
           real(sp) :: vt(3)
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== shuffle shifts into pairs of real shifts and pairs
           ! .    of complex conjugate shifts assuming complex
           ! .    conjugate shifts are already adjacent to one
           ! .    another. ====
           do i = 1,nshfts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
              end if
           end do
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by one.  the shuffle above
           ! .    ensures that the dropped shift is real and that
           ! .    the remaining shifts are paired. ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = zero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_slaset('ALL',kdu,kdu,zero,one,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps-1 columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    one column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_slaqr1(2,h(k + 1,k + 1),ldh,sr(2*m22 - 1),si(2*m22 - 1),sr( &
                                  2*m22),si(2*m22),v(1,m22))
                       beta = v(1,m22)
                       call la_slarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_slarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = zero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m22)
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = v(1,m22)*(h(k + 1,j) + v(2,m22)*h(k + 2,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= zero) then
                          tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                          if (tst1 == zero) then
                             if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                          end if
                          if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                       then
                                h(k + 1,k) = zero
                             end if
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m22)
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m22)
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_slaqr1(3,h(ktop,ktop),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                 2*m),si(2*m),v(1,m))
                       alpha = v(1,m)
                       call la_slarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually zero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*v(2,m)
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*v(3,m)
                       ! ==== calculate reflection to move
                       ! .    mth bulge one step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_slarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= zero .or. h(k + 3,k + 1) /= zero .or. h(k + 3,k + 2) == zero) &
                                 then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = zero
                          h(k + 3,k) = zero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new one. ====
                          call la_slaqr1(3,h(k + 1,k + 1),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                    2*m),si(2*m),vt)
                          alpha = vt(1)
                          call la_slarfg(3,alpha,vt(2),1,vt(1))
                          refsum = vt(1)*(h(k + 1,k) + vt(2)*h(k + 2,k))
                          if (abs(h(k + 2,k) - refsum*vt(2)) + abs(refsum*vt(3)) > ulp*(abs( &
                                    h(k,k)) + abs(h(k + 1,k + 1)) + abs(h(k + 2,k + 2)))) then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old one with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new one. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m)
                       h(j,k + 3) = h(j,k + 3) - refsum*v(3,m)
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = v(1,m)*(h(k + 1,k + 1) + v(2,m)*h(k + 2,k + 1) + v(3,m)*h(k + 3, &
                              k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= zero) then
                       tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                       if (tst1 == zero) then
                          if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                       end if
                       if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                    then
                             h(k + 1,k) = zero
                          end if
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = v(1,m)*(h(k + 1,j) + v(2,m)*h(k + 2,j) + v(3,m)*h(k + 3,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m)
                          u(j,kms + 3) = u(j,kms + 3) - refsum*v(3,m)
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m)
                          z(j,k + 3) = z(j,k + 3) - refsum*v(3,m)
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_sgemm('C','N',nu,jlen,nu,one,u(k1,k1),ldu,h(incol + k1, &
                              jcol),ldh,zero,wh,ldwh)
                    call la_slacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_sgemm('N','N',jlen,nu,nu,one,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,zero,wv,ldwv)
                    call la_slacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_sgemm('N','N',jlen,nu,nu,one,z(jrow,incol + k1),ldz,u( &
                                  k1,k1),ldu,zero,wv,ldwv)
                       call la_slacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_slaqr5
     !> DLAQR5:, called by DLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_dlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,sr,si,h,ldh, &
               iloz,ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_dp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(dp),intent(inout) :: h(ldh,*),si(*),sr(*),z(ldz,*)
           real(dp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(dp) :: alpha,beta,h11,h12,h21,h22,refsum,safmax,safmin,scl,smlnum,swap, &
                      tst1,tst2,ulp
           integer(ilp) :: i,i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms, &
                     krcol,m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,mod
           ! Local Arrays
           real(dp) :: vt(3)
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== shuffle shifts into pairs of real shifts and pairs
           ! .    of complex conjugate shifts assuming complex
           ! .    conjugate shifts are already adjacent to one
           ! .    another. ====
           do i = 1,nshfts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
              end if
           end do
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by one.  the shuffle above
           ! .    ensures that the dropped shift is real and that
           ! .    the remaining shifts are paired. ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = zero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_dlaset('ALL',kdu,kdu,zero,one,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    one column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_dlaqr1(2,h(k + 1,k + 1),ldh,sr(2*m22 - 1),si(2*m22 - 1),sr( &
                                  2*m22),si(2*m22),v(1,m22))
                       beta = v(1,m22)
                       call la_dlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_dlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = zero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m22)
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = v(1,m22)*(h(k + 1,j) + v(2,m22)*h(k + 2,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= zero) then
                          tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                          if (tst1 == zero) then
                             if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                          end if
                          if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                       then
                                h(k + 1,k) = zero
                             end if
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m22)
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m22)
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_dlaqr1(3,h(ktop,ktop),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                 2*m),si(2*m),v(1,m))
                       alpha = v(1,m)
                       call la_dlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually zero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*v(2,m)
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*v(3,m)
                       ! ==== calculate reflection to move
                       ! .    mth bulge one step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_dlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= zero .or. h(k + 3,k + 1) /= zero .or. h(k + 3,k + 2) == zero) &
                                 then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = zero
                          h(k + 3,k) = zero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new one. ====
                          call la_dlaqr1(3,h(k + 1,k + 1),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                    2*m),si(2*m),vt)
                          alpha = vt(1)
                          call la_dlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = vt(1)*(h(k + 1,k) + vt(2)*h(k + 2,k))
                          if (abs(h(k + 2,k) - refsum*vt(2)) + abs(refsum*vt(3)) > ulp*(abs( &
                                    h(k,k)) + abs(h(k + 1,k + 1)) + abs(h(k + 2,k + 2)))) then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old one with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new one. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m)
                       h(j,k + 3) = h(j,k + 3) - refsum*v(3,m)
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = v(1,m)*(h(k + 1,k + 1) + v(2,m)*h(k + 2,k + 1) + v(3,m)*h(k + 3, &
                              k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= zero) then
                       tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                       if (tst1 == zero) then
                          if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                       end if
                       if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                    then
                             h(k + 1,k) = zero
                          end if
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = v(1,m)*(h(k + 1,j) + v(2,m)*h(k + 2,j) + v(3,m)*h(k + 3,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m)
                          u(j,kms + 3) = u(j,kms + 3) - refsum*v(3,m)
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m)
                          z(j,k + 3) = z(j,k + 3) - refsum*v(3,m)
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_dgemm('C','N',nu,jlen,nu,one,u(k1,k1),ldu,h(incol + k1, &
                              jcol),ldh,zero,wh,ldwh)
                    call la_dlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_dgemm('N','N',jlen,nu,nu,one,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,zero,wv,ldwv)
                    call la_dlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_dgemm('N','N',jlen,nu,nu,one,z(jrow,incol + k1),ldz,u( &
                                  k1,k1),ldu,zero,wv,ldwv)
                       call la_dlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_dlaqr5
#ifdef LA_WITH_XDP
     !> XLAQR5:, called by XLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_xlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,sr,si,h,ldh, &
               iloz,ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_xdp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(xdp),intent(inout) :: h(ldh,*),si(*),sr(*),z(ldz,*)
           real(xdp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(xdp) :: alpha,beta,h11,h12,h21,h22,refsum,safmax,safmin,scl,smlnum,swap, &
                      tst1,tst2,ulp
           integer(ilp) :: i,i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms, &
                     krcol,m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,mod
           ! Local Arrays
           real(xdp) :: vt(3)
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== shuffle shifts into pairs of real shifts and pairs
           ! .    of complex conjugate shifts assuming complex
           ! .    conjugate shifts are already adjacent to one
           ! .    another. ====
           do i = 1,nshfts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
              end if
           end do
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by one.  the shuffle above
           ! .    ensures that the dropped shift is real and that
           ! .    the remaining shifts are paired. ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = zero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_xlaset('ALL',kdu,kdu,zero,one,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    one column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_xlaqr1(2,h(k + 1,k + 1),ldh,sr(2*m22 - 1),si(2*m22 - 1),sr( &
                                  2*m22),si(2*m22),v(1,m22))
                       beta = v(1,m22)
                       call la_xlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_xlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = zero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m22)
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = v(1,m22)*(h(k + 1,j) + v(2,m22)*h(k + 2,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= zero) then
                          tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                          if (tst1 == zero) then
                             if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                          end if
                          if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                       then
                                h(k + 1,k) = zero
                             end if
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m22)
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m22)
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_xlaqr1(3,h(ktop,ktop),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                 2*m),si(2*m),v(1,m))
                       alpha = v(1,m)
                       call la_xlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually zero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*v(2,m)
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*v(3,m)
                       ! ==== calculate reflection to move
                       ! .    mth bulge one step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_xlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= zero .or. h(k + 3,k + 1) /= zero .or. h(k + 3,k + 2) == zero) &
                                 then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = zero
                          h(k + 3,k) = zero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new one. ====
                          call la_xlaqr1(3,h(k + 1,k + 1),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                    2*m),si(2*m),vt)
                          alpha = vt(1)
                          call la_xlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = vt(1)*(h(k + 1,k) + vt(2)*h(k + 2,k))
                          if (abs(h(k + 2,k) - refsum*vt(2)) + abs(refsum*vt(3)) > ulp*(abs( &
                                    h(k,k)) + abs(h(k + 1,k + 1)) + abs(h(k + 2,k + 2)))) then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old one with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new one. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m)
                       h(j,k + 3) = h(j,k + 3) - refsum*v(3,m)
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = v(1,m)*(h(k + 1,k + 1) + v(2,m)*h(k + 2,k + 1) + v(3,m)*h(k + 3, &
                              k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= zero) then
                       tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                       if (tst1 == zero) then
                          if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                       end if
                       if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                    then
                             h(k + 1,k) = zero
                          end if
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = v(1,m)*(h(k + 1,j) + v(2,m)*h(k + 2,j) + v(3,m)*h(k + 3,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m)
                          u(j,kms + 3) = u(j,kms + 3) - refsum*v(3,m)
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m)
                          z(j,k + 3) = z(j,k + 3) - refsum*v(3,m)
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_xgemm('C','N',nu,jlen,nu,one,u(k1,k1),ldu,h(incol + k1, &
                              jcol),ldh,zero,wh,ldwh)
                    call la_xlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_xgemm('N','N',jlen,nu,nu,one,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,zero,wv,ldwv)
                    call la_xlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_xgemm('N','N',jlen,nu,nu,one,z(jrow,incol + k1),ldz,u( &
                                  k1,k1),ldu,zero,wv,ldwv)
                       call la_xlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_xlaqr5
#endif
#ifdef LA_WITH_QP
     !> QLAQR5:, called by QLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,sr,si,h,ldh, &
               iloz,ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_qp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),si(*),sr(*),z(ldz,*)
           real(qp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: alpha,beta,h11,h12,h21,h22,refsum,safmax,safmin,scl,smlnum,swap, &
                      tst1,tst2,ulp
           integer(ilp) :: i,i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms, &
                     krcol,m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,mod
           ! Local Arrays
           real(qp) :: vt(3)
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== shuffle shifts into pairs of real shifts and pairs
           ! .    of complex conjugate shifts assuming complex
           ! .    conjugate shifts are already adjacent to one
           ! .    another. ====
           do i = 1,nshfts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
              end if
           end do
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by one.  the shuffle above
           ! .    ensures that the dropped shift is real and that
           ! .    the remaining shifts are paired. ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = zero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_qlaset('ALL',kdu,kdu,zero,one,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    one column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_qlaqr1(2,h(k + 1,k + 1),ldh,sr(2*m22 - 1),si(2*m22 - 1),sr( &
                                  2*m22),si(2*m22),v(1,m22))
                       beta = v(1,m22)
                       call la_qlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_qlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = zero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m22)
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = v(1,m22)*(h(k + 1,j) + v(2,m22)*h(k + 2,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= zero) then
                          tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                          if (tst1 == zero) then
                             if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                          end if
                          if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                       then
                                h(k + 1,k) = zero
                             end if
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m22)
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m22)
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_qlaqr1(3,h(ktop,ktop),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                 2*m),si(2*m),v(1,m))
                       alpha = v(1,m)
                       call la_qlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually zero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*v(2,m)
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*v(3,m)
                       ! ==== calculate reflection to move
                       ! .    mth bulge one step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_qlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= zero .or. h(k + 3,k + 1) /= zero .or. h(k + 3,k + 2) == zero) &
                                 then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = zero
                          h(k + 3,k) = zero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new one. ====
                          call la_qlaqr1(3,h(k + 1,k + 1),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                    2*m),si(2*m),vt)
                          alpha = vt(1)
                          call la_qlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = vt(1)*(h(k + 1,k) + vt(2)*h(k + 2,k))
                          if (abs(h(k + 2,k) - refsum*vt(2)) + abs(refsum*vt(3)) > ulp*(abs( &
                                    h(k,k)) + abs(h(k + 1,k + 1)) + abs(h(k + 2,k + 2)))) then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old one with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new one. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m)
                       h(j,k + 3) = h(j,k + 3) - refsum*v(3,m)
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = v(1,m)*(h(k + 1,k + 1) + v(2,m)*h(k + 2,k + 1) + v(3,m)*h(k + 3, &
                              k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= zero) then
                       tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                       if (tst1 == zero) then
                          if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                       end if
                       if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                    then
                             h(k + 1,k) = zero
                          end if
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = v(1,m)*(h(k + 1,j) + v(2,m)*h(k + 2,j) + v(3,m)*h(k + 3,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m)
                          u(j,kms + 3) = u(j,kms + 3) - refsum*v(3,m)
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m)
                          z(j,k + 3) = z(j,k + 3) - refsum*v(3,m)
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_qgemm('C','N',nu,jlen,nu,one,u(k1,k1),ldu,h(incol + k1, &
                              jcol),ldh,zero,wh,ldwh)
                    call la_qlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_qgemm('N','N',jlen,nu,nu,one,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,zero,wv,ldwv)
                    call la_qlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_qgemm('N','N',jlen,nu,nu,one,z(jrow,incol + k1),ldz,u( &
                                  k1,k1),ldu,zero,wv,ldwv)
                       call la_qlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_qlaqr5
#endif

     !> SLAQTR: solves the real quasi-triangular system
     !> op(T)*p = scale*c,               if LREAL = .TRUE.
     !> or the complex quasi-triangular systems
     !> op(T + iB)*(p+iq) = scale*(c+id),  if LREAL = .FALSE.
     !> in real arithmetic, where T is upper quasi-triangular.
     !> If LREAL = .FALSE., then the first diagonal block of T must be
     !> 1 by 1, B is the specially structured matrix
     !> B = [ b(1) b(2) ... b(n) ]
     !> [       w            ]
     !> [           w        ]
     !> [              .     ]
     !> [                 w  ]
     !> op(A) = A or A**T, A**T denotes the transpose of
     !> matrix A.
     !> On input, X = [ c ].  On output, X = [ p ].
     !> [ d ]                  [ q ]
     !> This subroutine is designed for the condition number estimation
     !> in routine STRSNA.

     subroutine la_slaqtr(ltran,lreal,n,t,ldt,b,w,scale,x,work,info)
        use la_constants_sp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: lreal,ltran
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldt,n
           real(sp),intent(out) :: scale
           real(sp),intent(in) :: w
           ! Array Arguments
           real(sp),intent(in) :: b(*),t(ldt,*)
           real(sp),intent(out) :: work(*)
           real(sp),intent(inout) :: x(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ierr,j,j1,j2,jnext,k,n1,n2
           real(sp) :: bignum,eps,rec,scaloc,si,smin,sminw,smlnum,sr,tjj,tmp,xj,xmax, &
                     xnorm,z
           ! Local Arrays
           real(sp) :: d(2,2),v(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! do not test the input parameters for errors
           notran = .not. ltran
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_slamch('P')
           smlnum = la_slamch('S')/eps
           bignum = one/smlnum
           xnorm = la_slange('M',n,n,t,ldt,d)
           if (.not. lreal) xnorm = max(xnorm,abs(w),la_slange('M',n,1,b,n,d))

           smin = max(smlnum,eps*xnorm)
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = la_sasum(j - 1,t(1,j),1)
           end do
           if (.not. lreal) then
              do i = 2,n
                 work(i) = work(i) + abs(b(i))
              end do
           end if
           n2 = 2*n
           n1 = n
           if (.not. lreal) n1 = n2
           k = la_isamax(n1,x,1)
           xmax = abs(x(k))
           scale = one
           if (xmax > bignum) then
              scale = bignum/xmax
              call la_sscal(n1,scale,x,1)
              xmax = bignum
           end if
           if (lreal) then
              if (notran) then
                 ! solve t*p = scale*c
                 jnext = n
                 loop_30: do j = n,1,-1
                    if (j > jnext) cycle loop_30
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! meet 1 by 1 diagonal block
                       ! scale to avoid overflow when computing
                           ! x(j) = b(j)/t(j,j)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (xj == zero) cycle loop_30
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xj = abs(x(j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_saxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          k = la_isamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       ! call 2 by 2 linear system solve, to take
                       ! care of possible overflow by scaling factor.
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       call la_slaln2(.false.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_sscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       ! scale v(1,1) (= x(j1)) and/or v(2,1) (=x(j2))
                       ! to avoid overflow in updating right-hand side.
                       xj = max(abs(v(1,1)),abs(v(2,1)))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update right-hand side
                       if (j1 > 1) then
                          call la_saxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_saxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          k = la_isamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    end if
                 end do loop_30
              else
                 ! solve t**t*p = scale*c
                 jnext = 1
                 loop_40: do j = 1,n
                    if (j < jnext) cycle loop_40
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_sdot(j1 - 1,t(1,j1),1,x,1)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xmax = max(xmax,abs(x(j1)))
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side elements by inner product.
                       xj = max(abs(x(j1)),abs(x(j2)))
                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j2),work(j1)) > (bignum - xj)*rec) then
                             call la_sscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_sdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_sdot(j1 - 1,t(1,j2),1,x,1)
                       call la_slaln2(.true.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                 2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_sscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       xmax = max(abs(x(j1)),abs(x(j2)),xmax)
                    end if
                 end do loop_40
              end if
           else
              sminw = max(eps*abs(w),smin)
              if (notran) then
                 ! solve (t + ib)*(p+iq) = c+id
                 jnext = n
                 loop_70: do j = n,1,-1
                    if (j > jnext) cycle loop_70
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in division
                       z = w
                       if (j1 == 1) z = b(1)
                       xj = abs(x(j1)) + abs(x(n + j1))
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (xj == zero) cycle loop_70
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_sladiv(x(j1),x(n + j1),tmp,z,sr,si)
                       x(j1) = sr
                       x(n + j1) = si
                       xj = abs(x(j1)) + abs(x(n + j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_saxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_saxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(xmax,abs(x(k)) + abs(x(k + n)))
                          end do
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       d(1,2) = x(n + j1)
                       d(2,2) = x(n + j2)
                       call la_slaln2(.false.,2,2,sminw,one,t(j1,j1),ldt,one,one, &
                                 d,2,zero,-w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_sscal(2*n,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       ! scale x(j1), .... to avoid overflow in
                       ! updating right hand side.
                       xj = max(abs(v(1,1)) + abs(v(1,2)),abs(v(2,1)) + abs(v(2,2) &
                                  ))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update the right-hand side.
                       if (j1 > 1) then
                          call la_saxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_saxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          call la_saxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          call la_saxpy(j1 - 1,-x(n + j2),t(1,j2),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1) + b(j2)*x(n + j2)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1) - b(j2)*x(j2)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(abs(x(k)) + abs(x(k + n)),xmax)
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! solve (t + ib)**t*(p+iq) = c+id
                 jnext = 1
                 loop_80: do j = 1,n
                    if (j < jnext) cycle loop_80
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_sdot(j1 - 1,t(1,j1),1,x,1)
                       x(n + j1) = x(n + j1) - la_sdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       if (j1 > 1) then
                          x(j1) = x(j1) - b(j1)*x(n + 1)
                          x(n + j1) = x(n + j1) + b(j1)*x(1)
                       end if
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       z = w
                       if (j1 == 1) z = b(1)
                       ! scale if necessary to avoid overflow in
                       ! complex division
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_sladiv(x(j1),x(n + j1),tmp,-z,sr,si)
                       x(j1) = sr
                       x(j1 + n) = si
                       xmax = max(abs(x(j1)) + abs(x(j1 + n)),xmax)
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)))

                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j1),work(j2)) > (bignum - xj)/xmax) then
                             call la_sscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_sdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_sdot(j1 - 1,t(1,j2),1,x,1)
                       d(1,2) = x(n + j1) - la_sdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       d(2,2) = x(n + j2) - la_sdot(j1 - 1,t(1,j2),1,x(n + 1),1)

                       d(1,1) = d(1,1) - b(j1)*x(n + 1)
                       d(2,1) = d(2,1) - b(j2)*x(n + 1)
                       d(1,2) = d(1,2) + b(j1)*x(1)
                       d(2,2) = d(2,2) + b(j2)*x(1)
                       call la_slaln2(.true.,2,2,sminw,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_sscal(n2,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       xmax = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)) &
                                 ,xmax)
                    end if
                 end do loop_80
              end if
           end if
           return
     end subroutine la_slaqtr
     !> DLAQTR: solves the real quasi-triangular system
     !> op(T)*p = scale*c,               if LREAL = .TRUE.
     !> or the complex quasi-triangular systems
     !> op(T + iB)*(p+iq) = scale*(c+id),  if LREAL = .FALSE.
     !> in real arithmetic, where T is upper quasi-triangular.
     !> If LREAL = .FALSE., then the first diagonal block of T must be
     !> 1 by 1, B is the specially structured matrix
     !> B = [ b(1) b(2) ... b(n) ]
     !> [       w            ]
     !> [           w        ]
     !> [              .     ]
     !> [                 w  ]
     !> op(A) = A or A**T, A**T denotes the transpose of
     !> matrix A.
     !> On input, X = [ c ].  On output, X = [ p ].
     !> [ d ]                  [ q ]
     !> This subroutine is designed for the condition number estimation
     !> in routine DTRSNA.

     subroutine la_dlaqtr(ltran,lreal,n,t,ldt,b,w,scale,x,work,info)
        use la_constants_dp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: lreal,ltran
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldt,n
           real(dp),intent(out) :: scale
           real(dp),intent(in) :: w
           ! Array Arguments
           real(dp),intent(in) :: b(*),t(ldt,*)
           real(dp),intent(out) :: work(*)
           real(dp),intent(inout) :: x(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ierr,j,j1,j2,jnext,k,n1,n2
           real(dp) :: bignum,eps,rec,scaloc,si,smin,sminw,smlnum,sr,tjj,tmp,xj,xmax, &
                     xnorm,z
           ! Local Arrays
           real(dp) :: d(2,2),v(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! do not test the input parameters for errors
           notran = .not. ltran
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_dlamch('P')
           smlnum = la_dlamch('S')/eps
           bignum = one/smlnum
           xnorm = la_dlange('M',n,n,t,ldt,d)
           if (.not. lreal) xnorm = max(xnorm,abs(w),la_dlange('M',n,1,b,n,d))

           smin = max(smlnum,eps*xnorm)
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = la_dasum(j - 1,t(1,j),1)
           end do
           if (.not. lreal) then
              do i = 2,n
                 work(i) = work(i) + abs(b(i))
              end do
           end if
           n2 = 2*n
           n1 = n
           if (.not. lreal) n1 = n2
           k = la_idamax(n1,x,1)
           xmax = abs(x(k))
           scale = one
           if (xmax > bignum) then
              scale = bignum/xmax
              call la_dscal(n1,scale,x,1)
              xmax = bignum
           end if
           if (lreal) then
              if (notran) then
                 ! solve t*p = scale*c
                 jnext = n
                 loop_30: do j = n,1,-1
                    if (j > jnext) cycle loop_30
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! meet 1 by 1 diagonal block
                       ! scale to avoid overflow when computing
                           ! x(j) = b(j)/t(j,j)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (xj == zero) cycle loop_30
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xj = abs(x(j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_daxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          k = la_idamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       ! call 2 by 2 linear system solve, to take
                       ! care of possible overflow by scaling factor.
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       call la_dlaln2(.false.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_dscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       ! scale v(1,1) (= x(j1)) and/or v(2,1) (=x(j2))
                       ! to avoid overflow in updating right-hand side.
                       xj = max(abs(v(1,1)),abs(v(2,1)))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update right-hand side
                       if (j1 > 1) then
                          call la_daxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_daxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          k = la_idamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    end if
                 end do loop_30
              else
                 ! solve t**t*p = scale*c
                 jnext = 1
                 loop_40: do j = 1,n
                    if (j < jnext) cycle loop_40
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_ddot(j1 - 1,t(1,j1),1,x,1)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xmax = max(xmax,abs(x(j1)))
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side elements by inner product.
                       xj = max(abs(x(j1)),abs(x(j2)))
                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j2),work(j1)) > (bignum - xj)*rec) then
                             call la_dscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_ddot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_ddot(j1 - 1,t(1,j2),1,x,1)
                       call la_dlaln2(.true.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                 2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_dscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       xmax = max(abs(x(j1)),abs(x(j2)),xmax)
                    end if
                 end do loop_40
              end if
           else
              sminw = max(eps*abs(w),smin)
              if (notran) then
                 ! solve (t + ib)*(p+iq) = c+id
                 jnext = n
                 loop_70: do j = n,1,-1
                    if (j > jnext) cycle loop_70
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in division
                       z = w
                       if (j1 == 1) z = b(1)
                       xj = abs(x(j1)) + abs(x(n + j1))
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (xj == zero) cycle loop_70
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_dladiv(x(j1),x(n + j1),tmp,z,sr,si)
                       x(j1) = sr
                       x(n + j1) = si
                       xj = abs(x(j1)) + abs(x(n + j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_daxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_daxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(xmax,abs(x(k)) + abs(x(k + n)))
                          end do
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       d(1,2) = x(n + j1)
                       d(2,2) = x(n + j2)
                       call la_dlaln2(.false.,2,2,sminw,one,t(j1,j1),ldt,one,one, &
                                 d,2,zero,-w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_dscal(2*n,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       ! scale x(j1), .... to avoid overflow in
                       ! updating right hand side.
                       xj = max(abs(v(1,1)) + abs(v(1,2)),abs(v(2,1)) + abs(v(2,2) &
                                  ))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update the right-hand side.
                       if (j1 > 1) then
                          call la_daxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_daxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          call la_daxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          call la_daxpy(j1 - 1,-x(n + j2),t(1,j2),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1) + b(j2)*x(n + j2)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1) - b(j2)*x(j2)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(abs(x(k)) + abs(x(k + n)),xmax)
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! solve (t + ib)**t*(p+iq) = c+id
                 jnext = 1
                 loop_80: do j = 1,n
                    if (j < jnext) cycle loop_80
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_ddot(j1 - 1,t(1,j1),1,x,1)
                       x(n + j1) = x(n + j1) - la_ddot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       if (j1 > 1) then
                          x(j1) = x(j1) - b(j1)*x(n + 1)
                          x(n + j1) = x(n + j1) + b(j1)*x(1)
                       end if
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       z = w
                       if (j1 == 1) z = b(1)
                       ! scale if necessary to avoid overflow in
                       ! complex division
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_dladiv(x(j1),x(n + j1),tmp,-z,sr,si)
                       x(j1) = sr
                       x(j1 + n) = si
                       xmax = max(abs(x(j1)) + abs(x(j1 + n)),xmax)
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)))

                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j1),work(j2)) > (bignum - xj)/xmax) then
                             call la_dscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_ddot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_ddot(j1 - 1,t(1,j2),1,x,1)
                       d(1,2) = x(n + j1) - la_ddot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       d(2,2) = x(n + j2) - la_ddot(j1 - 1,t(1,j2),1,x(n + 1),1)

                       d(1,1) = d(1,1) - b(j1)*x(n + 1)
                       d(2,1) = d(2,1) - b(j2)*x(n + 1)
                       d(1,2) = d(1,2) + b(j1)*x(1)
                       d(2,2) = d(2,2) + b(j2)*x(1)
                       call la_dlaln2(.true.,2,2,sminw,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_dscal(n2,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       xmax = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)) &
                                 ,xmax)
                    end if
                 end do loop_80
              end if
           end if
           return
     end subroutine la_dlaqtr
#ifdef LA_WITH_XDP
     !> XLAQTR: solves the real quasi-triangular system
     !> op(T)*p = scale*c,               if LREAL = .TRUE.
     !> or the complex quasi-triangular systems
     !> op(T + iB)*(p+iq) = scale*(c+id),  if LREAL = .FALSE.
     !> in real arithmetic, where T is upper quasi-triangular.
     !> If LREAL = .FALSE., then the first diagonal block of T must be
     !> 1 by 1, B is the specially structured matrix
     !> B = [ b(1) b(2) ... b(n) ]
     !> [       w            ]
     !> [           w        ]
     !> [              .     ]
     !> [                 w  ]
     !> op(A) = A or A**T, A**T denotes the transpose of
     !> matrix A.
     !> On input, X = [ c ].  On output, X = [ p ].
     !> [ d ]                  [ q ]
     !> This subroutine is designed for the condition number estimation
     !> in routine XTRSNA.

     subroutine la_xlaqtr(ltran,lreal,n,t,ldt,b,w,scale,x,work,info)
        use la_constants_xdp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: lreal,ltran
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldt,n
           real(xdp),intent(out) :: scale
           real(xdp),intent(in) :: w
           ! Array Arguments
           real(xdp),intent(in) :: b(*),t(ldt,*)
           real(xdp),intent(out) :: work(*)
           real(xdp),intent(inout) :: x(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ierr,j,j1,j2,jnext,k,n1,n2
           real(xdp) :: bignum,eps,rec,scaloc,si,smin,sminw,smlnum,sr,tjj,tmp,xj,xmax, &
                     xnorm,z
           ! Local Arrays
           real(xdp) :: d(2,2),v(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! do not test the input parameters for errors
           notran = .not. ltran
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_xlamch('P')
           smlnum = la_xlamch('S')/eps
           bignum = one/smlnum
           xnorm = la_xlange('M',n,n,t,ldt,d)
           if (.not. lreal) xnorm = max(xnorm,abs(w),la_xlange('M',n,1,b,n,d))

           smin = max(smlnum,eps*xnorm)
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = la_xasum(j - 1,t(1,j),1)
           end do
           if (.not. lreal) then
              do i = 2,n
                 work(i) = work(i) + abs(b(i))
              end do
           end if
           n2 = 2*n
           n1 = n
           if (.not. lreal) n1 = n2
           k = la_ixamax(n1,x,1)
           xmax = abs(x(k))
           scale = one
           if (xmax > bignum) then
              scale = bignum/xmax
              call la_xscal(n1,scale,x,1)
              xmax = bignum
           end if
           if (lreal) then
              if (notran) then
                 ! solve t*p = scale*c
                 jnext = n
                 loop_30: do j = n,1,-1
                    if (j > jnext) cycle loop_30
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! meet 1 by 1 diagonal block
                       ! scale to avoid overflow when computing
                           ! x(j) = b(j)/t(j,j)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (xj == zero) cycle loop_30
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xj = abs(x(j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_xaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          k = la_ixamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       ! call 2 by 2 linear system solve, to take
                       ! care of possible overflow by scaling factor.
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       call la_xlaln2(.false.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_xscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       ! scale v(1,1) (= x(j1)) and/or v(2,1) (=x(j2))
                       ! to avoid overflow in updating right-hand side.
                       xj = max(abs(v(1,1)),abs(v(2,1)))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update right-hand side
                       if (j1 > 1) then
                          call la_xaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_xaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          k = la_ixamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    end if
                 end do loop_30
              else
                 ! solve t**t*p = scale*c
                 jnext = 1
                 loop_40: do j = 1,n
                    if (j < jnext) cycle loop_40
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_xdot(j1 - 1,t(1,j1),1,x,1)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xmax = max(xmax,abs(x(j1)))
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side elements by inner product.
                       xj = max(abs(x(j1)),abs(x(j2)))
                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j2),work(j1)) > (bignum - xj)*rec) then
                             call la_xscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_xdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_xdot(j1 - 1,t(1,j2),1,x,1)
                       call la_xlaln2(.true.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                 2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_xscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       xmax = max(abs(x(j1)),abs(x(j2)),xmax)
                    end if
                 end do loop_40
              end if
           else
              sminw = max(eps*abs(w),smin)
              if (notran) then
                 ! solve (t + ib)*(p+iq) = c+id
                 jnext = n
                 loop_70: do j = n,1,-1
                    if (j > jnext) cycle loop_70
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in division
                       z = w
                       if (j1 == 1) z = b(1)
                       xj = abs(x(j1)) + abs(x(n + j1))
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (xj == zero) cycle loop_70
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_xladiv(x(j1),x(n + j1),tmp,z,sr,si)
                       x(j1) = sr
                       x(n + j1) = si
                       xj = abs(x(j1)) + abs(x(n + j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_xaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_xaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(xmax,abs(x(k)) + abs(x(k + n)))
                          end do
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       d(1,2) = x(n + j1)
                       d(2,2) = x(n + j2)
                       call la_xlaln2(.false.,2,2,sminw,one,t(j1,j1),ldt,one,one, &
                                 d,2,zero,-w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_xscal(2*n,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       ! scale x(j1), .... to avoid overflow in
                       ! updating right hand side.
                       xj = max(abs(v(1,1)) + abs(v(1,2)),abs(v(2,1)) + abs(v(2,2) &
                                  ))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update the right-hand side.
                       if (j1 > 1) then
                          call la_xaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_xaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          call la_xaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          call la_xaxpy(j1 - 1,-x(n + j2),t(1,j2),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1) + b(j2)*x(n + j2)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1) - b(j2)*x(j2)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(abs(x(k)) + abs(x(k + n)),xmax)
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! solve (t + ib)**t*(p+iq) = c+id
                 jnext = 1
                 loop_80: do j = 1,n
                    if (j < jnext) cycle loop_80
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_xdot(j1 - 1,t(1,j1),1,x,1)
                       x(n + j1) = x(n + j1) - la_xdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       if (j1 > 1) then
                          x(j1) = x(j1) - b(j1)*x(n + 1)
                          x(n + j1) = x(n + j1) + b(j1)*x(1)
                       end if
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       z = w
                       if (j1 == 1) z = b(1)
                       ! scale if necessary to avoid overflow in
                       ! complex division
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_xladiv(x(j1),x(n + j1),tmp,-z,sr,si)
                       x(j1) = sr
                       x(j1 + n) = si
                       xmax = max(abs(x(j1)) + abs(x(j1 + n)),xmax)
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)))

                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j1),work(j2)) > (bignum - xj)/xmax) then
                             call la_xscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_xdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_xdot(j1 - 1,t(1,j2),1,x,1)
                       d(1,2) = x(n + j1) - la_xdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       d(2,2) = x(n + j2) - la_xdot(j1 - 1,t(1,j2),1,x(n + 1),1)

                       d(1,1) = d(1,1) - b(j1)*x(n + 1)
                       d(2,1) = d(2,1) - b(j2)*x(n + 1)
                       d(1,2) = d(1,2) + b(j1)*x(1)
                       d(2,2) = d(2,2) + b(j2)*x(1)
                       call la_xlaln2(.true.,2,2,sminw,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_xscal(n2,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       xmax = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)) &
                                 ,xmax)
                    end if
                 end do loop_80
              end if
           end if
           return
     end subroutine la_xlaqtr
#endif
#ifdef LA_WITH_QP
     !> QLAQTR: solves the real quasi-triangular system
     !> op(T)*p = scale*c,               if LREAL = .TRUE.
     !> or the complex quasi-triangular systems
     !> op(T + iB)*(p+iq) = scale*(c+id),  if LREAL = .FALSE.
     !> in real arithmetic, where T is upper quasi-triangular.
     !> If LREAL = .FALSE., then the first diagonal block of T must be
     !> 1 by 1, B is the specially structured matrix
     !> B = [ b(1) b(2) ... b(n) ]
     !> [       w            ]
     !> [           w        ]
     !> [              .     ]
     !> [                 w  ]
     !> op(A) = A or A**T, A**T denotes the transpose of
     !> matrix A.
     !> On input, X = [ c ].  On output, X = [ p ].
     !> [ d ]                  [ q ]
     !> This subroutine is designed for the condition number estimation
     !> in routine QTRSNA.

     subroutine la_qlaqtr(ltran,lreal,n,t,ldt,b,w,scale,x,work,info)
        use la_constants_qp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: lreal,ltran
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldt,n
           real(qp),intent(out) :: scale
           real(qp),intent(in) :: w
           ! Array Arguments
           real(qp),intent(in) :: b(*),t(ldt,*)
           real(qp),intent(out) :: work(*)
           real(qp),intent(inout) :: x(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ierr,j,j1,j2,jnext,k,n1,n2
           real(qp) :: bignum,eps,rec,scaloc,si,smin,sminw,smlnum,sr,tjj,tmp,xj,xmax, &
                     xnorm,z
           ! Local Arrays
           real(qp) :: d(2,2),v(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! do not test the input parameters for errors
           notran = .not. ltran
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           bignum = one/smlnum
           xnorm = la_qlange('M',n,n,t,ldt,d)
           if (.not. lreal) xnorm = max(xnorm,abs(w),la_qlange('M',n,1,b,n,d))

           smin = max(smlnum,eps*xnorm)
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = la_qasum(j - 1,t(1,j),1)
           end do
           if (.not. lreal) then
              do i = 2,n
                 work(i) = work(i) + abs(b(i))
              end do
           end if
           n2 = 2*n
           n1 = n
           if (.not. lreal) n1 = n2
           k = la_iqamax(n1,x,1)
           xmax = abs(x(k))
           scale = one
           if (xmax > bignum) then
              scale = bignum/xmax
              call la_qscal(n1,scale,x,1)
              xmax = bignum
           end if
           if (lreal) then
              if (notran) then
                 ! solve t*p = scale*c
                 jnext = n
                 loop_30: do j = n,1,-1
                    if (j > jnext) cycle loop_30
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! meet 1 by 1 diagonal block
                       ! scale to avoid overflow when computing
                           ! x(j) = b(j)/t(j,j)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (xj == zero) cycle loop_30
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xj = abs(x(j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          k = la_iqamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       ! call 2 by 2 linear system solve, to take
                       ! care of possible overflow by scaling factor.
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       call la_qlaln2(.false.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       ! scale v(1,1) (= x(j1)) and/or v(2,1) (=x(j2))
                       ! to avoid overflow in updating right-hand side.
                       xj = max(abs(v(1,1)),abs(v(2,1)))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update right-hand side
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          k = la_iqamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    end if
                 end do loop_30
              else
                 ! solve t**t*p = scale*c
                 jnext = 1
                 loop_40: do j = 1,n
                    if (j < jnext) cycle loop_40
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xmax = max(xmax,abs(x(j1)))
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side elements by inner product.
                       xj = max(abs(x(j1)),abs(x(j2)))
                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j2),work(j1)) > (bignum - xj)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_qdot(j1 - 1,t(1,j2),1,x,1)
                       call la_qlaln2(.true.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                 2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       xmax = max(abs(x(j1)),abs(x(j2)),xmax)
                    end if
                 end do loop_40
              end if
           else
              sminw = max(eps*abs(w),smin)
              if (notran) then
                 ! solve (t + ib)*(p+iq) = c+id
                 jnext = n
                 loop_70: do j = n,1,-1
                    if (j > jnext) cycle loop_70
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in division
                       z = w
                       if (j1 == 1) z = b(1)
                       xj = abs(x(j1)) + abs(x(n + j1))
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (xj == zero) cycle loop_70
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_qladiv(x(j1),x(n + j1),tmp,z,sr,si)
                       x(j1) = sr
                       x(n + j1) = si
                       xj = abs(x(j1)) + abs(x(n + j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(xmax,abs(x(k)) + abs(x(k + n)))
                          end do
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       d(1,2) = x(n + j1)
                       d(2,2) = x(n + j2)
                       call la_qlaln2(.false.,2,2,sminw,one,t(j1,j1),ldt,one,one, &
                                 d,2,zero,-w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(2*n,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       ! scale x(j1), .... to avoid overflow in
                       ! updating right hand side.
                       xj = max(abs(v(1,1)) + abs(v(1,2)),abs(v(2,1)) + abs(v(2,2) &
                                  ))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update the right-hand side.
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          call la_qaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          call la_qaxpy(j1 - 1,-x(n + j2),t(1,j2),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1) + b(j2)*x(n + j2)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1) - b(j2)*x(j2)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(abs(x(k)) + abs(x(k + n)),xmax)
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! solve (t + ib)**t*(p+iq) = c+id
                 jnext = 1
                 loop_80: do j = 1,n
                    if (j < jnext) cycle loop_80
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       x(n + j1) = x(n + j1) - la_qdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       if (j1 > 1) then
                          x(j1) = x(j1) - b(j1)*x(n + 1)
                          x(n + j1) = x(n + j1) + b(j1)*x(1)
                       end if
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       z = w
                       if (j1 == 1) z = b(1)
                       ! scale if necessary to avoid overflow in
                       ! complex division
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_qladiv(x(j1),x(n + j1),tmp,-z,sr,si)
                       x(j1) = sr
                       x(j1 + n) = si
                       xmax = max(abs(x(j1)) + abs(x(j1 + n)),xmax)
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)))

                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j1),work(j2)) > (bignum - xj)/xmax) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_qdot(j1 - 1,t(1,j2),1,x,1)
                       d(1,2) = x(n + j1) - la_qdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       d(2,2) = x(n + j2) - la_qdot(j1 - 1,t(1,j2),1,x(n + 1),1)

                       d(1,1) = d(1,1) - b(j1)*x(n + 1)
                       d(2,1) = d(2,1) - b(j2)*x(n + 1)
                       d(1,2) = d(1,2) + b(j1)*x(1)
                       d(2,2) = d(2,2) + b(j2)*x(1)
                       call la_qlaln2(.true.,2,2,sminw,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n2,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       xmax = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)) &
                                 ,xmax)
                    end if
                 end do loop_80
              end if
           end if
           return
     end subroutine la_qlaqtr
#endif

     !> SLAHQR: is an auxiliary routine called by SHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by SHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_slahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz, &
               info)
        use la_constants_sp,only:zero,one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(sp),intent(out) :: wi(*),wr(*)
        ! =========================================================
           ! Parameters
           real(sp),parameter :: dat1 = 3.0_sp/4.0_sp
           real(sp),parameter :: dat2 = -0.4375_sp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           real(sp) :: aa,ab,ba,bb,cs,det,h11,h12,h21,h21s,h22,rt1i,rt1r,rt2i,rt2r, &
                     rtdisc,s,safmax,safmin,smlnum,sn,sum,t1,t2,t3,tr,tst,ulp,v2,v3
           integer(ilp) :: i,i1,i2,its,itmax,j,k,l,m,nh,nr,nz,kdefl
           ! Local Arrays
           real(sp) :: v(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              wr(ilo) = h(ilo,ilo)
              wi(ilo) = zero
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = zero
              h(j + 3,j) = zero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = zero
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=sp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1 or 2. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           20 continue
           l = ilo
           if (i < ilo) go to 160
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 or 2 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           loop_140: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (abs(h(k,k - 1)) <= smlnum) go to 40
                 tst = abs(h(k - 1,k - 1)) + abs(h(k,k))
                 if (tst == zero) then
                    if (k - 2 >= ilo) tst = tst + abs(h(k - 1,k - 2))
                    if (k + 1 <= ihi) tst = tst + abs(h(k + 1,k))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation  criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some cases.  ====
                 if (abs(h(k,k - 1)) <= ulp*tst) then
                    ab = max(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    ba = min(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    aa = max(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    bb = min(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 40
                 end if
              end do
              40 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = zero
              end if
              ! exit from loop if a submatrix of order 1 or 2 has split off.
              if (l >= i - 1) go to 150
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                 h11 = dat1*s + h(i,i)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(l + 1,l)) + abs(h(l + 2,l + 1))
                 h11 = dat1*s + h(l,l)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else
                 ! prepare to use francis' double shift
                 ! (i.e. 2nd degree generalized rayleigh quotient)
                 h11 = h(i - 1,i - 1)
                 h21 = h(i,i - 1)
                 h12 = h(i - 1,i)
                 h22 = h(i,i)
              end if
              s = abs(h11) + abs(h12) + abs(h21) + abs(h22)
              if (s == zero) then
                 rt1r = zero
                 rt1i = zero
                 rt2r = zero
                 rt2i = zero
              else
                 h11 = h11/s
                 h21 = h21/s
                 h12 = h12/s
                 h22 = h22/s
                 tr = (h11 + h22)/two
                 det = (h11 - tr)*(h22 - tr) - h12*h21
                 rtdisc = sqrt(abs(det))
                 if (det >= zero) then
                    ! ==== complex conjugate shifts ====
                    rt1r = tr*s
                    rt2r = rt1r
                    rt1i = rtdisc*s
                    rt2i = -rt1i
                 else
                    ! ==== realshifts (use only one of them,KIND=sp)  ====
                    rt1r = tr + rtdisc
                    rt2r = tr - rtdisc
                    if (abs(rt1r - h22) <= abs(rt2r - h22)) then
                       rt1r = rt1r*s
                       rt2r = rt1r
                    else
                       rt2r = rt2r*s
                       rt1r = rt2r
                    end if
                    rt1i = zero
                    rt2i = zero
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 2,l,-1
                 ! determine the effect of starting the double-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.  (the following uses scaling to avoid
                 ! overflows and most underflows.)
                 h21s = h(m + 1,m)
                 s = abs(h(m,m) - rt2r) + abs(rt2i) + abs(h21s)
                 h21s = h(m + 1,m)/s
                 v(1) = h21s*h(m,m + 1) + (h(m,m) - rt1r)*((h(m,m) - rt2r)/s) - &
                           rt1i*(rt2i/s)
                 v(2) = h21s*(h(m,m) + h(m + 1,m + 1) - rt1r - rt2r)
                 v(3) = h21s*h(m + 2,m + 1)
                 s = abs(v(1)) + abs(v(2)) + abs(v(3))
                 v(1) = v(1)/s
                 v(2) = v(2)/s
                 v(3) = v(3)/s
                 if (m == l) go to 60
                 if (abs(h(m,m - 1))*(abs(v(2)) + abs(v(3))) <= ulp*abs(v(1))*(abs( &
                           h(m - 1,m - 1)) + abs(h(m,m)) + abs(h(m + 1,m + 1)))) go to 60
              end do
              60 continue
              ! double-shift qr step
              loop_130: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge one step toward the bottom of the active
                 ! submatrix. nr is the order of g.
                 nr = min(3,i - k + 1)
                 if (k > m) call la_scopy(nr,h(k,k - 1),1,v,1)
                 call la_slarfg(nr,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = zero
                    if (k < i - 1) h(k + 2,k - 1) = zero
                 else if (m > l) then
                     ! ==== use the following instead of
                     ! .    h( k, k-1 ) = -h( k, k-1 ) to
                     ! .    avoid a bug when v(2) and v(3)
                     ! .    underflow. ====
                    h(k,k - 1) = h(k,k - 1)*(one - t1)
                 end if
                 v2 = v(2)
                 t2 = t1*v2
                 if (nr == 3) then
                    v3 = v(3)
                    t3 = t1*v3
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j) + v3*h(k + 2,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                       h(k + 2,j) = h(k + 2,j) - sum*t3
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,min(k + 3,i)
                       sum = h(j,k) + v2*h(j,k + 1) + v3*h(j,k + 2)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                       h(j,k + 2) = h(j,k + 2) - sum*t3
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1) + v3*z(j,k + 2)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                          z(j,k + 2) = z(j,k + 2) - sum*t3
                       end do
                    end if
                 else if (nr == 2) then
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,i
                       sum = h(j,k) + v2*h(j,k + 1)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                       end do
                    end if
                 end if
              end do loop_130
           end do loop_140
           ! failure to converge in remaining number of iterations
           info = i
           return
           150 continue
           if (l == i) then
              ! h(i,i-1) is negligible: one eigenvalue has converged.
              wr(i) = h(i,i)
              wi(i) = zero
           else if (l == i - 1) then
              ! h(i-1,i-2) is negligible: a pair of eigenvalues have converged.
              ! transform the 2-by-2 submatrix to standard schur form,
              ! and compute and store the eigenvalues.
              call la_slanv2(h(i - 1,i - 1),h(i - 1,i),h(i,i - 1),h(i,i),wr(i - 1), &
                        wi(i - 1),wr(i),wi(i),cs,sn)
              if (wantt) then
                 ! apply the transformation to the rest of h.
                 if (i2 > i) call la_srot(i2 - i,h(i - 1,i + 1),ldh,h(i,i + 1),ldh,cs,sn)

                 call la_srot(i - i1 - 1,h(i1,i - 1),1,h(i1,i),1,cs,sn)
              end if
              if (wantz) then
                 ! apply the transformation to z.
                 call la_srot(nz,z(iloz,i - 1),1,z(iloz,i),1,cs,sn)
              end if
           end if
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 20
           160 continue
           return
     end subroutine la_slahqr
     !> DLAHQR: is an auxiliary routine called by DHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by DHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_dlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz, &
               info)
        use la_constants_dp,only:zero,one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(dp),intent(out) :: wi(*),wr(*)
        ! =========================================================
           ! Parameters
           real(dp),parameter :: dat1 = 3.0_dp/4.0_dp
           real(dp),parameter :: dat2 = -0.4375_dp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           real(dp) :: aa,ab,ba,bb,cs,det,h11,h12,h21,h21s,h22,rt1i,rt1r,rt2i,rt2r, &
                     rtdisc,s,safmax,safmin,smlnum,sn,sum,t1,t2,t3,tr,tst,ulp,v2,v3
           integer(ilp) :: i,i1,i2,its,itmax,j,k,l,m,nh,nr,nz,kdefl
           ! Local Arrays
           real(dp) :: v(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,sqrt
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              wr(ilo) = h(ilo,ilo)
              wi(ilo) = zero
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = zero
              h(j + 3,j) = zero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = zero
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=dp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1 or 2. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           20 continue
           l = ilo
           if (i < ilo) go to 160
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 or 2 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           loop_140: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (abs(h(k,k - 1)) <= smlnum) go to 40
                 tst = abs(h(k - 1,k - 1)) + abs(h(k,k))
                 if (tst == zero) then
                    if (k - 2 >= ilo) tst = tst + abs(h(k - 1,k - 2))
                    if (k + 1 <= ihi) tst = tst + abs(h(k + 1,k))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation  criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some cases.  ====
                 if (abs(h(k,k - 1)) <= ulp*tst) then
                    ab = max(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    ba = min(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    aa = max(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    bb = min(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 40
                 end if
              end do
              40 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = zero
              end if
              ! exit from loop if a submatrix of order 1 or 2 has split off.
              if (l >= i - 1) go to 150
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                 h11 = dat1*s + h(i,i)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(l + 1,l)) + abs(h(l + 2,l + 1))
                 h11 = dat1*s + h(l,l)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else
                 ! prepare to use francis' double shift
                 ! (i.e. 2nd degree generalized rayleigh quotient)
                 h11 = h(i - 1,i - 1)
                 h21 = h(i,i - 1)
                 h12 = h(i - 1,i)
                 h22 = h(i,i)
              end if
              s = abs(h11) + abs(h12) + abs(h21) + abs(h22)
              if (s == zero) then
                 rt1r = zero
                 rt1i = zero
                 rt2r = zero
                 rt2i = zero
              else
                 h11 = h11/s
                 h21 = h21/s
                 h12 = h12/s
                 h22 = h22/s
                 tr = (h11 + h22)/two
                 det = (h11 - tr)*(h22 - tr) - h12*h21
                 rtdisc = sqrt(abs(det))
                 if (det >= zero) then
                    ! ==== complex conjugate shifts ====
                    rt1r = tr*s
                    rt2r = rt1r
                    rt1i = rtdisc*s
                    rt2i = -rt1i
                 else
                    ! ==== realshifts (use only one of them,KIND=dp)  ====
                    rt1r = tr + rtdisc
                    rt2r = tr - rtdisc
                    if (abs(rt1r - h22) <= abs(rt2r - h22)) then
                       rt1r = rt1r*s
                       rt2r = rt1r
                    else
                       rt2r = rt2r*s
                       rt1r = rt2r
                    end if
                    rt1i = zero
                    rt2i = zero
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 2,l,-1
                 ! determine the effect of starting the double-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.  (the following uses scaling to avoid
                 ! overflows and most underflows.)
                 h21s = h(m + 1,m)
                 s = abs(h(m,m) - rt2r) + abs(rt2i) + abs(h21s)
                 h21s = h(m + 1,m)/s
                 v(1) = h21s*h(m,m + 1) + (h(m,m) - rt1r)*((h(m,m) - rt2r)/s) - &
                           rt1i*(rt2i/s)
                 v(2) = h21s*(h(m,m) + h(m + 1,m + 1) - rt1r - rt2r)
                 v(3) = h21s*h(m + 2,m + 1)
                 s = abs(v(1)) + abs(v(2)) + abs(v(3))
                 v(1) = v(1)/s
                 v(2) = v(2)/s
                 v(3) = v(3)/s
                 if (m == l) go to 60
                 if (abs(h(m,m - 1))*(abs(v(2)) + abs(v(3))) <= ulp*abs(v(1))*(abs( &
                           h(m - 1,m - 1)) + abs(h(m,m)) + abs(h(m + 1,m + 1)))) go to 60
              end do
              60 continue
              ! double-shift qr step
              loop_130: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge one step toward the bottom of the active
                 ! submatrix. nr is the order of g.
                 nr = min(3,i - k + 1)
                 if (k > m) call la_dcopy(nr,h(k,k - 1),1,v,1)
                 call la_dlarfg(nr,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = zero
                    if (k < i - 1) h(k + 2,k - 1) = zero
                 else if (m > l) then
                     ! ==== use the following instead of
                     ! .    h( k, k-1 ) = -h( k, k-1 ) to
                     ! .    avoid a bug when v(2) and v(3)
                     ! .    underflow. ====
                    h(k,k - 1) = h(k,k - 1)*(one - t1)
                 end if
                 v2 = v(2)
                 t2 = t1*v2
                 if (nr == 3) then
                    v3 = v(3)
                    t3 = t1*v3
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j) + v3*h(k + 2,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                       h(k + 2,j) = h(k + 2,j) - sum*t3
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,min(k + 3,i)
                       sum = h(j,k) + v2*h(j,k + 1) + v3*h(j,k + 2)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                       h(j,k + 2) = h(j,k + 2) - sum*t3
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1) + v3*z(j,k + 2)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                          z(j,k + 2) = z(j,k + 2) - sum*t3
                       end do
                    end if
                 else if (nr == 2) then
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,i
                       sum = h(j,k) + v2*h(j,k + 1)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                       end do
                    end if
                 end if
              end do loop_130
           end do loop_140
           ! failure to converge in remaining number of iterations
           info = i
           return
           150 continue
           if (l == i) then
              ! h(i,i-1) is negligible: one eigenvalue has converged.
              wr(i) = h(i,i)
              wi(i) = zero
           else if (l == i - 1) then
              ! h(i-1,i-2) is negligible: a pair of eigenvalues have converged.
              ! transform the 2-by-2 submatrix to standard schur form,
              ! and compute and store the eigenvalues.
              call la_dlanv2(h(i - 1,i - 1),h(i - 1,i),h(i,i - 1),h(i,i),wr(i - 1), &
                        wi(i - 1),wr(i),wi(i),cs,sn)
              if (wantt) then
                 ! apply the transformation to the rest of h.
                 if (i2 > i) call la_drot(i2 - i,h(i - 1,i + 1),ldh,h(i,i + 1),ldh,cs,sn)

                 call la_drot(i - i1 - 1,h(i1,i - 1),1,h(i1,i),1,cs,sn)
              end if
              if (wantz) then
                 ! apply the transformation to z.
                 call la_drot(nz,z(iloz,i - 1),1,z(iloz,i),1,cs,sn)
              end if
           end if
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 20
           160 continue
           return
     end subroutine la_dlahqr
#ifdef LA_WITH_XDP
     !> XLAHQR: is an auxiliary routine called by XHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by XHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_xlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz, &
               info)
        use la_constants_xdp,only:zero,one,two
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(xdp),intent(out) :: wi(*),wr(*)
        ! =========================================================
           ! Parameters
           real(xdp),parameter :: dat1 = 3.0_xdp/4.0_xdp
           real(xdp),parameter :: dat2 = -0.4375_xdp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           real(xdp) :: aa,ab,ba,bb,cs,det,h11,h12,h21,h21s,h22,rt1i,rt1r,rt2i,rt2r, &
                     rtdisc,s,safmax,safmin,smlnum,sn,sum,t1,t2,t3,tr,tst,ulp,v2,v3
           integer(ilp) :: i,i1,i2,its,itmax,j,k,l,m,nh,nr,nz,kdefl
           ! Local Arrays
           real(xdp) :: v(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,sqrt
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              wr(ilo) = h(ilo,ilo)
              wi(ilo) = zero
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = zero
              h(j + 3,j) = zero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = zero
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=xdp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1 or 2. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           20 continue
           l = ilo
           if (i < ilo) go to 160
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 or 2 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           loop_140: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (abs(h(k,k - 1)) <= smlnum) go to 40
                 tst = abs(h(k - 1,k - 1)) + abs(h(k,k))
                 if (tst == zero) then
                    if (k - 2 >= ilo) tst = tst + abs(h(k - 1,k - 2))
                    if (k + 1 <= ihi) tst = tst + abs(h(k + 1,k))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation  criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some cases.  ====
                 if (abs(h(k,k - 1)) <= ulp*tst) then
                    ab = max(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    ba = min(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    aa = max(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    bb = min(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 40
                 end if
              end do
              40 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = zero
              end if
              ! exit from loop if a submatrix of order 1 or 2 has split off.
              if (l >= i - 1) go to 150
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                 h11 = dat1*s + h(i,i)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(l + 1,l)) + abs(h(l + 2,l + 1))
                 h11 = dat1*s + h(l,l)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else
                 ! prepare to use francis' double shift
                 ! (i.e. 2nd degree generalized rayleigh quotient)
                 h11 = h(i - 1,i - 1)
                 h21 = h(i,i - 1)
                 h12 = h(i - 1,i)
                 h22 = h(i,i)
              end if
              s = abs(h11) + abs(h12) + abs(h21) + abs(h22)
              if (s == zero) then
                 rt1r = zero
                 rt1i = zero
                 rt2r = zero
                 rt2i = zero
              else
                 h11 = h11/s
                 h21 = h21/s
                 h12 = h12/s
                 h22 = h22/s
                 tr = (h11 + h22)/two
                 det = (h11 - tr)*(h22 - tr) - h12*h21
                 rtdisc = sqrt(abs(det))
                 if (det >= zero) then
                    ! ==== complex conjugate shifts ====
                    rt1r = tr*s
                    rt2r = rt1r
                    rt1i = rtdisc*s
                    rt2i = -rt1i
                 else
                    ! ==== realshifts (use only one of them,KIND=xdp)  ====
                    rt1r = tr + rtdisc
                    rt2r = tr - rtdisc
                    if (abs(rt1r - h22) <= abs(rt2r - h22)) then
                       rt1r = rt1r*s
                       rt2r = rt1r
                    else
                       rt2r = rt2r*s
                       rt1r = rt2r
                    end if
                    rt1i = zero
                    rt2i = zero
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 2,l,-1
                 ! determine the effect of starting the double-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.  (the following uses scaling to avoid
                 ! overflows and most underflows.)
                 h21s = h(m + 1,m)
                 s = abs(h(m,m) - rt2r) + abs(rt2i) + abs(h21s)
                 h21s = h(m + 1,m)/s
                 v(1) = h21s*h(m,m + 1) + (h(m,m) - rt1r)*((h(m,m) - rt2r)/s) - &
                           rt1i*(rt2i/s)
                 v(2) = h21s*(h(m,m) + h(m + 1,m + 1) - rt1r - rt2r)
                 v(3) = h21s*h(m + 2,m + 1)
                 s = abs(v(1)) + abs(v(2)) + abs(v(3))
                 v(1) = v(1)/s
                 v(2) = v(2)/s
                 v(3) = v(3)/s
                 if (m == l) go to 60
                 if (abs(h(m,m - 1))*(abs(v(2)) + abs(v(3))) <= ulp*abs(v(1))*(abs( &
                           h(m - 1,m - 1)) + abs(h(m,m)) + abs(h(m + 1,m + 1)))) go to 60
              end do
              60 continue
              ! double-shift qr step
              loop_130: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge one step toward the bottom of the active
                 ! submatrix. nr is the order of g.
                 nr = min(3,i - k + 1)
                 if (k > m) call la_xcopy(nr,h(k,k - 1),1,v,1)
                 call la_xlarfg(nr,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = zero
                    if (k < i - 1) h(k + 2,k - 1) = zero
                 else if (m > l) then
                     ! ==== use the following instead of
                     ! .    h( k, k-1 ) = -h( k, k-1 ) to
                     ! .    avoid a bug when v(2) and v(3)
                     ! .    underflow. ====
                    h(k,k - 1) = h(k,k - 1)*(one - t1)
                 end if
                 v2 = v(2)
                 t2 = t1*v2
                 if (nr == 3) then
                    v3 = v(3)
                    t3 = t1*v3
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j) + v3*h(k + 2,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                       h(k + 2,j) = h(k + 2,j) - sum*t3
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,min(k + 3,i)
                       sum = h(j,k) + v2*h(j,k + 1) + v3*h(j,k + 2)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                       h(j,k + 2) = h(j,k + 2) - sum*t3
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1) + v3*z(j,k + 2)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                          z(j,k + 2) = z(j,k + 2) - sum*t3
                       end do
                    end if
                 else if (nr == 2) then
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,i
                       sum = h(j,k) + v2*h(j,k + 1)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                       end do
                    end if
                 end if
              end do loop_130
           end do loop_140
           ! failure to converge in remaining number of iterations
           info = i
           return
           150 continue
           if (l == i) then
              ! h(i,i-1) is negligible: one eigenvalue has converged.
              wr(i) = h(i,i)
              wi(i) = zero
           else if (l == i - 1) then
              ! h(i-1,i-2) is negligible: a pair of eigenvalues have converged.
              ! transform the 2-by-2 submatrix to standard schur form,
              ! and compute and store the eigenvalues.
              call la_xlanv2(h(i - 1,i - 1),h(i - 1,i),h(i,i - 1),h(i,i),wr(i - 1), &
                        wi(i - 1),wr(i),wi(i),cs,sn)
              if (wantt) then
                 ! apply the transformation to the rest of h.
                 if (i2 > i) call la_xrot(i2 - i,h(i - 1,i + 1),ldh,h(i,i + 1),ldh,cs,sn)

                 call la_xrot(i - i1 - 1,h(i1,i - 1),1,h(i1,i),1,cs,sn)
              end if
              if (wantz) then
                 ! apply the transformation to z.
                 call la_xrot(nz,z(iloz,i - 1),1,z(iloz,i),1,cs,sn)
              end if
           end if
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 20
           160 continue
           return
     end subroutine la_xlahqr
#endif
#ifdef LA_WITH_QP
