              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_dgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_dlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_dgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_dlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_dgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_dlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=dp)
     end subroutine la_dlaqr2
