        ! ================================================================

           ! Local Scalars
           real(qp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwkopt
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_qgehrd ====
              call la_qgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qormhr ====
              call la_qormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=qp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_qlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_qcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_qlaset('A',jw,jw,zero,one,v,ldv)
           call la_qlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1,jw, &
                     v,ldv,infqr)
           ! ==== la_qtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_qtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_qtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_qlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_qcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_qlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_qlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_qlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_qgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_qlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_qcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_qormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_qgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_qlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_qgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_qlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_qgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_qlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr2
#endif

     !> SLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_slaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(sp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(sp),parameter :: wilk1 = 0.75_sp
           real(sp),parameter :: wilk2 = -0.4375_sp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_slahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(sp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(sp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,int,max,min,mod,real
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_slahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_slahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'SLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'SLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_slaqr3 ====
              call la_slaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_slaqr5, la_slaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=sp)
                 return
              end if
              ! ==== la_slahqr/la_slaqr0 crossover point ====
              nmin = la_ilaenv(12,'SLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'SLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'SLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_slaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_slaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_slaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_slanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_slaqr4 or
                       ! .    la_slahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_slacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_slaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_slahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_slanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_slaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=sp)
     end subroutine la_slaqr0
     !> DLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_dlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(dp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(dp),parameter :: wilk1 = 0.75_dp
           real(dp),parameter :: wilk2 = -0.4375_dp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_dlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(dp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(dp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_dlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_dlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_dlaqr3 ====
              call la_dlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_dlaqr5, la_dlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=dp)
                 return
              end if
              ! ==== la_dlahqr/la_dlaqr0 crossover point ====
              nmin = la_ilaenv(12,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_dlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_dlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_dlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_dlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_dlaqr4 or
                       ! .    la_dlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_dlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_dlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_dlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_dlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_dlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=dp)
     end subroutine la_dlaqr0
#ifdef LA_WITH_XDP
     !> XLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_xlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(xdp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(xdp),parameter :: wilk1 = 0.75_xdp
           real(xdp),parameter :: wilk2 = -0.4375_xdp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_xlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(xdp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(xdp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_xlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_xlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'XLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'XLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_xlaqr3 ====
              call la_xlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_xlaqr5, la_xlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=xdp)
                 return
              end if
              ! ==== la_xlahqr/la_xlaqr0 crossover point ====
              nmin = la_ilaenv(12,'XLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'XLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'XLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_xlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_xlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_xlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_xlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_xlaqr4 or
                       ! .    la_xlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_xlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_xlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_xlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_xlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_xlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=xdp)
     end subroutine la_xlaqr0
#endif
#ifdef LA_WITH_QP
     !> QLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_qlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           real(qp),parameter :: wilk2 = -0.4375_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_qlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(qp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_qlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'QLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'QLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_qlaqr3 ====
              call la_qlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_qlaqr5, la_qlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=qp)
                 return
              end if
              ! ==== la_qlahqr/la_qlaqr0 crossover point ====
              nmin = la_ilaenv(12,'QLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'QLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'QLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_qlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_qlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_qlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_qlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_qlaqr4 or
                       ! .    la_qlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_qlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_qlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_qlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_qlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr0
#endif

     !> Aggressive early deflation:
     !> SLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_slaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_sp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(sp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(sp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwk3,lwkopt,nmin
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,int,max,min,real,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_sgehrd ====
              call la_sgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_sormhr ====
              call la_sormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_slaqr4 ====
              call la_slaqr4(.true.,.true.,jw,1,jw,t,ldt,sr,si,1,jw,v,ldv,work,- &
                        1,infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=sp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_slacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_scopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_slaset('A',jw,jw,zero,one,v,ldv)
           nmin = la_ilaenv(12,'SLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_slaqr4(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,work,lwork,infqr)
           else
              call la_slahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,infqr)
           end if
           ! ==== la_strexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_strexc can not fail in this case.) ====
                    ifst = ns
                    call la_strexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_strexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_strexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_strexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_slanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_scopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_slarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_slaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_slarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_slarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_slarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_sgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_slacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_scopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_sormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_sgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_slacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_sgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_slacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_sgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_slacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=sp)
     end subroutine la_slaqr3
     !> Aggressive early deflation:
     !> DLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_dlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_dp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(dp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(dp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwk3,lwkopt,nmin
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_dgehrd ====
              call la_dgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_dormhr ====
              call la_dormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_dlaqr4 ====
              call la_dlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr,si,1,jw,v,ldv,work,- &
                        1,infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=dp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_dlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_dcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_dlaset('A',jw,jw,zero,one,v,ldv)
           nmin = la_ilaenv(12,'DLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_dlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,work,lwork,infqr)
           else
              call la_dlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,infqr)
           end if
           ! ==== la_dtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_dtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_dtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_dtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_dtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_dtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_dlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_dcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_dlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_dlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_dlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_dlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_dlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_dgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_dlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_dcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_dormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_dgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_dlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_dgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_dlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_dgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_dlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=dp)
     end subroutine la_dlaqr3
#ifdef LA_WITH_XDP
     !> Aggressive early deflation:
     !> XLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_xlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_xdp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(xdp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(xdp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwk3,lwkopt,nmin
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_xgehrd ====
              call la_xgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_xormhr ====
              call la_xormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_xlaqr4 ====
              call la_xlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr,si,1,jw,v,ldv,work,- &
                        1,infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=xdp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_xlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_xcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_xlaset('A',jw,jw,zero,one,v,ldv)
           nmin = la_ilaenv(12,'XLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_xlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,work,lwork,infqr)
           else
              call la_xlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,infqr)
           end if
           ! ==== la_xtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_xtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_xtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_xtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_xtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_xtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_xlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_xcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_xlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_xlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_xlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_xlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_xlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_xgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_xlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_xcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_xormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_xgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_xlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_xgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_xlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_xgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_xlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=xdp)
     end subroutine la_xlaqr3
#endif
#ifdef LA_WITH_QP
     !> Aggressive early deflation:
     !> QLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_qlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_qp,only:zero,one
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwk3,lwkopt,nmin
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_qgehrd ====
              call la_qgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qormhr ====
              call la_qormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qlaqr4 ====
              call la_qlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr,si,1,jw,v,ldv,work,- &
                        1,infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=qp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_qlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_qcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_qlaset('A',jw,jw,zero,one,v,ldv)
           nmin = la_ilaenv(12,'QLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_qlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,work,lwork,infqr)
           else
              call la_qlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,infqr)
           end if
           ! ==== la_qtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_qtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_qtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_qlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_qcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_qlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_qlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_qlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_qgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_qlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_qcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_qormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_qgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_qlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_qgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_qlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_qgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_qlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr3
#endif

     !> SLAQR4: implements one level of recursion for SLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by SLAQR0 and, for large enough
     !> deflation window size, it may be called by SLAQR3.  This
     !> subroutine is identical to SLAQR0 except that it calls SLAQR2
     !> instead of SLAQR3.
     !> SLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_slaqr4(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(sp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(sp),parameter :: wilk1 = 0.75_sp
           real(sp),parameter :: wilk2 = -0.4375_sp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_slahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(sp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(sp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,int,max,min,mod,real
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_slahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_slahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'SLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'SLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_slaqr2 ====
              call la_slaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_slaqr5, la_slaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=sp)
                 return
              end if
              ! ==== la_slahqr/la_slaqr0 crossover point ====
              nmin = la_ilaenv(12,'SLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'SLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'SLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_slaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_slaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_slaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_slanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_slahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_slacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_slahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr(ks &
                                    ),wi(ks),1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_slanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_slaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=sp)
     end subroutine la_slaqr4
     !> DLAQR4: implements one level of recursion for DLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by DLAQR0 and, for large enough
     !> deflation window size, it may be called by DLAQR3.  This
     !> subroutine is identical to DLAQR0 except that it calls DLAQR2
     !> instead of DLAQR3.
     !> DLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_dlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(dp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(dp),parameter :: wilk1 = 0.75_dp
           real(dp),parameter :: wilk2 = -0.4375_dp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_dlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(dp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(dp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_dlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_dlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_dlaqr2 ====
              call la_dlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_dlaqr5, la_dlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=dp)
                 return
              end if
              ! ==== la_dlahqr/la_dlaqr0 crossover point ====
              nmin = la_ilaenv(12,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_dlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_dlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_dlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_dlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_dlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_dlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_dlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr(ks &
                                    ),wi(ks),1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_dlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_dlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=dp)
     end subroutine la_dlaqr4
#ifdef LA_WITH_XDP
     !> XLAQR4: implements one level of recursion for XLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by XLAQR0 and, for large enough
     !> deflation window size, it may be called by XLAQR3.  This
     !> subroutine is identical to XLAQR0 except that it calls XLAQR2
     !> instead of XLAQR3.
     !> XLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_xlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(xdp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(xdp),parameter :: wilk1 = 0.75_xdp
           real(xdp),parameter :: wilk2 = -0.4375_xdp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_xlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(xdp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(xdp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_xlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_xlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'XLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'XLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_xlaqr2 ====
              call la_xlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_xlaqr5, la_xlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=xdp)
                 return
              end if
              ! ==== la_xlahqr/la_xlaqr0 crossover point ====
              nmin = la_ilaenv(12,'XLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'XLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'XLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_xlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_xlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_xlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_xlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_xlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_xlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_xlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr(ks &
                                    ),wi(ks),1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_xlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_xlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=xdp)
     end subroutine la_xlaqr4
#endif
#ifdef LA_WITH_QP
     !> QLAQR4: implements one level of recursion for QLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by QLAQR0 and, for large enough
     !> deflation window size, it may be called by QLAQR3.  This
     !> subroutine is identical to QLAQR0 except that it calls QLAQR2
     !> instead of QLAQR3.
     !> QLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_qlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           real(qp),parameter :: wilk2 = -0.4375_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_qlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(qp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_qlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'QLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'QLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_qlaqr2 ====
              call la_qlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_qlaqr5, la_qlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=qp)
                 return
              end if
              ! ==== la_qlahqr/la_qlaqr0 crossover point ====
              nmin = la_ilaenv(12,'QLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'QLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'QLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_qlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_qlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_qlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_qlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_qlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_qlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_qlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr(ks &
                                    ),wi(ks),1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_qlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr4
#endif

     !> SLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by SGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from SGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_slaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar, &
               alphai,beta,q,ldq,z,ldz,work,lwork,rec,info)
        use la_constants_sp,only:zero,one
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           real(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*),work(*)

           ! local scalars
           real(sp) :: smlnum,ulp,eshift,safmin,safmax,c1,s1,temp,swap
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost,i
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('SLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=sp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'SLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'SLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'SLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'SLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'SLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=sp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_shgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                         beta,q,ldq,z,ldz,work,lwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_slaqz3
           nw = max(nwr,nmin)
           call la_slaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work,nw,work,-1,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_slaqz4
           call la_slaqz4(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alphar,alphai,beta,a, &
                     lda,b,ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=sp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('SLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_slaset('FULL',n,n,zero,one,q,ldq)
           if (iwantz == 3) call la_slaset('FULL',n,n,zero,one,z,ldz)
           ! get machine constants
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 3*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop - 1,istop - 2)) <= max(smlnum,ulp*(abs(a(istop - 1,istop - 1)) + &
                        abs(a(istop - 2,istop - 2))))) then
                 a(istop - 1,istop - 2) = zero
                 istop = istop - 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + &
                        abs(a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = zero
                 istop = istop - 1
                 ld = 0
                 eshift = zero
              end if
              ! check deflations at the start
              if (abs(a(istart + 2,istart + 1)) <= max(smlnum,ulp*(abs(a(istart + 1,istart + 1 &
                        )) + abs(a(istart + 2,istart + 2))))) then
                 a(istart + 2,istart + 1) = zero
                 istart = istart + 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart) &
                         ) + abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = zero
                 istart = istart + 1
                 ld = 0
                 eshift = zero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = zero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 temp = zero
                 if (k < istop) then
                    temp = temp + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    temp = temp + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*temp)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_slartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = zero
                       call la_srot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_srot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_srot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_slartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = zero
                          call la_srot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_srot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_srot(n,q(1,k2),1,q(1,k2 + 1),1,c1,s1)
                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_slartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = zero
                       call la_srot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_srot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_srot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,s1)

                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = zero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using qz_small because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_slaqz3(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work(nw**2 + 1), &
                         nw,work(2*nw**2 + 1),lwork - 2*nw**2,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = zero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              ! shuffle shifts to put double shifts in front
              ! this ensures that we don't split up a double shift
              do i = shiftpos,shiftpos + n_undeflated - 1,2
                 if (alphai(i) /= -alphai(i + 1)) then
                    swap = alphar(i)
                    alphar(i) = alphar(i + 1)
                    alphar(i + 1) = alphar(i + 2)
                    alphar(i + 2) = swap
                    swap = alphai(i)
                    alphai(i) = alphai(i + 1)
                    alphai(i + 1) = alphai(i + 2)
                    alphai(i + 2) = swap
                    swap = beta(i)
                    beta(i) = beta(i + 1)
                    beta(i + 1) = beta(i + 2)
                    beta(i + 2) = swap
                 end if
              end do
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=sp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=sp))
                 end if
                 alphar(shiftpos) = one
                 alphar(shiftpos + 1) = zero
                 alphai(shiftpos) = zero
                 alphai(shiftpos + 1) = zero
                 beta(shiftpos) = eshift
                 beta(shiftpos + 1) = eshift
                 ns = 2
              end if
              ! time for a qz sweep
              call la_slaqz4(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alphar( &
              shiftpos),alphai(shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz, &
              work,nblock,work(nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2, &
                        sweep_info)
           end do
           ! call la_shgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_shgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_shgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                  beta,q,ldq,z,ldz,work,lwork,norm_info)
           info = norm_info
     end subroutine la_slaqz0
     !> DLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by DGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from DGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_dlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar, &
               alphai,beta,q,ldq,z,ldz,work,lwork,rec,info)
        use la_constants_dp,only:zero,one
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           real(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*),work(*)

           ! local scalars
           real(dp) :: smlnum,ulp,eshift,safmin,safmax,c1,s1,temp,swap
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost,i
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=dp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=dp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_dhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                         beta,q,ldq,z,ldz,work,lwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_dlaqz3
           nw = max(nwr,nmin)
           call la_dlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work,nw,work,-1,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_dlaqz4
           call la_dlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alphar,alphai,beta,a, &
                     lda,b,ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=dp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_dlaset('FULL',n,n,zero,one,q,ldq)
           if (iwantz == 3) call la_dlaset('FULL',n,n,zero,one,z,ldz)
           ! get machine constants
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 3*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop - 1,istop - 2)) <= max(smlnum,ulp*(abs(a(istop - 1,istop - 1)) + &
                        abs(a(istop - 2,istop - 2))))) then
                 a(istop - 1,istop - 2) = zero
                 istop = istop - 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + &
                        abs(a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = zero
                 istop = istop - 1
                 ld = 0
                 eshift = zero
              end if
              ! check deflations at the start
              if (abs(a(istart + 2,istart + 1)) <= max(smlnum,ulp*(abs(a(istart + 1,istart + 1 &
                        )) + abs(a(istart + 2,istart + 2))))) then
                 a(istart + 2,istart + 1) = zero
                 istart = istart + 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart) &
                         ) + abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = zero
                 istart = istart + 1
                 ld = 0
                 eshift = zero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = zero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 temp = zero
                 if (k < istop) then
                    temp = temp + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    temp = temp + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*temp)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_dlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = zero
                       call la_drot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_drot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_drot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_dlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = zero
                          call la_drot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_drot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_drot(n,q(1,k2),1,q(1,k2 + 1),1,c1,s1)
                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_dlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = zero
                       call la_drot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_drot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_drot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,s1)

                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = zero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using la_dhgeqz because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_dlaqz3(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work(nw**2 + 1), &
                         nw,work(2*nw**2 + 1),lwork - 2*nw**2,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = zero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              ! shuffle shifts to put double shifts in front
              ! this ensures that we don't split up a double shift
              do i = shiftpos,shiftpos + n_undeflated - 1,2
                 if (alphai(i) /= -alphai(i + 1)) then
                    swap = alphar(i)
                    alphar(i) = alphar(i + 1)
                    alphar(i + 1) = alphar(i + 2)
                    alphar(i + 2) = swap
                    swap = alphai(i)
                    alphai(i) = alphai(i + 1)
                    alphai(i + 1) = alphai(i + 2)
                    alphai(i + 2) = swap
                    swap = beta(i)
                    beta(i) = beta(i + 1)
                    beta(i + 1) = beta(i + 2)
                    beta(i + 2) = swap
                 end if
              end do
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=dp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=dp))
                 end if
                 alphar(shiftpos) = one
                 alphar(shiftpos + 1) = zero
                 alphai(shiftpos) = zero
                 alphai(shiftpos + 1) = zero
                 beta(shiftpos) = eshift
                 beta(shiftpos + 1) = eshift
                 ns = 2
              end if
              ! time for a qz sweep
              call la_dlaqz4(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alphar( &
              shiftpos),alphai(shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz, &
              work,nblock,work(nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2, &
                        sweep_info)
           end do
           ! call la_dhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_dhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_dhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                  beta,q,ldq,z,ldz,work,lwork,norm_info)
           info = norm_info
     end subroutine la_dlaqz0
#ifdef LA_WITH_XDP
     !> XLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by XGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from XGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_xlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar, &
               alphai,beta,q,ldq,z,ldz,work,lwork,rec,info)
        use la_constants_xdp,only:zero,one
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           real(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*),work(*)

           ! local scalars
           real(xdp) :: smlnum,ulp,eshift,safmin,safmax,c1,s1,temp,swap
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost,i
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('XLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=xdp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'XLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'XLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'XLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'XLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'XLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=xdp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_xhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                         beta,q,ldq,z,ldz,work,lwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_xlaqz3
           nw = max(nwr,nmin)
           call la_xlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work,nw,work,-1,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_xlaqz4
           call la_xlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alphar,alphai,beta,a, &
                     lda,b,ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=xdp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('XLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_xlaset('FULL',n,n,zero,one,q,ldq)
           if (iwantz == 3) call la_xlaset('FULL',n,n,zero,one,z,ldz)
           ! get machine constants
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 3*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop - 1,istop - 2)) <= max(smlnum,ulp*(abs(a(istop - 1,istop - 1)) + &
                        abs(a(istop - 2,istop - 2))))) then
                 a(istop - 1,istop - 2) = zero
                 istop = istop - 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + &
                        abs(a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = zero
                 istop = istop - 1
                 ld = 0
                 eshift = zero
              end if
              ! check deflations at the start
              if (abs(a(istart + 2,istart + 1)) <= max(smlnum,ulp*(abs(a(istart + 1,istart + 1 &
                        )) + abs(a(istart + 2,istart + 2))))) then
                 a(istart + 2,istart + 1) = zero
                 istart = istart + 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart) &
                         ) + abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = zero
                 istart = istart + 1
                 ld = 0
                 eshift = zero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = zero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 temp = zero
                 if (k < istop) then
                    temp = temp + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    temp = temp + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*temp)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_xlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = zero
                       call la_xrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_xrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_xrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_xlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = zero
                          call la_xrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_xrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_xrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,s1)
                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_xlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = zero
                       call la_xrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_xrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_xrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,s1)

                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = zero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using la_xhgeqz because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_xlaqz3(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work(nw**2 + 1), &
                         nw,work(2*nw**2 + 1),lwork - 2*nw**2,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = zero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              ! shuffle shifts to put double shifts in front
              ! this ensures that we don't split up a double shift
              do i = shiftpos,shiftpos + n_undeflated - 1,2
                 if (alphai(i) /= -alphai(i + 1)) then
                    swap = alphar(i)
                    alphar(i) = alphar(i + 1)
                    alphar(i + 1) = alphar(i + 2)
                    alphar(i + 2) = swap
                    swap = alphai(i)
                    alphai(i) = alphai(i + 1)
                    alphai(i + 1) = alphai(i + 2)
                    alphai(i + 2) = swap
                    swap = beta(i)
                    beta(i) = beta(i + 1)
                    beta(i + 1) = beta(i + 2)
                    beta(i + 2) = swap
                 end if
              end do
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=xdp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=xdp))
                 end if
                 alphar(shiftpos) = one
                 alphar(shiftpos + 1) = zero
                 alphai(shiftpos) = zero
                 alphai(shiftpos + 1) = zero
                 beta(shiftpos) = eshift
                 beta(shiftpos + 1) = eshift
                 ns = 2
              end if
              ! time for a qz sweep
              call la_xlaqz4(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alphar( &
              shiftpos),alphai(shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz, &
              work,nblock,work(nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2, &
                        sweep_info)
           end do
           ! call la_xhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_xhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_xhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                  beta,q,ldq,z,ldz,work,lwork,norm_info)
           info = norm_info
     end subroutine la_xlaqz0
#endif
#ifdef LA_WITH_QP
     !> QLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by QGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from QGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_qlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar, &
               alphai,beta,q,ldq,z,ldz,work,lwork,rec,info)
        use la_constants_qp,only:zero,one
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*),work(*)

           ! local scalars
           real(qp) :: smlnum,ulp,eshift,safmin,safmax,c1,s1,temp,swap
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost,i
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('QLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=qp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'QLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'QLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'QLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'QLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'QLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=qp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_qhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                         beta,q,ldq,z,ldz,work,lwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_qlaqz3
           nw = max(nwr,nmin)
           call la_qlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work,nw,work,-1,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_qlaqz4
           call la_qlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alphar,alphai,beta,a, &
                     lda,b,ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=qp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('QLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           if (iwantz == 3) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 3*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop - 1,istop - 2)) <= max(smlnum,ulp*(abs(a(istop - 1,istop - 1)) + &
                        abs(a(istop - 2,istop - 2))))) then
                 a(istop - 1,istop - 2) = zero
                 istop = istop - 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + &
                        abs(a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = zero
                 istop = istop - 1
                 ld = 0
                 eshift = zero
              end if
              ! check deflations at the start
              if (abs(a(istart + 2,istart + 1)) <= max(smlnum,ulp*(abs(a(istart + 1,istart + 1 &
                        )) + abs(a(istart + 2,istart + 2))))) then
                 a(istart + 2,istart + 1) = zero
                 istart = istart + 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart) &
                         ) + abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = zero
                 istart = istart + 1
                 ld = 0
                 eshift = zero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = zero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 temp = zero
                 if (k < istop) then
                    temp = temp + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    temp = temp + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*temp)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_qlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = zero
                       call la_qrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_qrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_qrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_qlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = zero
                          call la_qrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_qrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_qrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,s1)
                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_qlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = zero
                       call la_qrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_qrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_qrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,s1)

                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = zero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using la_qhgeqz because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_qlaqz3(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alphar,alphai,beta,work,nw,work(nw**2 + 1), &
                         nw,work(2*nw**2 + 1),lwork - 2*nw**2,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = zero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              ! shuffle shifts to put double shifts in front
              ! this ensures that we don't split up a double shift
              do i = shiftpos,shiftpos + n_undeflated - 1,2
                 if (alphai(i) /= -alphai(i + 1)) then
                    swap = alphar(i)
                    alphar(i) = alphar(i + 1)
                    alphar(i + 1) = alphar(i + 2)
                    alphar(i + 2) = swap
                    swap = alphai(i)
                    alphai(i) = alphai(i + 1)
                    alphai(i + 1) = alphai(i + 2)
                    alphai(i + 2) = swap
                    swap = beta(i)
                    beta(i) = beta(i + 1)
                    beta(i + 1) = beta(i + 2)
                    beta(i + 2) = swap
                 end if
              end do
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=qp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=qp))
                 end if
                 alphar(shiftpos) = one
                 alphar(shiftpos + 1) = zero
                 alphai(shiftpos) = zero
                 alphai(shiftpos + 1) = zero
                 beta(shiftpos) = eshift
                 beta(shiftpos + 1) = eshift
                 ns = 2
              end if
              ! time for a qz sweep
              call la_qlaqz4(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alphar( &
              shiftpos),alphai(shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz, &
              work,nblock,work(nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2, &
                        sweep_info)
           end do
           ! call la_qhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_qhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_qhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                  beta,q,ldq,z,ldz,work,lwork,norm_info)
           info = norm_info
     end subroutine la_qlaqz0
#endif

     !> SLAQZ3: performs AED

     recursive subroutine la_slaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,lwork,rec,info)
        use la_constants_sp,only:zero,one
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           real(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           real(sp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           real(sp),intent(out) :: work(*)

           ! local scalars
           logical(lk) :: bulge
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,stgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(sp) :: s,smlnum,ulp,safmin,safmax,c1,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = zero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_stgexc(.true.,.true.,jw,a,lda,b,ldb,qc,ldqc,zc,ldzc,ifst,ilst, &
                     work,-1,stgexc_info)
           lworkreq = int(work(1),KIND=ilp)
           call la_slaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,-1,rec + 1,qz_small_info)
           lworkreq = max(lworkreq,int(work(1),KIND=ilp) + 2*jw**2)
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('SLAQZ3',-info)
              return
           end if
           ! get machine constants
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alphar(kwtop) = a(kwtop,kwtop)
              alphai(kwtop) = zero
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = zero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_slacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_slacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_slaset('FULL',jw,jw,zero,one,qc,ldqc)
           call la_slaset('FULL',jw,jw,zero,one,zc,ldzc)
           call la_slaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_slacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_slacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == zero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                 bulge = .false.
                 if (kwbot - kwtop + 1 >= 2) then
                    bulge = a(kwbot,kwbot - 1) /= zero
                 end if
                 if (bulge) then
                    ! try to deflate complex conjugate eigenvalue pair
                    temp = abs(a(kwbot,kwbot)) + sqrt(abs(a(kwbot,kwbot - 1)))*sqrt(abs( &
                              a(kwbot - 1,kwbot)))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if (max(abs(s*qc(1,kwbot - kwtop)),abs(s*qc(1,kwbot - kwtop + 1))) <= &
                              max(smlnum,ulp*temp)) then
                       ! deflatable
                       kwbot = kwbot - 2
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_stgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,stgexc_info)

                       k2 = k2 + 2
                    end if
                    k = k + 2
                 else
                    ! try to deflate real eigenvalue
                    temp = abs(a(kwbot,kwbot))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*temp,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_stgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,stgexc_info)

                       k2 = k2 + 1
                    end if
                    k = k + 1
                 end if
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              bulge = .false.
              if (k < ihi) then
                 if (a(k + 1,k) /= zero) then
                    bulge = .true.
                 end if
              end if
              if (bulge) then
                 ! 2x2 eigenvalue block
                 call la_slag2(a(k,k),lda,b(k,k),ldb,safmin,beta(k),beta(k + 1), &
                            alphar(k),alphar(k + 1),alphai(k))
                 alphai(k + 1) = -alphai(k)
                 k = k + 2
              else
                 ! 1x1 eigenvalue block
                 alphar(k) = a(k,k)
                 alphai(k) = zero
                 beta(k) = b(k,k)
                 k = k + 1
              end if
           end do
           if (kwtop /= ilo .and. s /= zero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*qc(1,1:jw - nd)
              do k = kwbot - 1,kwtop,-1
                 call la_slartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = zero
                 k2 = max(kwtop,k - 1)
                 call la_srot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_srot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_srot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,s1)

              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 if ((k >= kwtop + 1) .and. a(k + 1,k - 1) /= zero) then
                    ! move double pole block down and remove it
                    do k2 = k - 1,kwbot - 2
                       call la_slaqz2(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                                  ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                    end do
                    k = k - 2
                 else
                    ! k points to single shift
                    do k2 = k,kwbot - 2
                       ! move shift down
                       call la_slartg(b(k2 + 1,k2 + 1),b(k2 + 1,k2),c1,s1,temp)
                       b(k2 + 1,k2 + 1) = temp
                       b(k2 + 1,k2) = zero
                       call la_srot(k2 + 2 - istartm + 1,a(istartm,k2 + 1),1,a(istartm,k2), &
                                 1,c1,s1)
                       call la_srot(k2 - istartm + 1,b(istartm,k2 + 1),1,b(istartm,k2),1, &
                                 c1,s1)
                       call la_srot(jw,zc(1,k2 + 1 - kwtop + 1),1,zc(1,k2 - kwtop + 1),1,c1, &
                                 s1)
                       call la_slartg(a(k2 + 1,k2),a(k2 + 2,k2),c1,s1,temp)
                       a(k2 + 1,k2) = temp
                       a(k2 + 2,k2) = zero
                       call la_srot(istopm - k2,a(k2 + 1,k2 + 1),lda,a(k2 + 2,k2 + 1),lda,c1, &
                                  s1)
                       call la_srot(istopm - k2,b(k2 + 1,k2 + 1),ldb,b(k2 + 2,k2 + 1),ldb,c1, &
                                  s1)
                       call la_srot(jw,qc(1,k2 + 1 - kwtop + 1),1,qc(1,k2 + 2 - kwtop + 1),1, &
                                 c1,s1)
                    end do
                    ! remove the shift
                    call la_slartg(b(kwbot,kwbot),b(kwbot,kwbot - 1),c1,s1,temp)

                    b(kwbot,kwbot) = temp
                    b(kwbot,kwbot - 1) = zero
                    call la_srot(kwbot - istartm,b(istartm,kwbot),1,b(istartm,kwbot - 1), &
                               1,c1,s1)
                    call la_srot(kwbot - istartm + 1,a(istartm,kwbot),1,a(istartm,kwbot - 1 &
                              ),1,c1,s1)
                    call la_srot(jw,zc(1,kwbot - kwtop + 1),1,zc(1,kwbot - 1 - kwtop + 1),1, &
                              c1,s1)
                    k = k - 1
                 end if
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_sgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,zero,work,jw)
              call la_slacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_sgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,zero,work,jw)
              call la_slacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_sgemm('N','N',n,jw,jw,one,q(1,kwtop),ldq,qc,ldqc,zero, &
                        work,n)
              call la_slacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_sgemm('N','N',kwtop - istartm,jw,jw,one,a(istartm,kwtop),lda, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_slacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop &
                        ),lda)
              call la_sgemm('N','N',kwtop - istartm,jw,jw,one,b(istartm,kwtop),ldb, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_slacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop &
                        ),ldb)
           end if
           if (ilz) then
              call la_sgemm('N','N',n,jw,jw,one,z(1,kwtop),ldz,zc,ldzc,zero, &
                        work,n)
              call la_slacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_slaqz3
     !> DLAQZ3: performs AED

     recursive subroutine la_dlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,lwork,rec,info)
        use la_constants_dp,only:zero,one
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           real(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           real(dp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           real(dp),intent(out) :: work(*)

           ! local scalars
           logical(lk) :: bulge
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,dtgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(dp) :: s,smlnum,ulp,safmin,safmax,c1,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = zero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_dtgexc(.true.,.true.,jw,a,lda,b,ldb,qc,ldqc,zc,ldzc,ifst,ilst, &
                     work,-1,dtgexc_info)
           lworkreq = int(work(1),KIND=ilp)
           call la_dlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,-1,rec + 1,qz_small_info)
           lworkreq = max(lworkreq,int(work(1),KIND=ilp) + 2*jw**2)
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ3',-info)
              return
           end if
           ! get machine constants
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alphar(kwtop) = a(kwtop,kwtop)
              alphai(kwtop) = zero
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = zero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_dlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_dlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_dlaset('FULL',jw,jw,zero,one,qc,ldqc)
           call la_dlaset('FULL',jw,jw,zero,one,zc,ldzc)
           call la_dlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_dlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_dlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == zero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                 bulge = .false.
                 if (kwbot - kwtop + 1 >= 2) then
                    bulge = a(kwbot,kwbot - 1) /= zero
                 end if
                 if (bulge) then
                    ! try to deflate complex conjugate eigenvalue pair
                    temp = abs(a(kwbot,kwbot)) + sqrt(abs(a(kwbot,kwbot - 1)))*sqrt(abs( &
                              a(kwbot - 1,kwbot)))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if (max(abs(s*qc(1,kwbot - kwtop)),abs(s*qc(1,kwbot - kwtop + 1))) <= &
                              max(smlnum,ulp*temp)) then
                       ! deflatable
                       kwbot = kwbot - 2
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_dtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,dtgexc_info)

                       k2 = k2 + 2
                    end if
                    k = k + 2
                 else
                    ! try to deflate real eigenvalue
                    temp = abs(a(kwbot,kwbot))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*temp,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_dtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,dtgexc_info)

                       k2 = k2 + 1
                    end if
                    k = k + 1
                 end if
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              bulge = .false.
              if (k < ihi) then
                 if (a(k + 1,k) /= zero) then
                    bulge = .true.
                 end if
              end if
              if (bulge) then
                 ! 2x2 eigenvalue block
                 call la_dlag2(a(k,k),lda,b(k,k),ldb,safmin,beta(k),beta(k + 1), &
                            alphar(k),alphar(k + 1),alphai(k))
                 alphai(k + 1) = -alphai(k)
                 k = k + 2
              else
                 ! 1x1 eigenvalue block
                 alphar(k) = a(k,k)
                 alphai(k) = zero
                 beta(k) = b(k,k)
                 k = k + 1
              end if
           end do
           if (kwtop /= ilo .and. s /= zero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*qc(1,1:jw - nd)
              do k = kwbot - 1,kwtop,-1
                 call la_dlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = zero
                 k2 = max(kwtop,k - 1)
                 call la_drot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_drot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_drot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,s1)

              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 if ((k >= kwtop + 1) .and. a(k + 1,k - 1) /= zero) then
                    ! move double pole block down and remove it
                    do k2 = k - 1,kwbot - 2
                       call la_dlaqz2(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                                  ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                    end do
                    k = k - 2
                 else
                    ! k points to single shift
                    do k2 = k,kwbot - 2
                       ! move shift down
                       call la_dlartg(b(k2 + 1,k2 + 1),b(k2 + 1,k2),c1,s1,temp)
                       b(k2 + 1,k2 + 1) = temp
                       b(k2 + 1,k2) = zero
                       call la_drot(k2 + 2 - istartm + 1,a(istartm,k2 + 1),1,a(istartm,k2), &
                                 1,c1,s1)
                       call la_drot(k2 - istartm + 1,b(istartm,k2 + 1),1,b(istartm,k2),1, &
                                 c1,s1)
                       call la_drot(jw,zc(1,k2 + 1 - kwtop + 1),1,zc(1,k2 - kwtop + 1),1,c1, &
                                 s1)
                       call la_dlartg(a(k2 + 1,k2),a(k2 + 2,k2),c1,s1,temp)
                       a(k2 + 1,k2) = temp
                       a(k2 + 2,k2) = zero
                       call la_drot(istopm - k2,a(k2 + 1,k2 + 1),lda,a(k2 + 2,k2 + 1),lda,c1, &
                                  s1)
                       call la_drot(istopm - k2,b(k2 + 1,k2 + 1),ldb,b(k2 + 2,k2 + 1),ldb,c1, &
                                  s1)
                       call la_drot(jw,qc(1,k2 + 1 - kwtop + 1),1,qc(1,k2 + 2 - kwtop + 1),1, &
                                 c1,s1)
                    end do
                    ! remove the shift
                    call la_dlartg(b(kwbot,kwbot),b(kwbot,kwbot - 1),c1,s1,temp)

                    b(kwbot,kwbot) = temp
                    b(kwbot,kwbot - 1) = zero
                    call la_drot(kwbot - istartm,b(istartm,kwbot),1,b(istartm,kwbot - 1), &
                               1,c1,s1)
                    call la_drot(kwbot - istartm + 1,a(istartm,kwbot),1,a(istartm,kwbot - 1 &
                              ),1,c1,s1)
                    call la_drot(jw,zc(1,kwbot - kwtop + 1),1,zc(1,kwbot - 1 - kwtop + 1),1, &
                              c1,s1)
                    k = k - 1
                 end if
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_dgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,zero,work,jw)
              call la_dlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_dgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,zero,work,jw)
              call la_dlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_dgemm('N','N',n,jw,jw,one,q(1,kwtop),ldq,qc,ldqc,zero, &
                        work,n)
              call la_dlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_dgemm('N','N',kwtop - istartm,jw,jw,one,a(istartm,kwtop),lda, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_dlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop &
                        ),lda)
              call la_dgemm('N','N',kwtop - istartm,jw,jw,one,b(istartm,kwtop),ldb, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_dlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop &
                        ),ldb)
           end if
           if (ilz) then
              call la_dgemm('N','N',n,jw,jw,one,z(1,kwtop),ldz,zc,ldzc,zero, &
                        work,n)
              call la_dlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_dlaqz3
#ifdef LA_WITH_XDP
     !> XLAQZ3: performs AED

     recursive subroutine la_xlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,lwork,rec,info)
        use la_constants_xdp,only:zero,one
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           real(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           real(xdp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           real(xdp),intent(out) :: work(*)

           ! local scalars
           logical(lk) :: bulge
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,xtgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(xdp) :: s,smlnum,ulp,safmin,safmax,c1,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = zero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_xtgexc(.true.,.true.,jw,a,lda,b,ldb,qc,ldqc,zc,ldzc,ifst,ilst, &
                     work,-1,xtgexc_info)
           lworkreq = int(work(1),KIND=ilp)
           call la_xlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,-1,rec + 1,qz_small_info)
           lworkreq = max(lworkreq,int(work(1),KIND=ilp) + 2*jw**2)
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('XLAQZ3',-info)
              return
           end if
           ! get machine constants
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alphar(kwtop) = a(kwtop,kwtop)
              alphai(kwtop) = zero
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = zero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_xlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_xlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_xlaset('FULL',jw,jw,zero,one,qc,ldqc)
           call la_xlaset('FULL',jw,jw,zero,one,zc,ldzc)
           call la_xlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_xlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_xlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == zero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                 bulge = .false.
                 if (kwbot - kwtop + 1 >= 2) then
                    bulge = a(kwbot,kwbot - 1) /= zero
                 end if
                 if (bulge) then
                    ! try to deflate complex conjugate eigenvalue pair
                    temp = abs(a(kwbot,kwbot)) + sqrt(abs(a(kwbot,kwbot - 1)))*sqrt(abs( &
                              a(kwbot - 1,kwbot)))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if (max(abs(s*qc(1,kwbot - kwtop)),abs(s*qc(1,kwbot - kwtop + 1))) <= &
                              max(smlnum,ulp*temp)) then
                       ! deflatable
                       kwbot = kwbot - 2
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_xtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,xtgexc_info)

                       k2 = k2 + 2
                    end if
                    k = k + 2
                 else
                    ! try to deflate real eigenvalue
                    temp = abs(a(kwbot,kwbot))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*temp,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_xtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,xtgexc_info)

                       k2 = k2 + 1
                    end if
                    k = k + 1
                 end if
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              bulge = .false.
              if (k < ihi) then
                 if (a(k + 1,k) /= zero) then
                    bulge = .true.
                 end if
              end if
              if (bulge) then
                 ! 2x2 eigenvalue block
                 call la_xlag2(a(k,k),lda,b(k,k),ldb,safmin,beta(k),beta(k + 1), &
                            alphar(k),alphar(k + 1),alphai(k))
                 alphai(k + 1) = -alphai(k)
                 k = k + 2
              else
                 ! 1x1 eigenvalue block
                 alphar(k) = a(k,k)
                 alphai(k) = zero
                 beta(k) = b(k,k)
                 k = k + 1
              end if
           end do
           if (kwtop /= ilo .and. s /= zero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*qc(1,1:jw - nd)
              do k = kwbot - 1,kwtop,-1
                 call la_xlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = zero
                 k2 = max(kwtop,k - 1)
                 call la_xrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_xrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_xrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,s1)

              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 if ((k >= kwtop + 1) .and. a(k + 1,k - 1) /= zero) then
                    ! move double pole block down and remove it
                    do k2 = k - 1,kwbot - 2
                       call la_xlaqz2(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                                  ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                    end do
                    k = k - 2
                 else
                    ! k points to single shift
                    do k2 = k,kwbot - 2
                       ! move shift down
                       call la_xlartg(b(k2 + 1,k2 + 1),b(k2 + 1,k2),c1,s1,temp)
                       b(k2 + 1,k2 + 1) = temp
                       b(k2 + 1,k2) = zero
                       call la_xrot(k2 + 2 - istartm + 1,a(istartm,k2 + 1),1,a(istartm,k2), &
                                 1,c1,s1)
                       call la_xrot(k2 - istartm + 1,b(istartm,k2 + 1),1,b(istartm,k2),1, &
                                 c1,s1)
                       call la_xrot(jw,zc(1,k2 + 1 - kwtop + 1),1,zc(1,k2 - kwtop + 1),1,c1, &
                                 s1)
                       call la_xlartg(a(k2 + 1,k2),a(k2 + 2,k2),c1,s1,temp)
                       a(k2 + 1,k2) = temp
                       a(k2 + 2,k2) = zero
                       call la_xrot(istopm - k2,a(k2 + 1,k2 + 1),lda,a(k2 + 2,k2 + 1),lda,c1, &
                                  s1)
                       call la_xrot(istopm - k2,b(k2 + 1,k2 + 1),ldb,b(k2 + 2,k2 + 1),ldb,c1, &
                                  s1)
                       call la_xrot(jw,qc(1,k2 + 1 - kwtop + 1),1,qc(1,k2 + 2 - kwtop + 1),1, &
                                 c1,s1)
                    end do
                    ! remove the shift
                    call la_xlartg(b(kwbot,kwbot),b(kwbot,kwbot - 1),c1,s1,temp)

                    b(kwbot,kwbot) = temp
                    b(kwbot,kwbot - 1) = zero
                    call la_xrot(kwbot - istartm,b(istartm,kwbot),1,b(istartm,kwbot - 1), &
                               1,c1,s1)
                    call la_xrot(kwbot - istartm + 1,a(istartm,kwbot),1,a(istartm,kwbot - 1 &
                              ),1,c1,s1)
                    call la_xrot(jw,zc(1,kwbot - kwtop + 1),1,zc(1,kwbot - 1 - kwtop + 1),1, &
                              c1,s1)
                    k = k - 1
                 end if
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_xgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,zero,work,jw)
              call la_xlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_xgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,zero,work,jw)
              call la_xlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_xgemm('N','N',n,jw,jw,one,q(1,kwtop),ldq,qc,ldqc,zero, &
                        work,n)
              call la_xlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_xgemm('N','N',kwtop - istartm,jw,jw,one,a(istartm,kwtop),lda, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_xlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop &
                        ),lda)
              call la_xgemm('N','N',kwtop - istartm,jw,jw,one,b(istartm,kwtop),ldb, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_xlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop &
                        ),ldb)
           end if
           if (ilz) then
              call la_xgemm('N','N',n,jw,jw,one,z(1,kwtop),ldz,zc,ldzc,zero, &
                        work,n)
              call la_xlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_xlaqz3
#endif
#ifdef LA_WITH_QP
     !> QLAQZ3: performs AED

     recursive subroutine la_qlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,lwork,rec,info)
        use la_constants_qp,only:zero,one
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           real(qp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           real(qp),intent(out) :: work(*)

           ! local scalars
           logical(lk) :: bulge
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,qtgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(qp) :: s,smlnum,ulp,safmin,safmax,c1,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = zero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_qtgexc(.true.,.true.,jw,a,lda,b,ldb,qc,ldqc,zc,ldzc,ifst,ilst, &
                     work,-1,qtgexc_info)
           lworkreq = int(work(1),KIND=ilp)
           call la_qlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,-1,rec + 1,qz_small_info)
           lworkreq = max(lworkreq,int(work(1),KIND=ilp) + 2*jw**2)
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('QLAQZ3',-info)
              return
           end if
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alphar(kwtop) = a(kwtop,kwtop)
              alphai(kwtop) = zero
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = zero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_qlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_qlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_qlaset('FULL',jw,jw,zero,one,qc,ldqc)
           call la_qlaset('FULL',jw,jw,zero,one,zc,ldzc)
           call la_qlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_qlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_qlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == zero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                 bulge = .false.
                 if (kwbot - kwtop + 1 >= 2) then
                    bulge = a(kwbot,kwbot - 1) /= zero
                 end if
                 if (bulge) then
                    ! try to deflate complex conjugate eigenvalue pair
                    temp = abs(a(kwbot,kwbot)) + sqrt(abs(a(kwbot,kwbot - 1)))*sqrt(abs( &
                              a(kwbot - 1,kwbot)))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if (max(abs(s*qc(1,kwbot - kwtop)),abs(s*qc(1,kwbot - kwtop + 1))) <= &
                              max(smlnum,ulp*temp)) then
                       ! deflatable
                       kwbot = kwbot - 2
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_qtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,qtgexc_info)

                       k2 = k2 + 2
                    end if
                    k = k + 2
                 else
                    ! try to deflate real eigenvalue
                    temp = abs(a(kwbot,kwbot))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*temp,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_qtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,qtgexc_info)

                       k2 = k2 + 1
                    end if
                    k = k + 1
                 end if
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              bulge = .false.
              if (k < ihi) then
                 if (a(k + 1,k) /= zero) then
                    bulge = .true.
                 end if
              end if
              if (bulge) then
                 ! 2x2 eigenvalue block
                 call la_qlag2(a(k,k),lda,b(k,k),ldb,safmin,beta(k),beta(k + 1), &
                            alphar(k),alphar(k + 1),alphai(k))
                 alphai(k + 1) = -alphai(k)
                 k = k + 2
              else
                 ! 1x1 eigenvalue block
                 alphar(k) = a(k,k)
                 alphai(k) = zero
                 beta(k) = b(k,k)
                 k = k + 1
              end if
           end do
           if (kwtop /= ilo .and. s /= zero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*qc(1,1:jw - nd)
              do k = kwbot - 1,kwtop,-1
                 call la_qlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = zero
                 k2 = max(kwtop,k - 1)
                 call la_qrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_qrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_qrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,s1)

              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 if ((k >= kwtop + 1) .and. a(k + 1,k - 1) /= zero) then
                    ! move double pole block down and remove it
                    do k2 = k - 1,kwbot - 2
                       call la_qlaqz2(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                                  ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                    end do
                    k = k - 2
                 else
                    ! k points to single shift
                    do k2 = k,kwbot - 2
                       ! move shift down
                       call la_qlartg(b(k2 + 1,k2 + 1),b(k2 + 1,k2),c1,s1,temp)
                       b(k2 + 1,k2 + 1) = temp
                       b(k2 + 1,k2) = zero
                       call la_qrot(k2 + 2 - istartm + 1,a(istartm,k2 + 1),1,a(istartm,k2), &
                                 1,c1,s1)
                       call la_qrot(k2 - istartm + 1,b(istartm,k2 + 1),1,b(istartm,k2),1, &
                                 c1,s1)
                       call la_qrot(jw,zc(1,k2 + 1 - kwtop + 1),1,zc(1,k2 - kwtop + 1),1,c1, &
                                 s1)
                       call la_qlartg(a(k2 + 1,k2),a(k2 + 2,k2),c1,s1,temp)
                       a(k2 + 1,k2) = temp
                       a(k2 + 2,k2) = zero
                       call la_qrot(istopm - k2,a(k2 + 1,k2 + 1),lda,a(k2 + 2,k2 + 1),lda,c1, &
                                  s1)
                       call la_qrot(istopm - k2,b(k2 + 1,k2 + 1),ldb,b(k2 + 2,k2 + 1),ldb,c1, &
                                  s1)
                       call la_qrot(jw,qc(1,k2 + 1 - kwtop + 1),1,qc(1,k2 + 2 - kwtop + 1),1, &
                                 c1,s1)
                    end do
                    ! remove the shift
                    call la_qlartg(b(kwbot,kwbot),b(kwbot,kwbot - 1),c1,s1,temp)

                    b(kwbot,kwbot) = temp
                    b(kwbot,kwbot - 1) = zero
                    call la_qrot(kwbot - istartm,b(istartm,kwbot),1,b(istartm,kwbot - 1), &
                               1,c1,s1)
                    call la_qrot(kwbot - istartm + 1,a(istartm,kwbot),1,a(istartm,kwbot - 1 &
                              ),1,c1,s1)
                    call la_qrot(jw,zc(1,kwbot - kwtop + 1),1,zc(1,kwbot - 1 - kwtop + 1),1, &
                              c1,s1)
                    k = k - 1
                 end if
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_qgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,zero,work,jw)
              call la_qlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_qgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,zero,work,jw)
              call la_qlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_qgemm('N','N',n,jw,jw,one,q(1,kwtop),ldq,qc,ldqc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_qgemm('N','N',kwtop - istartm,jw,jw,one,a(istartm,kwtop),lda, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_qlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop &
                        ),lda)
              call la_qgemm('N','N',kwtop - istartm,jw,jw,one,b(istartm,kwtop),ldb, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_qlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop &
                        ),ldb)
           end if
           if (ilz) then
              call la_qgemm('N','N',n,jw,jw,one,z(1,kwtop),ldz,zc,ldzc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_qlaqz3
#endif

     !> Given a 2-by-2 or 3-by-3 matrix H, CLAQR1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (H - s1*I)*(H - s2*I)
     !> scaling to avoid overflows and most underflows.
     !> This is useful for starting double implicit shift bulges
     !> in the QR algorithm.

     pure subroutine la_claqr1(n,h,ldh,s1,s2,v)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           complex(sp),intent(in) :: s1,s2
           integer(ilp),intent(in) :: ldh,n
           ! Array Arguments
           complex(sp),intent(in) :: h(ldh,*)
           complex(sp),intent(out) :: v(*)
        ! ================================================================
           ! Parameters
           real(sp),parameter :: rzero = 0.0_sp

           ! Local Scalars
           complex(sp) :: cdum,h21s,h31s
           real(sp) :: s
           ! Intrinsic Functions
           intrinsic :: abs,aimag,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           ! quick return if possible
           if (n /= 2 .and. n /= 3) then
              return
           end if
           if (n == 2) then
              s = cabs1(h(1,1) - s2) + cabs1(h(2,1))
              if (s == rzero) then
                 v(1) = czero
                 v(2) = czero
              else
                 h21s = h(2,1)/s
                 v(1) = h21s*h(1,2) + (h(1,1) - s1)*((h(1,1) - s2)/s)
                 v(2) = h21s*(h(1,1) + h(2,2) - s1 - s2)
              end if
           else
              s = cabs1(h(1,1) - s2) + cabs1(h(2,1)) + cabs1(h(3,1))
              if (s == czero) then
                 v(1) = czero
                 v(2) = czero
                 v(3) = czero
              else
                 h21s = h(2,1)/s
                 h31s = h(3,1)/s
                 v(1) = (h(1,1) - s1)*((h(1,1) - s2)/s) + h(1,2)*h21s + h(1,3) &
                           *h31s
                 v(2) = h21s*(h(1,1) + h(2,2) - s1 - s2) + h(2,3)*h31s
                 v(3) = h31s*(h(1,1) + h(3,3) - s1 - s2) + h21s*h(3,2)
              end if
           end if
     end subroutine la_claqr1
