     !> CLAHQR: is an auxiliary routine called by CHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by CHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_clahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,info &
               )
        use la_constants_sp,only:half,czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(sp),intent(out) :: w(*)
        ! =========================================================
           ! Parameters
           real(sp),parameter :: rzero = 0.0_sp
           real(sp),parameter :: rone = 1.0_sp
           real(sp),parameter :: dat1 = 3.0_sp/4.0_sp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           complex(sp) :: cdum,h11,h11s,h22,sc,sum,t,t1,temp,u,v2,x,y
           real(sp) :: aa,ab,ba,bb,h10,h21,rtemp,s,safmax,safmin,smlnum,sx,t2,tst, &
                     ulp
           integer(ilp) :: i,i1,i2,its,itmax,j,jhi,jlo,k,l,m,nh,nz,kdefl
           ! Local Arrays
           complex(sp) :: v(2)
           ! Statement Functions
           real(sp) :: cabs1
           ! Intrinsic Functions
           intrinsic :: abs,aimag,conjg,max,min,real,sqrt
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              w(ilo) = h(ilo,ilo)
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = czero
              h(j + 3,j) = czero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = czero
           ! ==== ensure that subdiagonal entries are real ====
           if (wantt) then
              jlo = 1
              jhi = n
           else
              jlo = ilo
              jhi = ihi
           end if
           do i = ilo + 1,ihi
              if (aimag(h(i,i - 1)) /= rzero) then
                 ! ==== the following redundant normalization
                 ! .    avoids problems with both gradual and
                 ! .    sudden underflow in abs(h(i,i-1)) ====
                 sc = h(i,i - 1)/cabs1(h(i,i - 1))
                 sc = conjg(sc)/abs(sc)
                 h(i,i - 1) = abs(h(i,i - 1))
                 call la_cscal(jhi - i + 1,sc,h(i,i),ldh)
                 call la_cscal(min(jhi,i + 1) - jlo + 1,conjg(sc),h(jlo,i),1)
                 if (wantz) call la_cscal(ihiz - iloz + 1,conjg(sc),z(iloz,i),1)
              end if
           end do
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_slamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=sp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo, or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           30 continue
           if (i < ilo) go to 150
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           l = ilo
           loop_130: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (cabs1(h(k,k - 1)) <= smlnum) go to 50
                 tst = cabs1(h(k - 1,k - 1)) + cabs1(h(k,k))
                 if (tst == czero) then
                    if (k - 2 >= ilo) tst = tst + abs(real(h(k - 1,k - 2),KIND=sp))
                    if (k + 1 <= ihi) tst = tst + abs(real(h(k + 1,k),KIND=sp))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some examples.  ====
                 if (abs(real(h(k,k - 1),KIND=sp)) <= ulp*tst) then
                    ab = max(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    ba = min(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    aa = max(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    bb = min(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 50
                 end if
              end do
              50 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = czero
              end if
              ! exit from loop if a submatrix of order 1 has split off.
              if (l >= i) go to 140
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(i,i - 1),KIND=sp))
                 t = s + h(i,i)
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(l + 1,l),KIND=sp))
                 t = s + h(l,l)
              else
                 ! wilkinson's shift.
                 t = h(i,i)
                 u = sqrt(h(i - 1,i))*sqrt(h(i,i - 1))
                 s = cabs1(u)
                 if (s /= rzero) then
                    x = half*(h(i - 1,i - 1) - t)
                    sx = cabs1(x)
                    s = max(s,cabs1(x))
                    y = s*sqrt((x/s)**2 + (u/s)**2)
                    if (sx > rzero) then
                       if (real(x/sx,KIND=sp)*real(y,KIND=sp) + aimag(x/sx)*aimag(y) &
                                 < rzero) y = -y
                    end if
                    t = t - u*la_cladiv(u, (x + y))
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 1,l + 1,-1
                 ! determine the effect of starting the single-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.
                 h11 = h(m,m)
                 h22 = h(m + 1,m + 1)
                 h11s = h11 - t
                 h21 = real(h(m + 1,m),KIND=sp)
                 s = cabs1(h11s) + abs(h21)
                 h11s = h11s/s
                 h21 = h21/s
                 v(1) = h11s
                 v(2) = h21
                 h10 = real(h(m,m - 1),KIND=sp)
                 if (abs(h10)*abs(h21) <= ulp*(cabs1(h11s)*(cabs1(h11) + cabs1(h22)))) &
                           go to 70
              end do
              h11 = h(l,l)
              h22 = h(l + 1,l + 1)
              h11s = h11 - t
              h21 = real(h(l + 1,l),KIND=sp)
              s = cabs1(h11s) + abs(h21)
              h11s = h11s/s
              h21 = h21/s
              v(1) = h11s
              v(2) = h21
              70 continue
              ! single-shift qr step
              loop_120: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge cone step toward the bottom of the active
                 ! submatrix.
                 ! v(2) is always real before the call to la_clarfg, and hence
                 ! after the call t2 ( = t1*v(2) ) is also real.
                 if (k > m) call la_ccopy(2,h(k,k - 1),1,v,1)
                 call la_clarfg(2,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = czero
                 end if
                 v2 = v(2)
                 t2 = real(t1*v2,KIND=sp)
                 ! apply g from the left to transform the rows of the matrix
                 ! in columns k to i2.
                 do j = k,i2
                    sum = conjg(t1)*h(k,j) + t2*h(k + 1,j)
                    h(k,j) = h(k,j) - sum
                    h(k + 1,j) = h(k + 1,j) - sum*v2
                 end do
                 ! apply g from the right to transform the columns of the
                 ! matrix in rows i1 to min(k+2,i).
                 do j = i1,min(k + 2,i)
                    sum = t1*h(j,k) + t2*h(j,k + 1)
                    h(j,k) = h(j,k) - sum
                    h(j,k + 1) = h(j,k + 1) - sum*conjg(v2)
                 end do
                 if (wantz) then
                    ! accumulate transformations in the matrix z
                    do j = iloz,ihiz
                       sum = t1*z(j,k) + t2*z(j,k + 1)
                       z(j,k) = z(j,k) - sum
                       z(j,k + 1) = z(j,k + 1) - sum*conjg(v2)
                    end do
                 end if
                 if (k == m .and. m > l) then
                    ! if the qr step was started at row m > l because two
                    ! consecutive small subdiagonals were found, then extra
                    ! scaling must be performed to ensure that h(m,m-1) remains
                    ! real.
                    temp = cone - t1
                    temp = temp/abs(temp)
                    h(m + 1,m) = h(m + 1,m)*conjg(temp)
                    if (m + 2 <= i) h(m + 2,m + 1) = h(m + 2,m + 1)*temp
                    do j = m,i
                       if (j /= m + 1) then
                          if (i2 > j) call la_cscal(i2 - j,temp,h(j,j + 1),ldh)
                          call la_cscal(j - i1,conjg(temp),h(i1,j),1)
                          if (wantz) then
                             call la_cscal(nz,conjg(temp),z(iloz,j),1)
                          end if
                       end if
                    end do
                 end if
              end do loop_120
              ! ensure that h(i,i-1) is real.
              temp = h(i,i - 1)
              if (aimag(temp) /= rzero) then
                 rtemp = abs(temp)
                 h(i,i - 1) = rtemp
                 temp = temp/rtemp
                 if (i2 > i) call la_cscal(i2 - i,conjg(temp),h(i,i + 1),ldh)
                 call la_cscal(i - i1,temp,h(i1,i),1)
                 if (wantz) then
                    call la_cscal(nz,temp,z(iloz,i),1)
                 end if
              end if
           end do loop_130
           ! failure to converge in remaining number of iterations
           info = i
           return
           140 continue
           ! h(i,i-1) is negligible: cone eigenvalue has converged.
           w(i) = h(i,i)
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 30
           150 continue
           return
     end subroutine la_clahqr
     !> ZLAHQR: is an auxiliary routine called by CHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by CHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_zlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,info &
               )
        use la_constants_dp,only:half,czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(dp),intent(out) :: w(*)
        ! =========================================================
           ! Parameters
           real(dp),parameter :: rzero = 0.0_dp
           real(dp),parameter :: rone = 1.0_dp
           real(dp),parameter :: dat1 = 3.0_dp/4.0_dp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           complex(dp) :: cdum,h11,h11s,h22,sc,sum,t,t1,temp,u,v2,x,y
           real(dp) :: aa,ab,ba,bb,h10,h21,rtemp,s,safmax,safmin,smlnum,sx,t2,tst, &
                     ulp
           integer(ilp) :: i,i1,i2,its,itmax,j,jhi,jlo,k,l,m,nh,nz,kdefl
           ! Local Arrays
           complex(dp) :: v(2)
           ! Statement Functions
           real(dp) :: cabs1
           ! Intrinsic Functions
           intrinsic :: abs,real,conjg,aimag,max,min,sqrt
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              w(ilo) = h(ilo,ilo)
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = czero
              h(j + 3,j) = czero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = czero
           ! ==== ensure that subdiagonal entries are real ====
           if (wantt) then
              jlo = 1
              jhi = n
           else
              jlo = ilo
              jhi = ihi
           end if
           do i = ilo + 1,ihi
              if (aimag(h(i,i - 1)) /= rzero) then
                 ! ==== the following redundant normalization
                 ! .    avoids problems with both gradual and
                 ! .    sudden underflow in abs(h(i,i-1)) ====
                 sc = h(i,i - 1)/cabs1(h(i,i - 1))
                 sc = conjg(sc)/abs(sc)
                 h(i,i - 1) = abs(h(i,i - 1))
                 call la_zscal(jhi - i + 1,sc,h(i,i),ldh)
                 call la_zscal(min(jhi,i + 1) - jlo + 1,conjg(sc),h(jlo,i),1)
                 if (wantz) call la_zscal(ihiz - iloz + 1,conjg(sc),z(iloz,i),1)
              end if
           end do
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=dp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo, or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           30 continue
           if (i < ilo) go to 150
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           l = ilo
           loop_130: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (cabs1(h(k,k - 1)) <= smlnum) go to 50
                 tst = cabs1(h(k - 1,k - 1)) + cabs1(h(k,k))
                 if (tst == czero) then
                    if (k - 2 >= ilo) tst = tst + abs(real(h(k - 1,k - 2),KIND=dp))
                    if (k + 1 <= ihi) tst = tst + abs(real(h(k + 1,k),KIND=dp))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some examples.  ====
                 if (abs(real(h(k,k - 1),KIND=dp)) <= ulp*tst) then
                    ab = max(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    ba = min(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    aa = max(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    bb = min(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 50
                 end if
              end do
              50 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = czero
              end if
              ! exit from loop if a submatrix of order 1 has split off.
              if (l >= i) go to 140
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(i,i - 1),KIND=dp))
                 t = s + h(i,i)
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(l + 1,l),KIND=dp))
                 t = s + h(l,l)
              else
                 ! wilkinson's shift.
                 t = h(i,i)
                 u = sqrt(h(i - 1,i))*sqrt(h(i,i - 1))
                 s = cabs1(u)
                 if (s /= rzero) then
                    x = half*(h(i - 1,i - 1) - t)
                    sx = cabs1(x)
                    s = max(s,cabs1(x))
                    y = s*sqrt((x/s)**2 + (u/s)**2)
                    if (sx > rzero) then
                       if (real(x/sx,KIND=dp)*real(y,KIND=dp) + aimag(x/sx)*aimag(y) &
                                 < rzero) y = -y
                    end if
                    t = t - u*la_zladiv(u, (x + y))
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 1,l + 1,-1
                 ! determine the effect of starting the single-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.
                 h11 = h(m,m)
                 h22 = h(m + 1,m + 1)
                 h11s = h11 - t
                 h21 = real(h(m + 1,m),KIND=dp)
                 s = cabs1(h11s) + abs(h21)
                 h11s = h11s/s
                 h21 = h21/s
                 v(1) = h11s
                 v(2) = h21
                 h10 = real(h(m,m - 1),KIND=dp)
                 if (abs(h10)*abs(h21) <= ulp*(cabs1(h11s)*(cabs1(h11) + cabs1(h22)))) &
                           go to 70
              end do
              h11 = h(l,l)
              h22 = h(l + 1,l + 1)
              h11s = h11 - t
              h21 = real(h(l + 1,l),KIND=dp)
              s = cabs1(h11s) + abs(h21)
              h11s = h11s/s
              h21 = h21/s
              v(1) = h11s
              v(2) = h21
              70 continue
              ! single-shift qr step
              loop_120: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge cone step toward the bottom of the active
                 ! submatrix.
                 ! v(2) is always real before the call to la_zlarfg, and hence
                 ! after the call t2 ( = t1*v(2) ) is also real.
                 if (k > m) call la_zcopy(2,h(k,k - 1),1,v,1)
                 call la_zlarfg(2,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = czero
                 end if
                 v2 = v(2)
                 t2 = real(t1*v2,KIND=dp)
                 ! apply g from the left to transform the rows of the matrix
                 ! in columns k to i2.
                 do j = k,i2
                    sum = conjg(t1)*h(k,j) + t2*h(k + 1,j)
                    h(k,j) = h(k,j) - sum
                    h(k + 1,j) = h(k + 1,j) - sum*v2
                 end do
                 ! apply g from the right to transform the columns of the
                 ! matrix in rows i1 to min(k+2,i).
                 do j = i1,min(k + 2,i)
                    sum = t1*h(j,k) + t2*h(j,k + 1)
                    h(j,k) = h(j,k) - sum
                    h(j,k + 1) = h(j,k + 1) - sum*conjg(v2)
                 end do
                 if (wantz) then
                    ! accumulate transformations in the matrix z
                    do j = iloz,ihiz
                       sum = t1*z(j,k) + t2*z(j,k + 1)
                       z(j,k) = z(j,k) - sum
                       z(j,k + 1) = z(j,k + 1) - sum*conjg(v2)
                    end do
                 end if
                 if (k == m .and. m > l) then
                    ! if the qr step was started at row m > l because two
                    ! consecutive small subdiagonals were found, then extra
                    ! scaling must be performed to ensure that h(m,m-1) remains
                    ! real.
                    temp = cone - t1
                    temp = temp/abs(temp)
                    h(m + 1,m) = h(m + 1,m)*conjg(temp)
                    if (m + 2 <= i) h(m + 2,m + 1) = h(m + 2,m + 1)*temp
                    do j = m,i
                       if (j /= m + 1) then
                          if (i2 > j) call la_zscal(i2 - j,temp,h(j,j + 1),ldh)
                          call la_zscal(j - i1,conjg(temp),h(i1,j),1)
                          if (wantz) then
                             call la_zscal(nz,conjg(temp),z(iloz,j),1)
                          end if
                       end if
                    end do
                 end if
              end do loop_120
              ! ensure that h(i,i-1) is real.
              temp = h(i,i - 1)
              if (aimag(temp) /= rzero) then
                 rtemp = abs(temp)
                 h(i,i - 1) = rtemp
                 temp = temp/rtemp
                 if (i2 > i) call la_zscal(i2 - i,conjg(temp),h(i,i + 1),ldh)
                 call la_zscal(i - i1,temp,h(i1,i),1)
                 if (wantz) then
                    call la_zscal(nz,temp,z(iloz,i),1)
                 end if
              end if
           end do loop_130
           ! failure to converge in remaining number of iterations
           info = i
           return
           140 continue
           ! h(i,i-1) is negligible: cone eigenvalue has converged.
           w(i) = h(i,i)
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 30
           150 continue
           return
     end subroutine la_zlahqr
#ifdef LA_WITH_XDP
