              if (aimag(h(i,i - 1)) /= rzero) then
                 ! ==== the following redundant normalization
                 ! .    avoids problems with both gradual and
                 ! .    sudden underflow in abs(h(i,i-1)) ====
                 sc = h(i,i - 1)/cabs1(h(i,i - 1))
                 sc = conjg(sc)/abs(sc)
                 h(i,i - 1) = abs(h(i,i - 1))
                 call la_yscal(jhi - i + 1,sc,h(i,i),ldh)
                 call la_yscal(min(jhi,i + 1) - jlo + 1,conjg(sc),h(jlo,i),1)
                 if (wantz) call la_yscal(ihiz - iloz + 1,conjg(sc),z(iloz,i),1)
              end if
           end do
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=xdp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo, or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           30 continue
           if (i < ilo) go to 150
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           l = ilo
           loop_130: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (cabs1(h(k,k - 1)) <= smlnum) go to 50
                 tst = cabs1(h(k - 1,k - 1)) + cabs1(h(k,k))
                 if (tst == czero) then
                    if (k - 2 >= ilo) tst = tst + abs(real(h(k - 1,k - 2),KIND=xdp))
                    if (k + 1 <= ihi) tst = tst + abs(real(h(k + 1,k),KIND=xdp))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some examples.  ====
                 if (abs(real(h(k,k - 1),KIND=xdp)) <= ulp*tst) then
                    ab = max(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    ba = min(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    aa = max(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    bb = min(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 50
                 end if
              end do
              50 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = czero
              end if
              ! exit from loop if a submatrix of order 1 has split off.
              if (l >= i) go to 140
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(i,i - 1),KIND=xdp))
                 t = s + h(i,i)
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(l + 1,l),KIND=xdp))
                 t = s + h(l,l)
              else
                 ! wilkinson's shift.
                 t = h(i,i)
                 u = sqrt(h(i - 1,i))*sqrt(h(i,i - 1))
                 s = cabs1(u)
                 if (s /= rzero) then
                    x = half*(h(i - 1,i - 1) - t)
                    sx = cabs1(x)
                    s = max(s,cabs1(x))
                    y = s*sqrt((x/s)**2 + (u/s)**2)
                    if (sx > rzero) then
                       if (real(x/sx,KIND=xdp)*real(y,KIND=xdp) + aimag(x/sx)*aimag(y) &
                                 < rzero) y = -y
                    end if
                    t = t - u*la_yladiv(u, (x + y))
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 1,l + 1,-1
                 ! determine the effect of starting the single-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.
                 h11 = h(m,m)
                 h22 = h(m + 1,m + 1)
                 h11s = h11 - t
                 h21 = real(h(m + 1,m),KIND=xdp)
                 s = cabs1(h11s) + abs(h21)
                 h11s = h11s/s
                 h21 = h21/s
                 v(1) = h11s
                 v(2) = h21
                 h10 = real(h(m,m - 1),KIND=xdp)
                 if (abs(h10)*abs(h21) <= ulp*(cabs1(h11s)*(cabs1(h11) + cabs1(h22)))) &
                           go to 70
              end do
              h11 = h(l,l)
              h22 = h(l + 1,l + 1)
              h11s = h11 - t
              h21 = real(h(l + 1,l),KIND=xdp)
              s = cabs1(h11s) + abs(h21)
              h11s = h11s/s
              h21 = h21/s
              v(1) = h11s
              v(2) = h21
              70 continue
              ! single-shift qr step
              loop_120: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge cone step toward the bottom of the active
                 ! submatrix.
                 ! v(2) is always real before the call to la_ylarfg, and hence
                 ! after the call t2 ( = t1*v(2) ) is also real.
                 if (k > m) call la_ycopy(2,h(k,k - 1),1,v,1)
                 call la_ylarfg(2,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = czero
                 end if
                 v2 = v(2)
                 t2 = real(t1*v2,KIND=xdp)
                 ! apply g from the left to transform the rows of the matrix
                 ! in columns k to i2.
                 do j = k,i2
                    sum = conjg(t1)*h(k,j) + t2*h(k + 1,j)
                    h(k,j) = h(k,j) - sum
                    h(k + 1,j) = h(k + 1,j) - sum*v2
                 end do
                 ! apply g from the right to transform the columns of the
                 ! matrix in rows i1 to min(k+2,i).
                 do j = i1,min(k + 2,i)
                    sum = t1*h(j,k) + t2*h(j,k + 1)
                    h(j,k) = h(j,k) - sum
                    h(j,k + 1) = h(j,k + 1) - sum*conjg(v2)
                 end do
                 if (wantz) then
                    ! accumulate transformations in the matrix z
                    do j = iloz,ihiz
                       sum = t1*z(j,k) + t2*z(j,k + 1)
                       z(j,k) = z(j,k) - sum
                       z(j,k + 1) = z(j,k + 1) - sum*conjg(v2)
                    end do
                 end if
                 if (k == m .and. m > l) then
                    ! if the qr step was started at row m > l because two
                    ! consecutive small subdiagonals were found, then extra
                    ! scaling must be performed to ensure that h(m,m-1) remains
                    ! real.
                    temp = cone - t1
                    temp = temp/abs(temp)
                    h(m + 1,m) = h(m + 1,m)*conjg(temp)
                    if (m + 2 <= i) h(m + 2,m + 1) = h(m + 2,m + 1)*temp
                    do j = m,i
                       if (j /= m + 1) then
                          if (i2 > j) call la_yscal(i2 - j,temp,h(j,j + 1),ldh)
                          call la_yscal(j - i1,conjg(temp),h(i1,j),1)
                          if (wantz) then
                             call la_yscal(nz,conjg(temp),z(iloz,j),1)
                          end if
                       end if
                    end do
                 end if
              end do loop_120
              ! ensure that h(i,i-1) is real.
              temp = h(i,i - 1)
              if (aimag(temp) /= rzero) then
                 rtemp = abs(temp)
                 h(i,i - 1) = rtemp
                 temp = temp/rtemp
                 if (i2 > i) call la_yscal(i2 - i,conjg(temp),h(i,i + 1),ldh)
                 call la_yscal(i - i1,temp,h(i1,i),1)
                 if (wantz) then
                    call la_yscal(nz,temp,z(iloz,i),1)
                 end if
              end if
           end do loop_130
           ! failure to converge in remaining number of iterations
           info = i
           return
           140 continue
           ! h(i,i-1) is negligible: cone eigenvalue has converged.
           w(i) = h(i,i)
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 30
           150 continue
           return
     end subroutine la_ylahqr
#endif
#ifdef LA_WITH_QP
     !> WLAHQR: is an auxiliary routine called by ZHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by ZHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_wlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,info &
               )
        use la_constants_qp,only:half,czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(qp),intent(out) :: w(*)
        ! =========================================================
           ! Parameters
           real(qp),parameter :: rzero = 0.0_qp
           real(qp),parameter :: rone = 1.0_qp
           real(qp),parameter :: dat1 = 3.0_qp/4.0_qp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           complex(qp) :: cdum,h11,h11s,h22,sc,sum,t,t1,temp,u,v2,x,y
           real(qp) :: aa,ab,ba,bb,h10,h21,rtemp,s,safmax,safmin,smlnum,sx,t2,tst, &
                     ulp
           integer(ilp) :: i,i1,i2,its,itmax,j,jhi,jlo,k,l,m,nh,nz,kdefl
           ! Local Arrays
           complex(qp) :: v(2)
           ! Statement Functions
           real(qp) :: cabs1
           ! Intrinsic Functions
           intrinsic :: abs,real,conjg,aimag,max,min,sqrt
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=qp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              w(ilo) = h(ilo,ilo)
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = czero
              h(j + 3,j) = czero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = czero
           ! ==== ensure that subdiagonal entries are real ====
           if (wantt) then
              jlo = 1
              jhi = n
           else
              jlo = ilo
              jhi = ihi
           end if
           do i = ilo + 1,ihi
              if (aimag(h(i,i - 1)) /= rzero) then
                 ! ==== the following redundant normalization
                 ! .    avoids problems with both gradual and
                 ! .    sudden underflow in abs(h(i,i-1)) ====
                 sc = h(i,i - 1)/cabs1(h(i,i - 1))
                 sc = conjg(sc)/abs(sc)
                 h(i,i - 1) = abs(h(i,i - 1))
                 call la_wscal(jhi - i + 1,sc,h(i,i),ldh)
                 call la_wscal(min(jhi,i + 1) - jlo + 1,conjg(sc),h(jlo,i),1)
                 if (wantz) call la_wscal(ihiz - iloz + 1,conjg(sc),z(iloz,i),1)
              end if
           end do
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=qp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo, or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           30 continue
           if (i < ilo) go to 150
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           l = ilo
           loop_130: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (cabs1(h(k,k - 1)) <= smlnum) go to 50
                 tst = cabs1(h(k - 1,k - 1)) + cabs1(h(k,k))
                 if (tst == czero) then
                    if (k - 2 >= ilo) tst = tst + abs(real(h(k - 1,k - 2),KIND=qp))
                    if (k + 1 <= ihi) tst = tst + abs(real(h(k + 1,k),KIND=qp))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some examples.  ====
                 if (abs(real(h(k,k - 1),KIND=qp)) <= ulp*tst) then
                    ab = max(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    ba = min(cabs1(h(k,k - 1)),cabs1(h(k - 1,k)))
                    aa = max(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    bb = min(cabs1(h(k,k)),cabs1(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 50
                 end if
              end do
              50 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = czero
              end if
              ! exit from loop if a submatrix of order 1 has split off.
              if (l >= i) go to 140
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(i,i - 1),KIND=qp))
                 t = s + h(i,i)
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = dat1*abs(real(h(l + 1,l),KIND=qp))
                 t = s + h(l,l)
              else
                 ! wilkinson's shift.
                 t = h(i,i)
                 u = sqrt(h(i - 1,i))*sqrt(h(i,i - 1))
                 s = cabs1(u)
                 if (s /= rzero) then
                    x = half*(h(i - 1,i - 1) - t)
                    sx = cabs1(x)
                    s = max(s,cabs1(x))
                    y = s*sqrt((x/s)**2 + (u/s)**2)
                    if (sx > rzero) then
                       if (real(x/sx,KIND=qp)*real(y,KIND=qp) + aimag(x/sx)*aimag(y) &
                                 < rzero) y = -y
                    end if
                    t = t - u*la_wladiv(u, (x + y))
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 1,l + 1,-1
                 ! determine the effect of starting the single-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.
                 h11 = h(m,m)
                 h22 = h(m + 1,m + 1)
                 h11s = h11 - t
                 h21 = real(h(m + 1,m),KIND=qp)
                 s = cabs1(h11s) + abs(h21)
                 h11s = h11s/s
                 h21 = h21/s
                 v(1) = h11s
                 v(2) = h21
                 h10 = real(h(m,m - 1),KIND=qp)
                 if (abs(h10)*abs(h21) <= ulp*(cabs1(h11s)*(cabs1(h11) + cabs1(h22)))) &
                           go to 70
              end do
              h11 = h(l,l)
              h22 = h(l + 1,l + 1)
              h11s = h11 - t
              h21 = real(h(l + 1,l),KIND=qp)
              s = cabs1(h11s) + abs(h21)
              h11s = h11s/s
              h21 = h21/s
              v(1) = h11s
              v(2) = h21
              70 continue
              ! single-shift qr step
              loop_120: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge cone step toward the bottom of the active
                 ! submatrix.
                 ! v(2) is always real before the call to la_wlarfg, and hence
                 ! after the call t2 ( = t1*v(2) ) is also real.
                 if (k > m) call la_wcopy(2,h(k,k - 1),1,v,1)
                 call la_wlarfg(2,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = czero
                 end if
                 v2 = v(2)
                 t2 = real(t1*v2,KIND=qp)
                 ! apply g from the left to transform the rows of the matrix
                 ! in columns k to i2.
                 do j = k,i2
                    sum = conjg(t1)*h(k,j) + t2*h(k + 1,j)
                    h(k,j) = h(k,j) - sum
                    h(k + 1,j) = h(k + 1,j) - sum*v2
                 end do
                 ! apply g from the right to transform the columns of the
                 ! matrix in rows i1 to min(k+2,i).
                 do j = i1,min(k + 2,i)
                    sum = t1*h(j,k) + t2*h(j,k + 1)
                    h(j,k) = h(j,k) - sum
                    h(j,k + 1) = h(j,k + 1) - sum*conjg(v2)
                 end do
                 if (wantz) then
                    ! accumulate transformations in the matrix z
                    do j = iloz,ihiz
                       sum = t1*z(j,k) + t2*z(j,k + 1)
                       z(j,k) = z(j,k) - sum
                       z(j,k + 1) = z(j,k + 1) - sum*conjg(v2)
                    end do
                 end if
                 if (k == m .and. m > l) then
                    ! if the qr step was started at row m > l because two
                    ! consecutive small subdiagonals were found, then extra
                    ! scaling must be performed to ensure that h(m,m-1) remains
                    ! real.
                    temp = cone - t1
                    temp = temp/abs(temp)
                    h(m + 1,m) = h(m + 1,m)*conjg(temp)
                    if (m + 2 <= i) h(m + 2,m + 1) = h(m + 2,m + 1)*temp
                    do j = m,i
                       if (j /= m + 1) then
                          if (i2 > j) call la_wscal(i2 - j,temp,h(j,j + 1),ldh)
                          call la_wscal(j - i1,conjg(temp),h(i1,j),1)
                          if (wantz) then
                             call la_wscal(nz,conjg(temp),z(iloz,j),1)
                          end if
                       end if
                    end do
                 end if
              end do loop_120
              ! ensure that h(i,i-1) is real.
              temp = h(i,i - 1)
              if (aimag(temp) /= rzero) then
                 rtemp = abs(temp)
                 h(i,i - 1) = rtemp
                 temp = temp/rtemp
                 if (i2 > i) call la_wscal(i2 - i,conjg(temp),h(i,i + 1),ldh)
                 call la_wscal(i - i1,temp,h(i1,i),1)
                 if (wantz) then
                    call la_wscal(nz,temp,z(iloz,i),1)
                 end if
              end if
           end do loop_130
           ! failure to converge in remaining number of iterations
           info = i
           return
           140 continue
           ! h(i,i-1) is negligible: cone eigenvalue has converged.
           w(i) = h(i,i)
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 30
           150 continue
           return
     end subroutine la_wlahqr
#endif

     !> CLAQR5: called by CLAQR0 performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_claqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,s,h,ldh,iloz, &
               ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_sp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),s(*),z(ldz,*)
           complex(sp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(sp),parameter :: rzero = 0.0_sp
           real(sp),parameter :: rone = 1.0_sp

           ! Local Scalars
           complex(sp) :: alpha,beta,cdum,refsum
           real(sp) :: h11,h12,h21,h22,safmax,safmin,scl,smlnum,tst1,tst2,ulp
           integer(ilp) :: i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms,krcol, &
                      m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,aimag,conjg,max,min,mod,real
           ! Local Arrays
           complex(sp) :: vt(3)
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by cone.  ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_slamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = czero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_claset('ALL',kdu,kdu,czero,cone,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    cone column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_claqr1(2,h(k + 1,k + 1),ldh,s(2*m22 - 1),s(2*m22),v(1, &
                                 m22))
                       beta = v(1,m22)
                       call la_clarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_clarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = czero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m22))
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = conjg(v(1,m22))*(h(k + 1,j) + conjg(v(2,m22))*h(k + 2,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= czero) then
                          tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                          if (tst1 == rzero) then
                             if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                          end if
                          if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h( &
                                       k + 1,k) = czero
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m22))
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m22))
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_claqr1(3,h(ktop,ktop),ldh,s(2*m - 1),s(2*m),v(1,m) &
                                  )
                       alpha = v(1,m)
                       call la_clarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually czero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*conjg(v(2,m))
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*conjg(v(3,m))
                       ! ==== calculate reflection to move
                       ! .    mth bulge cone step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_clarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= czero .or. h(k + 3,k + 1) /= czero .or. h(k + 3,k + 2) == czero &
                                 ) then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = czero
                          h(k + 3,k) = czero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new cone. ====
                          call la_claqr1(3,h(k + 1,k + 1),ldh,s(2*m - 1),s(2*m),vt)

                          alpha = vt(1)
                          call la_clarfg(3,alpha,vt(2),1,vt(1))
                          refsum = conjg(vt(1))*(h(k + 1,k) + conjg(vt(2))*h(k + 2,k))

                          if (cabs1(h(k + 2,k) - refsum*vt(2)) + cabs1(refsum*vt(3)) > ulp*( &
                          cabs1(h(k,k)) + cabs1(h(k + 1,k + 1)) + cabs1(h(k + 2,k + 2)))) &
                                    then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old cone with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new cone. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m))
                       h(j,k + 3) = h(j,k + 3) - refsum*conjg(v(3,m))
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = conjg(v(1,m))*(h(k + 1,k + 1) + conjg(v(2,m))*h(k + 2,k + 1) + &
                              conjg(v(3,m))*h(k + 3,k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= czero) then
                       tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                       if (tst1 == rzero) then
                          if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                       end if
                       if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h(k + 1, &
                                     k) = czero
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = conjg(v(1,m))*(h(k + 1,j) + conjg(v(2,m))*h(k + 2,j) + &
                                 conjg(v(3,m))*h(k + 3,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m))
                          u(j,kms + 3) = u(j,kms + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m))
                          z(j,k + 3) = z(j,k + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_cgemm('C','N',nu,jlen,nu,cone,u(k1,k1),ldu,h(incol + k1, &
                               jcol),ldh,czero,wh,ldwh)
                    call la_clacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_cgemm('N','N',jlen,nu,nu,cone,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,czero,wv,ldwv)
                    call la_clacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_cgemm('N','N',jlen,nu,nu,cone,z(jrow,incol + k1),ldz, &
                                 u(k1,k1),ldu,czero,wv,ldwv)
                       call la_clacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_claqr5
     !> ZLAQR5:, called by ZLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_zlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,s,h,ldh,iloz, &
               ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_dp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),s(*),z(ldz,*)
           complex(dp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(dp),parameter :: rzero = 0.0_dp
           real(dp),parameter :: rone = 1.0_dp

           ! Local Scalars
           complex(dp) :: alpha,beta,cdum,refsum
           real(dp) :: h11,h12,h21,h22,safmax,safmin,scl,smlnum,tst1,tst2,ulp
           integer(ilp) :: i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms,krcol, &
                      m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,conjg,aimag,max,min,mod
           ! Local Arrays
           complex(dp) :: vt(3)
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by cone.  ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = czero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_zlaset('ALL',kdu,kdu,czero,cone,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    cone column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_zlaqr1(2,h(k + 1,k + 1),ldh,s(2*m22 - 1),s(2*m22),v(1, &
                                 m22))
                       beta = v(1,m22)
                       call la_zlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_zlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = czero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m22))
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = conjg(v(1,m22))*(h(k + 1,j) + conjg(v(2,m22))*h(k + 2,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= czero) then
                          tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                          if (tst1 == rzero) then
                             if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                          end if
                          if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h( &
                                       k + 1,k) = czero
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m22))
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m22))
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_zlaqr1(3,h(ktop,ktop),ldh,s(2*m - 1),s(2*m),v(1,m) &
                                  )
                       alpha = v(1,m)
                       call la_zlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually czero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*conjg(v(2,m))
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*conjg(v(3,m))
                       ! ==== calculate reflection to move
                       ! .    mth bulge cone step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_zlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= czero .or. h(k + 3,k + 1) /= czero .or. h(k + 3,k + 2) == czero &
                                 ) then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = czero
                          h(k + 3,k) = czero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new cone. ====
                          call la_zlaqr1(3,h(k + 1,k + 1),ldh,s(2*m - 1),s(2*m),vt)

                          alpha = vt(1)
                          call la_zlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = conjg(vt(1))*(h(k + 1,k) + conjg(vt(2))*h(k + 2,k))

                          if (cabs1(h(k + 2,k) - refsum*vt(2)) + cabs1(refsum*vt(3)) > ulp*( &
                          cabs1(h(k,k)) + cabs1(h(k + 1,k + 1)) + cabs1(h(k + 2,k + 2)))) &
                                    then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old cone with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new cone. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m))
                       h(j,k + 3) = h(j,k + 3) - refsum*conjg(v(3,m))
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = conjg(v(1,m))*(h(k + 1,k + 1) + conjg(v(2,m))*h(k + 2,k + 1) + &
                              conjg(v(3,m))*h(k + 3,k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= czero) then
                       tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                       if (tst1 == rzero) then
                          if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                       end if
                       if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h(k + 1, &
                                     k) = czero
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = conjg(v(1,m))*(h(k + 1,j) + conjg(v(2,m))*h(k + 2,j) + &
                                 conjg(v(3,m))*h(k + 3,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m))
                          u(j,kms + 3) = u(j,kms + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m))
                          z(j,k + 3) = z(j,k + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_zgemm('C','N',nu,jlen,nu,cone,u(k1,k1),ldu,h(incol + k1, &
                               jcol),ldh,czero,wh,ldwh)
                    call la_zlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_zgemm('N','N',jlen,nu,nu,cone,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,czero,wv,ldwv)
                    call la_zlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_zgemm('N','N',jlen,nu,nu,cone,z(jrow,incol + k1),ldz, &
                                 u(k1,k1),ldu,czero,wv,ldwv)
                       call la_zlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_zlaqr5
#ifdef LA_WITH_XDP
     !> YLAQR5:, called by YLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_ylaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,s,h,ldh,iloz, &
               ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_xdp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(xdp),intent(inout) :: h(ldh,*),s(*),z(ldz,*)
           complex(xdp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(xdp),parameter :: rzero = 0.0_xdp
           real(xdp),parameter :: rone = 1.0_xdp

           ! Local Scalars
           complex(xdp) :: alpha,beta,cdum,refsum
           real(xdp) :: h11,h12,h21,h22,safmax,safmin,scl,smlnum,tst1,tst2,ulp
           integer(ilp) :: i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms,krcol, &
                      m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,conjg,aimag,max,min,mod
           ! Local Arrays
           complex(xdp) :: vt(3)
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=xdp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by cone.  ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = czero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_ylaset('ALL',kdu,kdu,czero,cone,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    cone column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_ylaqr1(2,h(k + 1,k + 1),ldh,s(2*m22 - 1),s(2*m22),v(1, &
                                 m22))
                       beta = v(1,m22)
                       call la_ylarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_ylarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = czero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m22))
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = conjg(v(1,m22))*(h(k + 1,j) + conjg(v(2,m22))*h(k + 2,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= czero) then
                          tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                          if (tst1 == rzero) then
                             if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                          end if
                          if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h( &
                                       k + 1,k) = czero
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m22))
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m22))
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_ylaqr1(3,h(ktop,ktop),ldh,s(2*m - 1),s(2*m),v(1,m) &
                                  )
                       alpha = v(1,m)
                       call la_ylarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually czero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*conjg(v(2,m))
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*conjg(v(3,m))
                       ! ==== calculate reflection to move
                       ! .    mth bulge cone step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_ylarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= czero .or. h(k + 3,k + 1) /= czero .or. h(k + 3,k + 2) == czero &
                                 ) then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = czero
                          h(k + 3,k) = czero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new cone. ====
                          call la_ylaqr1(3,h(k + 1,k + 1),ldh,s(2*m - 1),s(2*m),vt)

                          alpha = vt(1)
                          call la_ylarfg(3,alpha,vt(2),1,vt(1))
                          refsum = conjg(vt(1))*(h(k + 1,k) + conjg(vt(2))*h(k + 2,k))

                          if (cabs1(h(k + 2,k) - refsum*vt(2)) + cabs1(refsum*vt(3)) > ulp*( &
                          cabs1(h(k,k)) + cabs1(h(k + 1,k + 1)) + cabs1(h(k + 2,k + 2)))) &
                                    then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old cone with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new cone. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m))
                       h(j,k + 3) = h(j,k + 3) - refsum*conjg(v(3,m))
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = conjg(v(1,m))*(h(k + 1,k + 1) + conjg(v(2,m))*h(k + 2,k + 1) + &
                              conjg(v(3,m))*h(k + 3,k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= czero) then
                       tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                       if (tst1 == rzero) then
                          if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                       end if
                       if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h(k + 1, &
                                     k) = czero
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = conjg(v(1,m))*(h(k + 1,j) + conjg(v(2,m))*h(k + 2,j) + &
                                 conjg(v(3,m))*h(k + 3,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m))
                          u(j,kms + 3) = u(j,kms + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m))
                          z(j,k + 3) = z(j,k + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_ygemm('C','N',nu,jlen,nu,cone,u(k1,k1),ldu,h(incol + k1, &
                               jcol),ldh,czero,wh,ldwh)
                    call la_ylacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_ygemm('N','N',jlen,nu,nu,cone,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,czero,wv,ldwv)
                    call la_ylacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_ygemm('N','N',jlen,nu,nu,cone,z(jrow,incol + k1),ldz, &
                                 u(k1,k1),ldu,czero,wv,ldwv)
                       call la_ylacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_ylaqr5
#endif
#ifdef LA_WITH_QP
     !> WLAQR5:, called by WLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_wlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,s,h,ldh,iloz, &
               ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        use la_constants_qp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(qp),intent(inout) :: h(ldh,*),s(*),z(ldz,*)
           complex(qp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(qp),parameter :: rzero = 0.0_qp
           real(qp),parameter :: rone = 1.0_qp

           ! Local Scalars
           complex(qp) :: alpha,beta,cdum,refsum
           real(qp) :: h11,h12,h21,h22,safmax,safmin,scl,smlnum,tst1,tst2,ulp
           integer(ilp) :: i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms,krcol, &
                      m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,conjg,aimag,max,min,mod
           ! Local Arrays
           complex(qp) :: vt(3)
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=qp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by cone.  ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = czero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_wlaset('ALL',kdu,kdu,czero,cone,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    cone column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_wlaqr1(2,h(k + 1,k + 1),ldh,s(2*m22 - 1),s(2*m22),v(1, &
                                 m22))
                       beta = v(1,m22)
                       call la_wlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_wlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = czero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m22))
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = conjg(v(1,m22))*(h(k + 1,j) + conjg(v(2,m22))*h(k + 2,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= czero) then
                          tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                          if (tst1 == rzero) then
                             if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                          end if
                          if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                             h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h( &
                                       k + 1,k) = czero
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m22))
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m22))
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_wlaqr1(3,h(ktop,ktop),ldh,s(2*m - 1),s(2*m),v(1,m) &
                                  )
                       alpha = v(1,m)
                       call la_wlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually czero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*conjg(v(2,m))
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*conjg(v(3,m))
                       ! ==== calculate reflection to move
                       ! .    mth bulge cone step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_wlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= czero .or. h(k + 3,k + 1) /= czero .or. h(k + 3,k + 2) == czero &
                                 ) then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = czero
                          h(k + 3,k) = czero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new cone. ====
                          call la_wlaqr1(3,h(k + 1,k + 1),ldh,s(2*m - 1),s(2*m),vt)

                          alpha = vt(1)
                          call la_wlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = conjg(vt(1))*(h(k + 1,k) + conjg(vt(2))*h(k + 2,k))

                          if (cabs1(h(k + 2,k) - refsum*vt(2)) + cabs1(refsum*vt(3)) > ulp*( &
                          cabs1(h(k,k)) + cabs1(h(k + 1,k + 1)) + cabs1(h(k + 2,k + 2)))) &
                                    then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old cone with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new cone. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = czero
                             h(k + 3,k) = czero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*conjg(v(2,m))
                       h(j,k + 3) = h(j,k + 3) - refsum*conjg(v(3,m))
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = conjg(v(1,m))*(h(k + 1,k + 1) + conjg(v(2,m))*h(k + 2,k + 1) + &
                              conjg(v(3,m))*h(k + 3,k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is czero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= czero) then
                       tst1 = cabs1(h(k,k)) + cabs1(h(k + 1,k + 1))
                       if (tst1 == rzero) then
                          if (k >= ktop + 1) tst1 = tst1 + cabs1(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + cabs1(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + cabs1(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + cabs1(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + cabs1(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + cabs1(h(k + 4,k + 1))
                       end if
                       if (cabs1(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h21 = min(cabs1(h(k + 1,k)),cabs1(h(k,k + 1)))
                          h11 = max(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          h22 = min(cabs1(h(k + 1,k + 1)),cabs1(h(k,k) - h(k + 1,k + 1)))

                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == rzero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) h(k + 1, &
                                     k) = czero
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = conjg(v(1,m))*(h(k + 1,j) + conjg(v(2,m))*h(k + 2,j) + &
                                 conjg(v(3,m))*h(k + 3,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*conjg(v(2,m))
                          u(j,kms + 3) = u(j,kms + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*conjg(v(2,m))
                          z(j,k + 3) = z(j,k + 3) - refsum*conjg(v(3,m))
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_wgemm('C','N',nu,jlen,nu,cone,u(k1,k1),ldu,h(incol + k1, &
                               jcol),ldh,czero,wh,ldwh)
                    call la_wlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_wgemm('N','N',jlen,nu,nu,cone,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,czero,wv,ldwv)
                    call la_wlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_wgemm('N','N',jlen,nu,nu,cone,z(jrow,incol + k1),ldz, &
                                 u(k1,k1),ldu,czero,wv,ldwv)
                       call la_wlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_wlaqr5
#endif

     !> CLAQZ1: chases a 1x1 shift bulge in a matrix pencil down a single position

     pure subroutine la_claqz1(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_sp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(sp) :: c
           complex(sp) :: s,temp
           if (k + 1 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              call la_clartg(b(ihi,ihi),b(ihi,ihi - 1),c,s,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = czero
              call la_crot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c,s)

              call la_crot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c,s)

              if (ilz) then
                 call la_crot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c,s)

              end if
           else
              ! normal operation, move bulge down
              ! apply transformation from the right
              call la_clartg(b(k + 1,k + 1),b(k + 1,k),c,s,temp)
              b(k + 1,k + 1) = temp
              b(k + 1,k) = czero
              call la_crot(k + 2 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c,s)

              call la_crot(k - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c,s)

              if (ilz) then
                 call la_crot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c,s)

              end if
              ! apply transformation from the left
              call la_clartg(a(k + 1,k),a(k + 2,k),c,s,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = czero
              call la_crot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c,s)
              call la_crot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c,s)
              if (ilq) then
                 call la_crot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c,conjg( &
                            s))
              end if
           end if
     end subroutine la_claqz1
     !> ZLAQZ1: chases a 1x1 shift bulge in a matrix pencil down a single position

     pure subroutine la_zlaqz1(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
        use la_constants_dp
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           complex(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(dp) :: c
           complex(dp) :: s,temp
           if (k + 1 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              call la_zlartg(b(ihi,ihi),b(ihi,ihi - 1),c,s,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = czero
              call la_zrot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c,s)

              call la_zrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c,s)

              if (ilz) then
                 call la_zrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c,s)

              end if
           else
              ! normal operation, move bulge down
              ! apply transformation from the right
              call la_zlartg(b(k + 1,k + 1),b(k + 1,k),c,s,temp)
              b(k + 1,k + 1) = temp
              b(k + 1,k) = czero
              call la_zrot(k + 2 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c,s)

              call la_zrot(k - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c,s)

              if (ilz) then
                 call la_zrot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c,s)

              end if
              ! apply transformation from the left
              call la_zlartg(a(k + 1,k),a(k + 2,k),c,s,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = czero
              call la_zrot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c,s)
              call la_zrot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c,s)
              if (ilq) then
                 call la_zrot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c,conjg( &
                            s))
              end if
           end if
     end subroutine la_zlaqz1
