     !> CLAQZ3: Executes a single multishift QZ sweep

     pure subroutine la_claqz3(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,alpha, &
                beta,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_sp,only:one,czero,cone
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),alpha(*),beta(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(sp) :: safmin,safmax,c,scale
           complex(sp) :: temp,temp2,temp3,s
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('CLAQZ3',-info)
              return
           end if
           ! executable statements
           ! get machine constants
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ns = nshifts
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_claset('FULL',ns + 1,ns + 1,czero,cone,qc,ldqc)
           call la_claset('FULL',ns,ns,czero,cone,zc,ldzc)
           do i = 1,ns
              ! introduce the shift
              scale = sqrt(abs(alpha(i)))*sqrt(abs(beta(i)))
              if (scale >= safmin .and. scale <= safmax) then
                 alpha(i) = alpha(i)/scale
                 beta(i) = beta(i)/scale
              end if
              temp2 = beta(i)*a(ilo,ilo) - alpha(i)*b(ilo,ilo)
              temp3 = beta(i)*a(ilo + 1,ilo)
              if (abs(temp2) > safmax .or. abs(temp3) > safmax) then
                 temp2 = cone
                 temp3 = czero
              end if
              call la_clartg(temp2,temp3,c,s,temp)
              call la_crot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c,s)
              call la_crot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c,s)
              call la_crot(ns + 1,qc(1,1),1,qc(1,2),1,c,conjg(s))
              ! chase the shift down
              do j = 1,ns - i
                 call la_claqz1(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ilo,ilo + &
                        ns),lda,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ilo,ilo + &
                        ns),ldb,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_cgemm('N','N',n,sheight,sheight,cone,q(1,ilo),ldq,qc,ldqc, &
                        czero,work,n)
              call la_clacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_cgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ilo),lda, &
                        zc,ldzc,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_cgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ilo),ldb, &
                        zc,ldzc,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_cgemm('N','N',n,swidth,swidth,cone,z(1,ilo),ldz,zc,ldzc, &
                        czero,work,n)
              call la_clacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_claset('FULL',ns + np,ns + np,czero,cone,qc,ldqc)
              call la_claset('FULL',ns + np,ns + np,czero,cone,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-1
                 do j = 0,np - 1
                    ! move down the block with index k+i+j, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_claqz1(.true.,.true.,k + i + j,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,czero,work,sheight)
                 call la_clacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,czero,work,sheight)
                 call la_clacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_cgemm('N','N',n,nblock,nblock,cone,q(1,k + 1),ldq,qc,ldqc, &
                           czero,work,n)
                 call la_clacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_cgemm('N','N',sheight,swidth,swidth,cone,a(istartm,k),lda, &
                           zc,ldzc,czero,work,sheight)
                 call la_clacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_cgemm('N','N',sheight,swidth,swidth,cone,b(istartm,k),ldb, &
                           zc,ldzc,czero,work,sheight)
                 call la_clacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_cgemm('N','N',n,nblock,nblock,cone,z(1,k),ldz,zc,ldzc, &
                           czero,work,n)
                 call la_clacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_claset('FULL',ns,ns,czero,cone,qc,ldqc)
           call la_claset('FULL',ns + 1,ns + 1,czero,cone,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i,ihi - 1
                 call la_claqz1(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_cgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_cgemm('N','N',n,ns,ns,cone,q(1,ihi - ns + 1),ldq,qc,ldqc,czero, &
                         work,n)
              call la_clacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_cgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ihi - ns), &
                        lda,zc,ldzc,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_cgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ihi - ns), &
                        ldb,zc,ldzc,czero,work,sheight)
              call la_clacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_cgemm('N','N',n,ns + 1,ns + 1,cone,z(1,ihi - ns),ldz,zc,ldzc, &
                        czero,work,n)
              call la_clacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_claqz3
     !> ZLAQZ3: Executes a single multishift QZ sweep

     pure subroutine la_zlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,alpha, &
                beta,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_dp,only:one,czero,cone
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           complex(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),alpha(*),beta(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(dp) :: safmin,safmax,c,scale
           complex(dp) :: temp,temp2,temp3,s
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('ZLAQZ3',-info)
              return
           end if
           ! executable statements
           ! get machine constants
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ns = nshifts
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_zlaset('FULL',ns + 1,ns + 1,czero,cone,qc,ldqc)
           call la_zlaset('FULL',ns,ns,czero,cone,zc,ldzc)
           do i = 1,ns
              ! introduce the shift
              scale = sqrt(abs(alpha(i)))*sqrt(abs(beta(i)))
              if (scale >= safmin .and. scale <= safmax) then
                 alpha(i) = alpha(i)/scale
                 beta(i) = beta(i)/scale
              end if
              temp2 = beta(i)*a(ilo,ilo) - alpha(i)*b(ilo,ilo)
              temp3 = beta(i)*a(ilo + 1,ilo)
              if (abs(temp2) > safmax .or. abs(temp3) > safmax) then
                 temp2 = cone
                 temp3 = czero
              end if
              call la_zlartg(temp2,temp3,c,s,temp)
              call la_zrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c,s)
              call la_zrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c,s)
              call la_zrot(ns + 1,qc(1,1),1,qc(1,2),1,c,conjg(s))
              ! chase the shift down
              do j = 1,ns - i
                 call la_zlaqz1(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ilo,ilo + &
                        ns),lda,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ilo,ilo + &
                        ns),ldb,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_zgemm('N','N',n,sheight,sheight,cone,q(1,ilo),ldq,qc,ldqc, &
                        czero,work,n)
              call la_zlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_zgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ilo),lda, &
                        zc,ldzc,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_zgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ilo),ldb, &
                        zc,ldzc,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_zgemm('N','N',n,swidth,swidth,cone,z(1,ilo),ldz,zc,ldzc, &
                        czero,work,n)
              call la_zlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_zlaset('FULL',ns + np,ns + np,czero,cone,qc,ldqc)
              call la_zlaset('FULL',ns + np,ns + np,czero,cone,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-1
                 do j = 0,np - 1
                    ! move down the block with index k+i+j, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_zlaqz1(.true.,.true.,k + i + j,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,czero,work,sheight)
                 call la_zlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,czero,work,sheight)
                 call la_zlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_zgemm('N','N',n,nblock,nblock,cone,q(1,k + 1),ldq,qc,ldqc, &
                           czero,work,n)
                 call la_zlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_zgemm('N','N',sheight,swidth,swidth,cone,a(istartm,k),lda, &
                           zc,ldzc,czero,work,sheight)
                 call la_zlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_zgemm('N','N',sheight,swidth,swidth,cone,b(istartm,k),ldb, &
                           zc,ldzc,czero,work,sheight)
                 call la_zlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_zgemm('N','N',n,nblock,nblock,cone,z(1,k),ldz,zc,ldzc, &
                           czero,work,n)
                 call la_zlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_zlaset('FULL',ns,ns,czero,cone,qc,ldqc)
           call la_zlaset('FULL',ns + 1,ns + 1,czero,cone,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i,ihi - 1
                 call la_zlaqz1(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_zgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_zgemm('N','N',n,ns,ns,cone,q(1,ihi - ns + 1),ldq,qc,ldqc,czero, &
                         work,n)
              call la_zlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_zgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ihi - ns), &
                        lda,zc,ldzc,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_zgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ihi - ns), &
                        ldb,zc,ldzc,czero,work,sheight)
              call la_zlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_zgemm('N','N',n,ns + 1,ns + 1,cone,z(1,ihi - ns),ldz,zc,ldzc, &
                        czero,work,n)
              call la_zlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_zlaqz3
#ifdef LA_WITH_XDP
     !> YLAQZ3: Executes a single multishift QZ sweep

     pure subroutine la_ylaqz3(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,alpha, &
                beta,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_xdp,only:one,czero,cone
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           complex(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),alpha(*),beta(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(xdp) :: safmin,safmax,c,scale
           complex(xdp) :: temp,temp2,temp3,s
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('YLAQZ3',-info)
              return
           end if
           ! executable statements
           ! get machine constants
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ns = nshifts
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_ylaset('FULL',ns + 1,ns + 1,czero,cone,qc,ldqc)
           call la_ylaset('FULL',ns,ns,czero,cone,zc,ldzc)
           do i = 1,ns
              ! introduce the shift
              scale = sqrt(abs(alpha(i)))*sqrt(abs(beta(i)))
              if (scale >= safmin .and. scale <= safmax) then
                 alpha(i) = alpha(i)/scale
                 beta(i) = beta(i)/scale
              end if
              temp2 = beta(i)*a(ilo,ilo) - alpha(i)*b(ilo,ilo)
              temp3 = beta(i)*a(ilo + 1,ilo)
              if (abs(temp2) > safmax .or. abs(temp3) > safmax) then
                 temp2 = cone
                 temp3 = czero
              end if
              call la_ylartg(temp2,temp3,c,s,temp)
              call la_yrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c,s)
              call la_yrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c,s)
              call la_yrot(ns + 1,qc(1,1),1,qc(1,2),1,c,conjg(s))
              ! chase the shift down
              do j = 1,ns - i
                 call la_ylaqz1(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ilo,ilo + &
                        ns),lda,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ilo,ilo + &
                        ns),ldb,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_ygemm('N','N',n,sheight,sheight,cone,q(1,ilo),ldq,qc,ldqc, &
                        czero,work,n)
              call la_ylacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_ygemm('N','N',sheight,swidth,swidth,cone,a(istartm,ilo),lda, &
                        zc,ldzc,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_ygemm('N','N',sheight,swidth,swidth,cone,b(istartm,ilo),ldb, &
                        zc,ldzc,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_ygemm('N','N',n,swidth,swidth,cone,z(1,ilo),ldz,zc,ldzc, &
                        czero,work,n)
              call la_ylacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_ylaset('FULL',ns + np,ns + np,czero,cone,qc,ldqc)
              call la_ylaset('FULL',ns + np,ns + np,czero,cone,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-1
                 do j = 0,np - 1
                    ! move down the block with index k+i+j, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_ylaqz1(.true.,.true.,k + i + j,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,czero,work,sheight)
                 call la_ylacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,czero,work,sheight)
                 call la_ylacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_ygemm('N','N',n,nblock,nblock,cone,q(1,k + 1),ldq,qc,ldqc, &
                           czero,work,n)
                 call la_ylacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_ygemm('N','N',sheight,swidth,swidth,cone,a(istartm,k),lda, &
                           zc,ldzc,czero,work,sheight)
                 call la_ylacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_ygemm('N','N',sheight,swidth,swidth,cone,b(istartm,k),ldb, &
                           zc,ldzc,czero,work,sheight)
                 call la_ylacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_ygemm('N','N',n,nblock,nblock,cone,z(1,k),ldz,zc,ldzc, &
                           czero,work,n)
                 call la_ylacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_ylaset('FULL',ns,ns,czero,cone,qc,ldqc)
           call la_ylaset('FULL',ns + 1,ns + 1,czero,cone,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i,ihi - 1
                 call la_ylaqz1(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_ygemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_ygemm('N','N',n,ns,ns,cone,q(1,ihi - ns + 1),ldq,qc,ldqc,czero, &
                         work,n)
              call la_ylacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_ygemm('N','N',sheight,swidth,swidth,cone,a(istartm,ihi - ns), &
                        lda,zc,ldzc,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_ygemm('N','N',sheight,swidth,swidth,cone,b(istartm,ihi - ns), &
                        ldb,zc,ldzc,czero,work,sheight)
              call la_ylacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_ygemm('N','N',n,ns + 1,ns + 1,cone,z(1,ihi - ns),ldz,zc,ldzc, &
                        czero,work,n)
              call la_ylacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_ylaqz3
#endif
#ifdef LA_WITH_QP
     !> WLAQZ3: Executes a single multishift QZ sweep

     pure subroutine la_wlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_desired,alpha, &
                beta,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
        use la_constants_qp,only:one,czero,cone
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_desired,ldqc,ldzc
           complex(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),alpha(*),beta(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(qp) :: safmin,safmax,c,scale
           complex(qp) :: temp,temp2,temp3,s
           info = 0
           if (nblock_desired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_desired
              return
           else if (lwork < n*nblock_desired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('WLAQZ3',-info)
              return
           end if
           ! executable statements
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ns = nshifts
           npos = max(nblock_desired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_wlaset('FULL',ns + 1,ns + 1,czero,cone,qc,ldqc)
           call la_wlaset('FULL',ns,ns,czero,cone,zc,ldzc)
           do i = 1,ns
              ! introduce the shift
              scale = sqrt(abs(alpha(i)))*sqrt(abs(beta(i)))
              if (scale >= safmin .and. scale <= safmax) then
                 alpha(i) = alpha(i)/scale
                 beta(i) = beta(i)/scale
              end if
              temp2 = beta(i)*a(ilo,ilo) - alpha(i)*b(ilo,ilo)
              temp3 = beta(i)*a(ilo + 1,ilo)
              if (abs(temp2) > safmax .or. abs(temp3) > safmax) then
                 temp2 = cone
                 temp3 = czero
              end if
              call la_wlartg(temp2,temp3,c,s,temp)
              call la_wrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c,s)
              call la_wrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c,s)
              call la_wrot(ns + 1,qc(1,1),1,qc(1,2),1,c,conjg(s))
              ! chase the shift down
              do j = 1,ns - i
                 call la_wlaqz1(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ilo,ilo + &
                        ns),lda,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ilo,ilo + &
                        ns),ldb,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_wgemm('N','N',n,sheight,sheight,cone,q(1,ilo),ldq,qc,ldqc, &
                        czero,work,n)
              call la_wlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_wgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ilo),lda, &
                        zc,ldzc,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_wgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ilo),ldb, &
                        zc,ldzc,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_wgemm('N','N',n,swidth,swidth,cone,z(1,ilo),ldz,zc,ldzc, &
                        czero,work,n)
              call la_wlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_wlaset('FULL',ns + np,ns + np,czero,cone,qc,ldqc)
              call la_wlaset('FULL',ns + np,ns + np,czero,cone,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-1
                 do j = 0,np - 1
                    ! move down the block with index k+i+j, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_wlaqz1(.true.,.true.,k + i + j,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,czero,work,sheight)
                 call la_wlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,czero,work,sheight)
                 call la_wlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_wgemm('N','N',n,nblock,nblock,cone,q(1,k + 1),ldq,qc,ldqc, &
                           czero,work,n)
                 call la_wlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_wgemm('N','N',sheight,swidth,swidth,cone,a(istartm,k),lda, &
                           zc,ldzc,czero,work,sheight)
                 call la_wlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_wgemm('N','N',sheight,swidth,swidth,cone,b(istartm,k),ldb, &
                           zc,ldzc,czero,work,sheight)
                 call la_wlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_wgemm('N','N',n,nblock,nblock,cone,z(1,k),ldz,zc,ldzc, &
                           czero,work,n)
                 call la_wlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_wlaset('FULL',ns,ns,czero,cone,qc,ldqc)
           call la_wlaset('FULL',ns + 1,ns + 1,czero,cone,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i,ihi - 1
                 call la_wlaqz1(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_wgemm('C','N',sheight,swidth,sheight,cone,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_wgemm('N','N',n,ns,ns,cone,q(1,ihi - ns + 1),ldq,qc,ldqc,czero, &
                         work,n)
              call la_wlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_wgemm('N','N',sheight,swidth,swidth,cone,a(istartm,ihi - ns), &
                        lda,zc,ldzc,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_wgemm('N','N',sheight,swidth,swidth,cone,b(istartm,ihi - ns), &
                        ldb,zc,ldzc,czero,work,sheight)
              call la_wlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_wgemm('N','N',n,ns + 1,ns + 1,cone,z(1,ihi - ns),ldz,zc,ldzc, &
                        czero,work,n)
              call la_wlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_wlaqz3
#endif

     !> CLAQR2: is identical to CLAQR3 except that it avoids
     !> recursion by calling CLAHQR instead of CLAQR4.
     !> Aggressive early deflation:
     !> This subroutine accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_claqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_sp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(sp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(sp),parameter :: rzero = 0.0_sp
           real(sp),parameter :: rone = 1.0_sp

           ! Local Scalars
           complex(sp) :: beta,cdum,s,tau
           real(sp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwkopt
           ! Intrinsic Functions
           intrinsic :: abs,aimag,cmplx,conjg,int,max,min,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_cgehrd ====
              call la_cgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_cunmhr ====
              call la_cunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=sp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_slamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_clacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_ccopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_claset('A',jw,jw,czero,cone,v,ldv)
           call la_clahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                     infqr)
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ctrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ctrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ctrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_ccopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_clarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_claset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_clarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_clarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_clarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_cgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_clacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_ccopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_cunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_cgemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_clacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_cgemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_clacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_cgemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_clacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=sp)
     end subroutine la_claqr2
     !> ZLAQR2: is identical to ZLAQR3 except that it avoids
     !> recursion by calling ZLAHQR instead of ZLAQR4.
     !> Aggressive early deflation:
     !> ZLAQR2 accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_zlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_dp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(dp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(dp),parameter :: rzero = 0.0_dp
           real(dp),parameter :: rone = 1.0_dp

           ! Local Scalars
           complex(dp) :: beta,cdum,s,tau
           real(dp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwkopt
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,conjg,aimag,int,max,min
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_zgehrd ====
              call la_zgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_zunmhr ====
              call la_zunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=dp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_zlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_zcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_zlaset('A',jw,jw,czero,cone,v,ldv)
           call la_zlahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                     infqr)
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ztrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ztrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ztrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_zcopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_zlarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_zlaset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_zlarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_zlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_zlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_zgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_zlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_zcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_zunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_zgemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_zlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_zgemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_zlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_zgemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_zlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=dp)
     end subroutine la_zlaqr2
#ifdef LA_WITH_XDP
     !> YLAQR2: is identical to YLAQR3 except that it avoids
     !> recursion by calling YLAHQR instead of YLAQR4.
     !> Aggressive early deflation:
     !> YLAQR2 accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
