              call la_yunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=xdp)
