           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_ylacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_ycopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_ylaset('A',jw,jw,czero,cone,v,ldv)
           call la_ylahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                     infqr)
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ytrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ytrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ytrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_ycopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_ylarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_ylaset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_ylarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_ylarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_ylarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_ygehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_ylacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_ycopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_yunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_ygemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_ylacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_ygemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_ylacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_ygemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_ylacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=xdp)
     end subroutine la_ylaqr2
#endif
#ifdef LA_WITH_QP
     !> WLAQR2: is identical to WLAQR3 except that it avoids
     !> recursion by calling WLAHQR instead of WLAQR4.
     !> Aggressive early deflation:
     !> WLAQR2 accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_wlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_qp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(qp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(qp),parameter :: rzero = 0.0_qp
           real(qp),parameter :: rone = 1.0_qp

           ! Local Scalars
           complex(qp) :: beta,cdum,s,tau
           real(qp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwkopt
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,conjg,aimag,int,max,min
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=qp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_wgehrd ====
              call la_wgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_wunmhr ====
              call la_wunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=qp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_wlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_wcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_wlaset('A',jw,jw,czero,cone,v,ldv)
           call la_wlahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                     infqr)
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_wtrexc can not fail in this case.) ====
                 ifst = ns
                 call la_wtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_wtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_wcopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_wlarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_wlaset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_wlarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_wlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_wlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_wgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_wlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_wcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_wunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_wgemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_wlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_wgemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_wlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_wgemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_wlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=qp)
     end subroutine la_wlaqr2
#endif

     !> CLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_claqr0(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(sp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(sp),parameter :: wilk1 = 0.75_sp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_clahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(sp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(sp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(sp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,aimag,cmplx,int,max,min,mod,real,sqrt
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_clahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_clahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'CLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'CLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_claqr3 ====
              call la_claqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_claqr5, la_claqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=sp)
                 return
              end if
              ! ==== la_clahqr/la_claqr0 crossover point ====
              nmin = la_ilaenv(12,'CLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'CLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'CLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_claqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_claqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_claqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_claqr4 or
                       ! .    la_clahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_clacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_claqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_clahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_claqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=sp)
     end subroutine la_claqr0
     !> ZLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_zlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(dp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(dp),parameter :: wilk1 = 0.75_dp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_zlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(dp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(dp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(dp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_zlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_zlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'ZLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'ZLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_zlaqr3 ====
              call la_zlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_zlaqr5, la_zlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=dp)
                 return
              end if
              ! ==== la_zlahqr/la_zlaqr0 crossover point ====
              nmin = la_ilaenv(12,'ZLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'ZLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'ZLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_zlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_zlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_zlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_zlaqr4 or
                       ! .    la_zlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_zlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_zlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_zlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_zlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=dp)
     end subroutine la_zlaqr0
#ifdef LA_WITH_XDP
     !> YLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_ylaqr0(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(xdp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(xdp),parameter :: wilk1 = 0.75_xdp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_ylahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(xdp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(xdp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(xdp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=xdp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_ylahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_ylahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'YLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'YLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_ylaqr3 ====
              call la_ylaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_ylaqr5, la_ylaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=xdp)
                 return
              end if
              ! ==== la_ylahqr/la_ylaqr0 crossover point ====
              nmin = la_ilaenv(12,'YLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'YLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'YLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_ylaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_ylaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_ylaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_ylaqr4 or
                       ! .    la_ylahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_ylacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_ylaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_ylahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_ylaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=xdp)
     end subroutine la_ylaqr0
#endif
#ifdef LA_WITH_QP
     !> WLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_wlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(qp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_wlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(qp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(qp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=qp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_wlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_wlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'WLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'WLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_wlaqr3 ====
              call la_wlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_wlaqr5, la_wlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=qp)
                 return
              end if
              ! ==== la_wlahqr/la_wlaqr0 crossover point ====
              nmin = la_ilaenv(12,'WLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'WLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'WLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_wlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_wlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_wlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_wlaqr4 or
                       ! .    la_wlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_wlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_wlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_wlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w( &
                                       ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_wlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=qp)
     end subroutine la_wlaqr0
#endif

     !> Aggressive early deflation:
     !> CLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_claqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_sp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(sp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(sp),parameter :: rzero = 0.0_sp
           real(sp),parameter :: rone = 1.0_sp

           ! Local Scalars
           complex(sp) :: beta,cdum,s,tau
           real(sp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwk3,lwkopt,nmin
           ! Intrinsic Functions
           intrinsic :: abs,aimag,cmplx,conjg,int,max,min,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_cgehrd ====
              call la_cgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_cunmhr ====
              call la_cunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_claqr4 ====
              call la_claqr4(.true.,.true.,jw,1,jw,t,ldt,sh,1,jw,v,ldv,work,-1, &
                        infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=sp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_slamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_clacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_ccopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_claset('A',jw,jw,czero,cone,v,ldv)
           nmin = la_ilaenv(12,'CLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_claqr4(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        work,lwork,infqr)
           else
              call la_clahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        infqr)
           end if
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ctrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ctrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ctrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_ccopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_clarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_claset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_clarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_clarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_clarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_cgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_clacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_ccopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_cunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_cgemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_clacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_cgemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_clacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_cgemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_clacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=sp)
     end subroutine la_claqr3
     !> Aggressive early deflation:
     !> ZLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_zlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_dp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(dp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(dp),parameter :: rzero = 0.0_dp
           real(dp),parameter :: rone = 1.0_dp

           ! Local Scalars
           complex(dp) :: beta,cdum,s,tau
           real(dp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwk3,lwkopt,nmin
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,conjg,aimag,int,max,min
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_zgehrd ====
              call la_zgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_zunmhr ====
              call la_zunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_zlaqr4 ====
              call la_zlaqr4(.true.,.true.,jw,1,jw,t,ldt,sh,1,jw,v,ldv,work,-1, &
                        infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=dp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_zlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_zcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_zlaset('A',jw,jw,czero,cone,v,ldv)
           nmin = la_ilaenv(12,'ZLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_zlaqr4(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        work,lwork,infqr)
           else
              call la_zlahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        infqr)
           end if
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ztrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ztrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ztrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_zcopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_zlarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_zlaset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_zlarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_zlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_zlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_zgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_zlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_zcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_zunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_zgemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_zlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_zgemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_zlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_zgemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_zlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=dp)
     end subroutine la_zlaqr3
#ifdef LA_WITH_XDP
     !> Aggressive early deflation:
     !> YLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an unitary similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     pure subroutine la_ylaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
               ns,nd,sh,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        use la_constants_xdp,only:czero,cone
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(xdp),intent(out) :: sh(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================
           ! Parameters
           real(xdp),parameter :: rzero = 0.0_xdp
           real(xdp),parameter :: rone = 1.0_xdp

           ! Local Scalars
           complex(xdp) :: beta,cdum,s,tau
           real(xdp) :: foo,safmax,safmin,smlnum,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,kcol,kln,knt,krow,kwtop,ltop, &
                     lwk1,lwk2,lwk3,lwkopt,nmin
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,conjg,aimag,int,max,min
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=xdp)) + abs(aimag(cdum))
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_ygehrd ====
              call la_ygehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_yunmhr ====
              call la_yunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_ylaqr4 ====
              call la_ylaqr4(.true.,.true.,jw,1,jw,t,ldt,sh,1,jw,v,ldv,work,-1, &
                        infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = cmplx(lwkopt,0,KIND=xdp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = cone
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = rone/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = czero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sh(kwtop) = h(kwtop,kwtop)
              ns = 1
              nd = 0
              if (cabs1(s) <= max(smlnum,ulp*cabs1(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = czero
              end if
              work(1) = cone
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_ylacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_ycopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_ylaset('A',jw,jw,czero,cone,v,ldv)
           nmin = la_ilaenv(12,'YLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_ylaqr4(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        work,lwork,infqr)
           else
              call la_ylahqr(.true.,.true.,jw,1,jw,t,ldt,sh(kwtop),1,jw,v,ldv, &
                        infqr)
           end if
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           do knt = infqr + 1,jw
              ! ==== small spike tip deflation test ====
              foo = cabs1(t(ns,ns))
              if (foo == rzero) foo = cabs1(s)
              if (cabs1(s)*cabs1(v(1,ns)) <= max(smlnum,ulp*foo)) then
                 ! ==== cone more converged eigenvalue ====
                 ns = ns - 1
              else
                 ! ==== cone undeflatable eigenvalue.  move it up out of the
                 ! .    way.   (la_ytrexc can not fail in this case.) ====
                 ifst = ns
                 call la_ytrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)
                 ilst = ilst + 1
              end if
           end do
              ! ==== return to hessenberg form ====
           if (ns == 0) s = czero
           if (ns < jw) then
              ! ==== sorting the diagonal of t improves accuracy for
              ! .    graded matrices.  ====
              do i = infqr + 1,ns
                 ifst = i
                 do j = i + 1,ns
                    if (cabs1(t(j,j)) > cabs1(t(ifst,ifst))) ifst = j
                 end do
                 ilst = i
                 if (ifst /= ilst) call la_ytrexc('V',jw,t,ldt,v,ldv,ifst,ilst,info)

              end do
           end if
           ! ==== restore shift/eigenvalue array from t ====
           do i = infqr + 1,jw
              sh(kwtop + i - 1) = t(i,i)
           end do
           if (ns < jw .or. s == czero) then
              if (ns > 1 .and. s /= czero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_ycopy(ns,v,ldv,work,1)
                 do i = 1,ns
                    work(i) = conjg(work(i))
                 end do
                 beta = work(1)
                 call la_ylarfg(ns,beta,work(2),1,tau)
                 work(1) = cone
                 call la_ylaset('L',jw - 2,jw - 2,czero,czero,t(3,1),ldt)
                 call la_ylarf('L',ns,jw,work,1,conjg(tau),t,ldt,work(jw + 1))

                 call la_ylarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_ylarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_ygehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*conjg(v(1,1))
              call la_ylacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_ycopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= czero) call la_yunmhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_ygemm('N','N',kln,jw,jw,cone,h(krow,kwtop),ldh,v,ldv, &
                           czero,wv,ldwv)
                 call la_ylacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_ygemm('C','N',jw,kln,jw,cone,v,ldv,h(kwtop,kcol),ldh, &
                              czero,t,ldt)
                    call la_ylacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_ygemm('N','N',kln,jw,jw,cone,z(krow,kwtop),ldz,v,ldv, &
                              czero,wv,ldwv)
                    call la_ylacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = cmplx(lwkopt,0,KIND=xdp)
     end subroutine la_ylaqr3
#endif
#ifdef LA_WITH_QP
     !> Aggressive early deflation:
     !> WLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an unitary similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
