              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_wunmhr ====
              call la_wunmhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_wlaqr4 ====
              call la_wlaqr4(.true.,.true.,jw,1,jw,t,ldt,sh,1,jw,v,ldv,work,-1, &
                        infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
