           ! .    here and there to keep track.) ====
           call la_wlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_wcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_wlaset('A',jw,jw,czero,cone,v,ldv)
           nmin = la_ilaenv(12,'WLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
