     end subroutine la_wlaqr3
#endif

     !> CLAQR4: implements one level of recursion for CLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by CLAQR0 and, for large enough
     !> deflation window size, it may be called by CLAQR3.  This
     !> subroutine is identical to CLAQR0 except that it calls CLAQR2
     !> instead of CLAQR3.
     !> CLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_claqr4(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(sp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(sp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(sp),parameter :: wilk1 = 0.75_sp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_clahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(sp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(sp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(sp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,aimag,cmplx,int,max,min,mod,real,sqrt
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=sp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_clahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_clahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'CLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'CLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_claqr2 ====
              call la_claqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_claqr5, la_claqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=sp)
                 return
              end if
              ! ==== la_clahqr/la_claqr0 crossover point ====
              nmin = la_ilaenv(12,'CLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'CLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'CLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_claqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_claqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_claqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_clahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_clacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_clahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w(ks) &
                                    ,1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_claqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=sp)
     end subroutine la_claqr4
     !> ZLAQR4: implements one level of recursion for ZLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by ZLAQR0 and, for large enough
     !> deflation window size, it may be called by ZLAQR3.  This
     !> subroutine is identical to ZLAQR0 except that it calls ZLAQR2
     !> instead of ZLAQR3.
     !> ZLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_zlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_dp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(dp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(dp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(dp),parameter :: wilk1 = 0.75_dp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_zlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(dp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(dp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(dp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(dp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=dp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_zlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_zlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'ZLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'ZLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_zlaqr2 ====
              call la_zlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_zlaqr5, la_zlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=dp)
                 return
              end if
              ! ==== la_zlahqr/la_zlaqr0 crossover point ====
              nmin = la_ilaenv(12,'ZLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'ZLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'ZLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_zlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_zlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_zlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_zlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_zlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_zlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w(ks) &
                                    ,1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_zlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=dp)
     end subroutine la_zlaqr4
#ifdef LA_WITH_XDP
     !> YLAQR4: implements one level of recursion for YLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by YLAQR0 and, for large enough
     !> deflation window size, it may be called by YLAQR3.  This
     !> subroutine is identical to YLAQR0 except that it calls YLAQR2
     !> instead of YLAQR3.
     !> YLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_ylaqr4(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_xdp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(xdp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(xdp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(xdp),parameter :: wilk1 = 0.75_xdp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_ylahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(xdp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(xdp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(xdp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=xdp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_ylahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_ylahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'YLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'YLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_ylaqr2 ====
              call la_ylaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_ylaqr5, la_ylaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=xdp)
                 return
              end if
              ! ==== la_ylahqr/la_ylaqr0 crossover point ====
              nmin = la_ilaenv(12,'YLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'YLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'YLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_ylaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_ylaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_ylaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_ylahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_ylacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_ylahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w(ks) &
                                    ,1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_ylaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=xdp)
     end subroutine la_ylaqr4
#endif
#ifdef LA_WITH_QP
     !> WLAQR4: implements one level of recursion for WLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by WLAQR0 and, for large enough
     !> deflation window size, it may be called by WLAQR3.  This
     !> subroutine is identical to WLAQR0 except that it calls WLAQR2
     !> instead of WLAQR3.
     !> WLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**H, where T is an upper triangular matrix (the
     !> Schur form), and Z is the unitary matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input unitary
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the unitary matrix Q:  A = Q*H*Q**H = (QZ)*H*(QZ)**H.

     pure subroutine la_wlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz,z,ldz,work, &
                lwork,info)
        use la_constants_qp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           complex(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           complex(qp),intent(out) :: w(*),work(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_wlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constant wilk1 is used to form the exceptional
           ! .    shifts. ====

           ! Local Scalars
           complex(qp) :: aa,bb,cc,cdum,dd,det,rtdisc,swap,tr2
           real(qp) :: s
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           complex(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,cmplx,aimag,int,max,min,mod,sqrt
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(cdum) = abs(real(cdum,KIND=qp)) + abs(aimag(cdum))
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = cone
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_wlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_wlahqr(wantt,wantz,n,ilo,ihi,h,ldh,w,iloz,ihiz, &
                        z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'WLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'WLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_wlaqr2 ====
              call la_wlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,w,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_wlaqr5, la_wlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = cmplx(lwkopt,0,KIND=qp)
                 return
              end if
              ! ==== la_wlahqr/la_wlaqr0 crossover point ====
              nmin = la_ilaenv(12,'WLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'WLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'WLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_70: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 80
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == czero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (cabs1(h(kwtop,kwtop - 1)) > cabs1(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_wlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,w,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh,work, &
                           lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_wlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_wlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,ks + 1,-2
                          w(i) = h(i,i) + wilk1*cabs1(h(i,i - 1))
                          w(i - 1) = w(i)
                       end do
                    else
                       ! ==== got ns/2 or fewer shifts? use la_wlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_wlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_wlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,w(ks) &
                                    ,1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  scale to avoid
                          ! .    overflows, underflows and subnormals.
                          ! .    (the scale factor s can not be czero,
                          ! .    because h(kbot,kbot-1) is nonzero.) ====
                          if (ks >= kbot) then
                             s = cabs1(h(kbot - 1,kbot - 1)) + cabs1(h(kbot,kbot - 1)) + cabs1( &
                                       h(kbot - 1,kbot)) + cabs1(h(kbot,kbot))
                             aa = h(kbot - 1,kbot - 1)/s
                             cc = h(kbot,kbot - 1)/s
                             bb = h(kbot - 1,kbot)/s
                             dd = h(kbot,kbot)/s
                             tr2 = (aa + dd)/two
                             det = (aa - tr2)*(dd - tr2) - bb*cc
                             rtdisc = sqrt(-det)
                             w(kbot - 1) = (tr2 + rtdisc)*s
                             w(kbot) = (tr2 - rtdisc)*s
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little) ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (cabs1(w(i)) < cabs1(w(i + 1))) then
                                   sorted = .false.
                                   swap = w(i)
                                   w(i) = w(i + 1)
                                   w(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                    end if
                    ! ==== if there are only two shifts, then use
                    ! .    only cone.  ====
                    if (kbot - ks + 1 == 2) then
                       if (cabs1(w(kbot) - h(kbot,kbot)) < cabs1(w(kbot - 1) - h(kbot,kbot)) &
                                  ) then
                          w(kbot - 1) = w(kbot)
                       else
                          w(kbot) = w(kbot - 1)
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping cone to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_wlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,w(ks),h,ldh, &
                    iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh,nho,h(ku, &
                               kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_70
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              80 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = cmplx(lwkopt,0,KIND=qp)
     end subroutine la_wlaqr4
#endif

     !> CLAQZ0: computes the eigenvalues of a matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a matrix pair (A,B):
     !> A = Q1*H*Z1**H,  B = Q1*T*Z1**H,
     !> as computed by CGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**H,  T = Q*P*Z**H,
     !> where Q and Z are unitary matrices, P and S are an upper triangular
     !> matrices.
     !> Optionally, the unitary matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> unitary matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the unitary matrices from CGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the unitary factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**H,  B = (Q1*Q)*P*(Z1*Z)**H.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_claqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha, &
               beta,q,ldq,z,ldz,work,lwork,rwork,rec,info)
        use la_constants_sp,only:zero,one,czero,cone
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*),work(*)
           real(sp),intent(out) :: rwork(*)

           ! local scalars
           real(sp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(sp) :: eshift,s1,temp
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('CLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=sp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'CLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'CLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'CLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'CLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'CLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=sp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_chgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                         ldq,z,ldz,work,lwork,rwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_claqz2
           nw = max(nwr,nmin)
           call la_claqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alpha,beta,work,nw,work,nw,work,-1,rwork,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_claqz3
           call la_claqz3(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alpha,beta,a,lda,b, &
                     ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=sp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('CLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_claset('FULL',n,n,czero,cone,q,ldq)
           if (iwantz == 3) call la_claset('FULL',n,n,czero,cone,z,ldz)
           ! get machine constants
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 30*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + abs( &
                        a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = czero
                 istop = istop - 1
                 ld = 0
                 eshift = czero
              end if
              ! check deflations at the start
              if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart)) + &
                        abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = czero
                 istart = istart + 1
                 ld = 0
                 eshift = czero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = czero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 tempr = zero
                 if (k < istop) then
                    tempr = tempr + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    tempr = tempr + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*tempr)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_clartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = czero
                       call la_crot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_crot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_crot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_clartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = czero
                          call la_crot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_crot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_crot(n,q(1,k2),1,q(1,k2 + 1),1,c1,conjg(s1))

                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_clartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = czero
                       call la_crot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_crot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_crot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,conjg( &
                                     s1))
                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = czero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using la_chgeqz because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_claqz2(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alpha,beta,work,nw,work(nw**2 + 1),nw,work( &
                         2*nw**2 + 1),lwork - 2*nw**2,rwork,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = czero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=sp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + cone/(safmin*real(maxit,KIND=sp))
                 end if
                 alpha(shiftpos) = cone
                 beta(shiftpos) = eshift
                 ns = 1
              end if
              ! time for a qz sweep
              call la_claqz3(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alpha( &
              shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz,work,nblock,work( &
                        nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2,sweep_info)
           end do
           ! call la_chgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_chgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_chgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                  ldq,z,ldz,work,lwork,rwork,norm_info)
           info = norm_info
     end subroutine la_claqz0
     !> ZLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**H,  B = Q1*T*Z1**H,
     !> as computed by ZGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**H,  T = Q*P*Z**H,
     !> where Q and Z are unitary matrices, P and S are an upper triangular
     !> matrices.
     !> Optionally, the unitary matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> unitary matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the unitary matrices from ZGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the unitary factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**H,  B = (Q1*Q)*P*(Z1*Z)**H.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_zlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha, &
               beta,q,ldq,z,ldz,work,lwork,rwork,rec,info)
        use la_constants_dp,only:zero,one,czero,cone
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           complex(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*),work(*)
           real(dp),intent(out) :: rwork(*)

           ! local scalars
           real(dp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(dp) :: eshift,s1,temp
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('ZLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=dp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'ZLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'ZLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'ZLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'ZLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'ZLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=dp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_zhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                         ldq,z,ldz,work,lwork,rwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_zlaqz2
           nw = max(nwr,nmin)
           call la_zlaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alpha,beta,work,nw,work,nw,work,-1,rwork,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_zlaqz3
           call la_zlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alpha,beta,a,lda,b, &
                     ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=dp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('ZLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_zlaset('FULL',n,n,czero,cone,q,ldq)
           if (iwantz == 3) call la_zlaset('FULL',n,n,czero,cone,z,ldz)
           ! get machine constants
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 30*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + abs( &
                        a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = czero
                 istop = istop - 1
                 ld = 0
                 eshift = czero
              end if
              ! check deflations at the start
              if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart)) + &
                        abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = czero
                 istart = istart + 1
                 ld = 0
                 eshift = czero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = czero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 tempr = zero
                 if (k < istop) then
                    tempr = tempr + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    tempr = tempr + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*tempr)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_zlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = czero
                       call la_zrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_zrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_zrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_zlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = czero
                          call la_zrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_zrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_zrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,conjg(s1))

                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_zlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = czero
                       call la_zrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_zrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_zrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,conjg( &
                                     s1))
                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = czero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using qz_small because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_zlaqz2(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alpha,beta,work,nw,work(nw**2 + 1),nw,work( &
                         2*nw**2 + 1),lwork - 2*nw**2,rwork,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = czero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=dp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + cone/(safmin*real(maxit,KIND=dp))
                 end if
                 alpha(shiftpos) = cone
                 beta(shiftpos) = eshift
                 ns = 1
              end if
              ! time for a qz sweep
              call la_zlaqz3(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alpha( &
              shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz,work,nblock,work( &
                        nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2,sweep_info)
           end do
           ! call la_zhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_zhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_zhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                  ldq,z,ldz,work,lwork,rwork,norm_info)
           info = norm_info
     end subroutine la_zlaqz0
#ifdef LA_WITH_XDP
     !> YLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**H,  B = Q1*T*Z1**H,
     !> as computed by YGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**H,  T = Q*P*Z**H,
     !> where Q and Z are unitary matrices, P and S are an upper triangular
     !> matrices.
     !> Optionally, the unitary matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> unitary matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the unitary matrices from YGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the unitary factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**H,  B = (Q1*Q)*P*(Z1*Z)**H.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_ylaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha, &
               beta,q,ldq,z,ldz,work,lwork,rwork,rec,info)
        use la_constants_xdp,only:zero,one,czero,cone
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           complex(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*),work(*)
           real(xdp),intent(out) :: rwork(*)

           ! local scalars
           real(xdp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(xdp) :: eshift,s1,temp
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('YLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=xdp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'YLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'YLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'YLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'YLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'YLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=xdp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_yhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                         ldq,z,ldz,work,lwork,rwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_ylaqz2
           nw = max(nwr,nmin)
           call la_ylaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alpha,beta,work,nw,work,nw,work,-1,rwork,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_ylaqz3
           call la_ylaqz3(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alpha,beta,a,lda,b, &
                     ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=xdp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('YLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_ylaset('FULL',n,n,czero,cone,q,ldq)
           if (iwantz == 3) call la_ylaset('FULL',n,n,czero,cone,z,ldz)
           ! get machine constants
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 30*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + abs( &
                        a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = czero
                 istop = istop - 1
                 ld = 0
                 eshift = czero
              end if
              ! check deflations at the start
              if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart)) + &
                        abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = czero
                 istart = istart + 1
                 ld = 0
                 eshift = czero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = czero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 tempr = zero
                 if (k < istop) then
                    tempr = tempr + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    tempr = tempr + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*tempr)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_ylartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = czero
                       call la_yrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_yrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_yrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_ylartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = czero
                          call la_yrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_yrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_yrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,conjg(s1))

                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_ylartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = czero
                       call la_yrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_yrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_yrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,conjg( &
                                     s1))
                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = czero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using qz_small because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_ylaqz2(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alpha,beta,work,nw,work(nw**2 + 1),nw,work( &
                         2*nw**2 + 1),lwork - 2*nw**2,rwork,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = czero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=xdp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + cone/(safmin*real(maxit,KIND=xdp))
                 end if
                 alpha(shiftpos) = cone
                 beta(shiftpos) = eshift
                 ns = 1
              end if
              ! time for a qz sweep
              call la_ylaqz3(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alpha( &
              shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz,work,nblock,work( &
                        nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2,sweep_info)
           end do
           ! call la_yhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_yhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_yhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                  ldq,z,ldz,work,lwork,rwork,norm_info)
           info = norm_info
     end subroutine la_ylaqz0
#endif
#ifdef LA_WITH_QP
     !> WLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**H,  B = Q1*T*Z1**H,
     !> as computed by WGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**H,  T = Q*P*Z**H,
     !> where Q and Z are unitary matrices, P and S are an upper triangular
     !> matrices.
     !> Optionally, the unitary matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> unitary matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the unitary matrices from WGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the unitary factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**H,  B = (Q1*Q)*P*(Z1*Z)**H.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_wlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha, &
               beta,q,ldq,z,ldz,work,lwork,rwork,rec,info)
        use la_constants_qp,only:zero,one,czero,cone
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           complex(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*),work(*)
           real(qp),intent(out) :: rwork(*)

           ! local scalars
           real(qp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(qp) :: eshift,s1,temp
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_deflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('WLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=qp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'WLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'WLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'WLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'WLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'WLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=qp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_whgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                         ldq,z,ldz,work,lwork,rwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_wlaqz2
           nw = max(nwr,nmin)
           call la_wlaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_deflated,alpha,beta,work,nw,work,nw,work,-1,rwork,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_wlaqz3
           call la_wlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alpha,beta,a,lda,b, &
                     ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=qp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('WLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_wlaset('FULL',n,n,czero,cone,q,ldq)
           if (iwantz == 3) call la_wlaset('FULL',n,n,czero,cone,z,ldz)
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 30*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + abs( &
                        a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = czero
                 istop = istop - 1
                 ld = 0
                 eshift = czero
              end if
              ! check deflations at the start
              if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart)) + &
                        abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = czero
                 istart = istart + 1
                 ld = 0
                 eshift = czero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = czero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 tempr = zero
                 if (k < istop) then
                    tempr = tempr + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    tempr = tempr + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*tempr)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_wlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = czero
                       call la_wrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_wrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_wrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_wlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = czero
                          call la_wrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_wrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_wrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,conjg(s1))

                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_wlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = czero
                       call la_wrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_wrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_wrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,conjg( &
                                     s1))
                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = czero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using qz_small because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_wlaqz2(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_deflated,alpha,beta,work,nw,work(nw**2 + 1),nw,work( &
                         2*nw**2 + 1),lwork - 2*nw**2,rwork,rec,aed_info)
              if (n_deflated > 0) then
                 istop = istop - n_deflated
                 ld = 0
                 eshift = czero
              end if
              if (100*n_deflated > nibble*(n_deflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_deflated - n_undeflated + 1
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=qp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + cone/(safmin*real(maxit,KIND=qp))
                 end if
                 alpha(shiftpos) = cone
                 beta(shiftpos) = eshift
                 ns = 1
              end if
              ! time for a qz sweep
              call la_wlaqz3(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alpha( &
              shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz,work,nblock,work( &
                        nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2,sweep_info)
           end do
           ! call la_whgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_whgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80 call la_whgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alpha,beta,q, &
                  ldq,z,ldz,work,lwork,rwork,norm_info)
           info = norm_info
     end subroutine la_wlaqz0
#endif

     !> CLAQZ2: performs AED

     recursive subroutine la_claqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alpha,beta,qc,ldqc,zc,ldzc,work,lwork,rwork,rec,info)
        use la_constants_sp,only:zero,one,czero,cone
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           complex(sp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           complex(sp),intent(out) :: work(*)
           real(sp),intent(out) :: rwork(*)

           ! local scalars
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,ctgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(sp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(sp) :: s,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = czero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_claqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alpha,beta,qc,ldqc,zc,ldzc,work,-1,rwork,rec + 1,qz_small_info)
           lworkreq = int(work(1),KIND=ilp) + 2*jw**2
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('CLAQZ2',-info)
              return
           end if
           ! get machine constants
           safmin = la_slamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_slabad(safmin,safmax)
           ulp = la_slamch('PRECISION')
           smlnum = safmin*(real(n,KIND=sp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alpha(kwtop) = a(kwtop,kwtop)
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = czero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_clacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_clacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_claset('FULL',jw,jw,czero,cone,qc,ldqc)
           call la_claset('FULL',jw,jw,czero,cone,zc,ldzc)
           call la_claqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alpha,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rwork,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_clacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_clacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == czero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                    ! try to deflate eigenvalue
                    tempr = abs(a(kwbot,kwbot))
                    if (tempr == zero) then
                       tempr = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*tempr,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_ctgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                                 kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,ctgexc_info)
                       k2 = k2 + 1
                    end if
                    k = k + 1
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              alpha(k) = a(k,k)
              beta(k) = b(k,k)
              k = k + 1
           end do
           if (kwtop /= ilo .and. s /= czero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*conjg(qc(1,1:jw - nd))
              do k = kwbot - 1,kwtop,-1
                 call la_clartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = czero
                 k2 = max(kwtop,k - 1)
                 call la_crot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_crot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_crot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,conjg( &
                           s1))
              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 ! move bulge down and remove it
                 do k2 = k,kwbot - 1
                    call la_claqz1(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                              ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                 end do
                 k = k - 1
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_cgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,czero,work,jw)
              call la_clacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_cgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,czero,work,jw)
              call la_clacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_cgemm('N','N',n,jw,jw,cone,q(1,kwtop),ldq,qc,ldqc,czero, &
                        work,n)
              call la_clacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_cgemm('N','N',kwtop - istartm,jw,jw,cone,a(istartm,kwtop),lda, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_clacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop) &
                       ,lda)
              call la_cgemm('N','N',kwtop - istartm,jw,jw,cone,b(istartm,kwtop),ldb, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_clacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop) &
                       ,ldb)
           end if
           if (ilz) then
              call la_cgemm('N','N',n,jw,jw,cone,z(1,kwtop),ldz,zc,ldzc,czero, &
                        work,n)
              call la_clacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_claqz2
     !> ZLAQZ2: performs AED

     recursive subroutine la_zlaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alpha,beta,qc,ldqc,zc,ldzc,work,lwork,rwork,rec,info)
        use la_constants_dp,only:zero,one,czero,cone
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           complex(dp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           complex(dp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           complex(dp),intent(out) :: work(*)
           real(dp),intent(out) :: rwork(*)

           ! local scalars
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,ztgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(dp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(dp) :: s,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = czero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_zlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alpha,beta,qc,ldqc,zc,ldzc,work,-1,rwork,rec + 1,qz_small_info)
           lworkreq = int(work(1),KIND=ilp) + 2*jw**2
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('ZLAQZ2',-info)
              return
           end if
           ! get machine constants
           safmin = la_dlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_dlabad(safmin,safmax)
           ulp = la_dlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=dp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alpha(kwtop) = a(kwtop,kwtop)
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = czero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_zlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_zlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_zlaset('FULL',jw,jw,czero,cone,qc,ldqc)
           call la_zlaset('FULL',jw,jw,czero,cone,zc,ldzc)
           call la_zlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alpha,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rwork,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_zlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_zlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == czero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                    ! try to deflate eigenvalue
                    tempr = abs(a(kwbot,kwbot))
                    if (tempr == zero) then
                       tempr = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*tempr,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_ztgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                                 kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,ztgexc_info)
                       k2 = k2 + 1
                    end if
                    k = k + 1
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              alpha(k) = a(k,k)
              beta(k) = b(k,k)
              k = k + 1
           end do
           if (kwtop /= ilo .and. s /= czero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*conjg(qc(1,1:jw - nd))
              do k = kwbot - 1,kwtop,-1
                 call la_zlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = czero
                 k2 = max(kwtop,k - 1)
                 call la_zrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_zrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_zrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,conjg( &
                           s1))
              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 ! move bulge down and remove it
                 do k2 = k,kwbot - 1
                    call la_zlaqz1(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                              ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                 end do
                 k = k - 1
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_zgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,czero,work,jw)
              call la_zlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_zgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,czero,work,jw)
              call la_zlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_zgemm('N','N',n,jw,jw,cone,q(1,kwtop),ldq,qc,ldqc,czero, &
                        work,n)
              call la_zlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_zgemm('N','N',kwtop - istartm,jw,jw,cone,a(istartm,kwtop),lda, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_zlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop) &
                       ,lda)
              call la_zgemm('N','N',kwtop - istartm,jw,jw,cone,b(istartm,kwtop),ldb, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_zlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop) &
                       ,ldb)
           end if
           if (ilz) then
              call la_zgemm('N','N',n,jw,jw,cone,z(1,kwtop),ldz,zc,ldzc,czero, &
                        work,n)
              call la_zlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_zlaqz2
#ifdef LA_WITH_XDP
     !> YLAQZ2: performs AED

     recursive subroutine la_ylaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alpha,beta,qc,ldqc,zc,ldzc,work,lwork,rwork,rec,info)
        use la_constants_xdp,only:zero,one,czero,cone
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           complex(xdp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           complex(xdp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           complex(xdp),intent(out) :: work(*)
           real(xdp),intent(out) :: rwork(*)

           ! local scalars
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,ytgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(xdp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(xdp) :: s,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = czero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_ylaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alpha,beta,qc,ldqc,zc,ldzc,work,-1,rwork,rec + 1,qz_small_info)
           lworkreq = int(work(1),KIND=ilp) + 2*jw**2
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('YLAQZ2',-info)
              return
           end if
           ! get machine constants
           safmin = la_xlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_xlabad(safmin,safmax)
           ulp = la_xlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=xdp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alpha(kwtop) = a(kwtop,kwtop)
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = czero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_ylacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_ylacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_ylaset('FULL',jw,jw,czero,cone,qc,ldqc)
           call la_ylaset('FULL',jw,jw,czero,cone,zc,ldzc)
           call la_ylaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alpha,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rwork,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_ylacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_ylacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == czero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                    ! try to deflate eigenvalue
                    tempr = abs(a(kwbot,kwbot))
                    if (tempr == zero) then
                       tempr = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*tempr,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_ytgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                                 kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,ytgexc_info)
                       k2 = k2 + 1
                    end if
                    k = k + 1
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              alpha(k) = a(k,k)
              beta(k) = b(k,k)
              k = k + 1
           end do
           if (kwtop /= ilo .and. s /= czero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*conjg(qc(1,1:jw - nd))
              do k = kwbot - 1,kwtop,-1
                 call la_ylartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = czero
                 k2 = max(kwtop,k - 1)
                 call la_yrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_yrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_yrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,conjg( &
                           s1))
              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 ! move bulge down and remove it
                 do k2 = k,kwbot - 1
                    call la_ylaqz1(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                              ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                 end do
                 k = k - 1
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_ygemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,czero,work,jw)
              call la_ylacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_ygemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,czero,work,jw)
              call la_ylacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_ygemm('N','N',n,jw,jw,cone,q(1,kwtop),ldq,qc,ldqc,czero, &
                        work,n)
              call la_ylacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_ygemm('N','N',kwtop - istartm,jw,jw,cone,a(istartm,kwtop),lda, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_ylacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop) &
                       ,lda)
              call la_ygemm('N','N',kwtop - istartm,jw,jw,cone,b(istartm,kwtop),ldb, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_ylacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop) &
                       ,ldb)
           end if
           if (ilz) then
              call la_ygemm('N','N',n,jw,jw,cone,z(1,kwtop),ldz,zc,ldzc,czero, &
                        work,n)
              call la_ylacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_ylaqz2
#endif
#ifdef LA_WITH_QP
     !> WLAQZ2: performs AED

     recursive subroutine la_wlaqz2(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alpha,beta,qc,ldqc,zc,ldzc,work,lwork,rwork,rec,info)
        use la_constants_qp,only:zero,one,czero,cone
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           complex(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*), &
                     alpha(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           complex(qp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           complex(qp),intent(out) :: work(*)
           real(qp),intent(out) :: rwork(*)

           ! local scalars
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,wtgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(qp) :: smlnum,ulp,safmin,safmax,c1,tempr
           complex(qp) :: s,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = czero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_wlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alpha,beta,qc,ldqc,zc,ldzc,work,-1,rwork,rec + 1,qz_small_info)
           lworkreq = int(work(1),KIND=ilp) + 2*jw**2
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('WLAQZ2',-info)
              return
           end if
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alpha(kwtop) = a(kwtop,kwtop)
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = czero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_wlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_wlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_wlaset('FULL',jw,jw,czero,cone,qc,ldqc)
           call la_wlaset('FULL',jw,jw,czero,cone,zc,ldzc)
           call la_wlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alpha,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rwork,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_wlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_wlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == czero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                    ! try to deflate eigenvalue
                    tempr = abs(a(kwbot,kwbot))
                    if (tempr == zero) then
                       tempr = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*tempr,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_wtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                                 kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,wtgexc_info)
                       k2 = k2 + 1
                    end if
                    k = k + 1
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              alpha(k) = a(k,k)
              beta(k) = b(k,k)
              k = k + 1
           end do
           if (kwtop /= ilo .and. s /= czero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*conjg(qc(1,1:jw - nd))
              do k = kwbot - 1,kwtop,-1
                 call la_wlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = czero
                 k2 = max(kwtop,k - 1)
                 call la_wrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_wrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_wrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,conjg( &
                           s1))
              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 ! move bulge down and remove it
                 do k2 = k,kwbot - 1
                    call la_wlaqz1(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                              ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                 end do
                 k = k - 1
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_wgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,czero,work,jw)
              call la_wlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_wgemm('C','N',jw,istopm - ihi,jw,cone,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,czero,work,jw)
              call la_wlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_wgemm('N','N',n,jw,jw,cone,q(1,kwtop),ldq,qc,ldqc,czero, &
                        work,n)
              call la_wlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_wgemm('N','N',kwtop - istartm,jw,jw,cone,a(istartm,kwtop),lda, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_wlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop) &
                       ,lda)
              call la_wgemm('N','N',kwtop - istartm,jw,jw,cone,b(istartm,kwtop),ldb, &
                        zc,ldzc,czero,work,kwtop - istartm)
             call la_wlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop) &
                       ,ldb)
           end if
           if (ilz) then
              call la_wgemm('N','N',n,jw,jw,cone,z(1,kwtop),ldz,zc,ldzc,czero, &
                        work,n)
              call la_wlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_wlaqz2
